const OPERATOR_CREDENTIAL_MIN_ITERATIONS: u32 = 100_000;
const OPERATOR_CREDENTIAL_MAX_ITERATIONS: u32 = 2_000_000;
const OPERATOR_PASSWORD_MIN_CHARACTERS: usize = 8;
const OPERATOR_PASSWORD_MAX_BYTES: usize = 1_024;

fn parented_file_dialog(window: &WebviewWindow) -> rfd::FileDialog {
    // rfd treats failed raw-window/display handle acquisition as no parent,
    // preserving the existing dialog behavior when a native handle is unavailable.
    rfd::FileDialog::new().set_parent(window)
}

#[tauri::command]
fn select_gdtf_file(window: WebviewWindow) -> Option<String> {
    parented_file_dialog(&window)
        .add_filter("GDTF Fixture", &["gdtf"])
        .pick_file()
        .map(|path| path.to_string_lossy().to_string())
}

#[tauri::command]
fn select_video_source_file(
    window: WebviewWindow,
    kind: VideoSourceKind,
) -> Result<Option<String>, String> {
    let (label, extensions) = video_source_file_dialog_filter(&kind)?;
    Ok(parented_file_dialog(&window)
        .add_filter(label, extensions)
        .pick_file()
        .map(|path| path.to_string_lossy().to_string()))
}

#[tauri::command]
fn select_video_source_files(
    window: WebviewWindow,
    kind: VideoSourceKind,
) -> Result<Vec<String>, String> {
    let (label, extensions) = video_source_file_dialog_filter(&kind)?;
    Ok(parented_file_dialog(&window)
        .add_filter(label, extensions)
        .pick_files()
        .unwrap_or_default()
        .into_iter()
        .map(|path| path.to_string_lossy().to_string())
        .collect())
}

#[tauri::command]
fn select_video_isf_file(window: WebviewWindow) -> Result<Option<VideoIsfEffectSummary>, String> {
    let Some(path) = parented_file_dialog(&window)
        .add_filter("Interactive Shader Format", ISF_FILE_EXTENSIONS)
        .pick_file()
    else {
        return Ok(None);
    };
    load_video_isf_effect_from_path(&path).map(Some)
}

fn load_video_isf_effect_from_path(path: &Path) -> Result<VideoIsfEffectSummary, String> {
    let source = fs::read_to_string(path)
        .map_err(|error| format!("Failed to read ISF shader '{}': {error}", path.display()))?;
    let prepared = video::prepare_isf_shader(&source).map_err(|error| error.to_string())?;
    let label = path
        .file_stem()
        .and_then(OsStr::to_str)
        .map(str::trim)
        .filter(|label| !label.is_empty())
        .unwrap_or("ISF Filter")
        .to_string();
    Ok(video::isf_effect_from_prepared(
        label,
        source,
        Some(path.to_string_lossy().to_string()),
        &prepared,
    ))
}

#[tauri::command]
fn import_video_output_bitmap_mask(
    window: WebviewWindow,
) -> Result<Option<VideoBitmapMaskImportResult>, String> {
    let Some(path) = parented_file_dialog(&window)
        .add_filter("Luma Mask Image", &["png", "jpg", "jpeg"])
        .pick_file()
    else {
        return Ok(None);
    };
    let (width, height, words) =
        video::load_video_bitmap_mask(&path).map_err(|error| format!("{error:?}"))?;
    Ok(Some(VideoBitmapMaskImportResult {
        width,
        height,
        luma_words: words.to_vec(),
        source_name: path
            .file_name()
            .and_then(OsStr::to_str)
            .unwrap_or("mask image")
            .to_string(),
    }))
}

#[tauri::command]
fn import_gdtf(path: String) -> Result<FixtureProfileSummary, String> {
    // Import is a session preview. The profile becomes project persistence only
    // when a successful Patch/Repair publication explicitly embeds it.
    import_gdtf_from_path(path)
}

#[tauri::command]
fn load_gdtf_wheel_media(
    path: String,
    media: String,
) -> Result<Option<GdtfWheelMediaPayload>, String> {
    if path.starts_with("memory://") || path.starts_with("snapshot://") {
        return Ok(None);
    }
    let mime_type = gdtf_wheel_media_mime_type(&media).to_string();
    gdtf::load_wheel_media(path, &media)
        .map(|bytes| bytes.map(|bytes| GdtfWheelMediaPayload { bytes, mime_type }))
        .map_err(|error| error.to_string())
}

fn gdtf_wheel_media_mime_type(media: &str) -> &'static str {
    let normalized = media.trim().to_ascii_lowercase();
    if normalized.ends_with(".jpg") || normalized.ends_with(".jpeg") {
        "image/jpeg"
    } else if normalized.ends_with(".webp") {
        "image/webp"
    } else if normalized.ends_with(".svg") {
        "image/svg+xml"
    } else {
        "image/png"
    }
}

