#[tauri::command]
fn add_timeline_cue_event(
    state: State<'_, AppState>,
    cue_id: CueId,
    time_ms: u64,
    time_beats: Option<f64>,
    track: TimelineTrackKind,
    layer_id: Option<u32>,
) -> Result<TimelineEventId, String> {
    validate_timeline_time_beats("Timeline cue event", time_beats)?;
    let snapshot = state.engine.snapshot();
    if !snapshot.cues.iter().any(|cue| cue.id == cue_id) {
        return Err(format!("Cue {cue_id} was not found"));
    }
    let event_id = state.engine.allocate_timeline_event_id();
    state
        .engine
        .add_timeline_cue_event_published(event_id, cue_id, time_ms, time_beats, track, layer_id)?;
    Ok(event_id)
}

#[tauri::command]
fn set_timeline_cue_event(
    state: State<'_, AppState>,
    event_id: TimelineEventId,
    cue_id: CueId,
    time_ms: u64,
    time_beats: Option<f64>,
    track: TimelineTrackKind,
    layer_id: Option<u32>,
) -> Result<(), String> {
    validate_timeline_time_beats(&format!("Timeline event {event_id}"), time_beats)?;
    let snapshot = state.engine.snapshot();
    if !snapshot.cues.iter().any(|cue| cue.id == cue_id) {
        return Err(format!("Cue {cue_id} was not found"));
    }
    if !snapshot
        .timeline
        .events
        .iter()
        .any(|event| event.id == event_id)
    {
        return Err(format!("Timeline event {event_id} was not found"));
    }
    state
        .engine
        .set_timeline_cue_event_published(event_id, cue_id, time_ms, time_beats, track, layer_id)
}

fn validate_timeline_time_beats(owner: &str, time_beats: Option<f64>) -> Result<(), String> {
    if time_beats.is_some_and(|beats| !beats.is_finite() || beats < 0.0) {
        return Err(format!(
            "{owner} beat-domain start must be a finite non-negative value"
        ));
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn validate_timeline_scene_block_fields(
    events: &[protocol::TimelineCueEventSummary],
    owner: &str,
    time_ms: u64,
    time_beats: Option<f64>,
    duration_ms: u64,
    duration_beats: Option<f64>,
    conform_to_tempo: bool,
    loop_fill: bool,
    loop_count: u16,
    jump_to_event_id: Option<TimelineEventId>,
    allow_legacy_point: bool,
    cue_authored_beats: Option<f32>,
) -> Result<(), String> {
    validate_timeline_time_beats(owner, time_beats)?;
    if duration_beats.is_some_and(|beats| !beats.is_finite() || beats < 0.0) {
        return Err(format!(
            "{owner} beat-domain duration must be a finite non-negative value"
        ));
    }
    if loop_fill && !conform_to_tempo {
        return Err(format!(
            "{owner} Loop-fill requires Conform-to-tempo to be enabled"
        ));
    }
    if conform_to_tempo {
        if cue_authored_beats.is_none() {
            return Err(format!(
                "{owner} uses Conform-to-tempo, but its cue has no authored beat length"
            ));
        }
        if !loop_fill && !duration_beats.is_some_and(|beats| beats > 0.0) {
            return Err(format!(
                "{owner} uses Conform-to-tempo without Loop-fill and requires a positive beat-domain duration"
            ));
        }
    }
    if duration_ms == 0 {
        if conform_to_tempo {
            return Err(format!(
                "{owner} uses Conform-to-tempo and must have a duration greater than zero"
            ));
        }
        if !allow_legacy_point {
            return Err(format!("{owner} duration must be greater than zero"));
        }
        if loop_count != 1 {
            return Err(format!(
                "{owner} is a point event and must use a loop count of 1"
            ));
        }
        if jump_to_event_id.is_some() {
            return Err(format!("{owner} is a point event and cannot define a jump"));
        }
        return Ok(());
    }

    if !(1..=protocol::MAX_TIMELINE_SCENE_BLOCK_LOOPS).contains(&loop_count) {
        return Err(format!(
            "{owner} loop count must be from 1 to {}",
            protocol::MAX_TIMELINE_SCENE_BLOCK_LOOPS
        ));
    }
    let total_duration_ms = if conform_to_tempo {
        duration_ms
    } else {
        duration_ms
            .checked_mul(u64::from(loop_count))
            .ok_or_else(|| format!("{owner} total duration overflows the timeline"))?
    };
    time_ms
        .checked_add(total_duration_ms)
        .ok_or_else(|| format!("{owner} end time overflows the timeline"))?;

    if let Some(jump_to_event_id) = jump_to_event_id {
        if !events.iter().any(|event| event.id == jump_to_event_id) {
            return Err(format!(
                "{owner} references missing jump target event {jump_to_event_id}"
            ));
        }
    }
    Ok(())
}

fn validate_timeline_scene_block_request(
    snapshot: &EngineSnapshot,
    owner: &str,
    cue_id: CueId,
    time_ms: u64,
    time_beats: Option<f64>,
    duration_ms: u64,
    duration_beats: Option<f64>,
    conform_to_tempo: bool,
    loop_fill: bool,
    loop_count: u16,
    jump_to_event_id: Option<TimelineEventId>,
) -> Result<(), String> {
    let cue = snapshot
        .cues
        .iter()
        .find(|cue| cue.id == cue_id)
        .ok_or_else(|| format!("Cue {cue_id} was not found"))?;
    validate_timeline_scene_block_fields(
        &snapshot.timeline.events,
        owner,
        time_ms,
        time_beats,
        duration_ms,
        duration_beats,
        conform_to_tempo,
        loop_fill,
        loop_count,
        jump_to_event_id,
        false,
        cue.authored_beats,
    )
}

#[allow(clippy::too_many_arguments)]
#[tauri::command]
fn add_timeline_scene_block(
    state: State<'_, AppState>,
    cue_id: CueId,
    time_ms: u64,
    time_beats: Option<f64>,
    track: TimelineTrackKind,
    layer_id: Option<u32>,
    duration_ms: u64,
    duration_beats: Option<f64>,
    conform_to_tempo: bool,
    loop_fill: bool,
    source_offset_ms: i64,
    fade_in_ms: u64,
    fade_out_ms: u64,
    loop_count: u16,
    jump_to_event_id: Option<TimelineEventId>,
) -> Result<TimelineEventId, String> {
    let snapshot = state.engine.snapshot();
    validate_timeline_scene_block_request(
        &snapshot,
        "Timeline scene block",
        cue_id,
        time_ms,
        time_beats,
        duration_ms,
        duration_beats,
        conform_to_tempo,
        loop_fill,
        loop_count,
        jump_to_event_id,
    )?;
    let event_id = state.engine.allocate_timeline_event_id();
    state.engine.add_timeline_scene_block(
        event_id,
        cue_id,
        time_ms,
        time_beats,
        track,
        layer_id,
        duration_ms,
        duration_beats,
        conform_to_tempo,
        loop_fill,
        source_offset_ms,
        fade_in_ms.min(duration_ms),
        fade_out_ms.min(duration_ms),
        loop_count,
        jump_to_event_id,
    )?;
    Ok(event_id)
}

#[allow(clippy::too_many_arguments)]
#[tauri::command]
fn set_timeline_scene_block(
    state: State<'_, AppState>,
    event_id: TimelineEventId,
    cue_id: CueId,
    time_ms: u64,
    time_beats: Option<f64>,
    track: TimelineTrackKind,
    layer_id: Option<u32>,
    duration_ms: u64,
    duration_beats: Option<f64>,
    conform_to_tempo: bool,
    loop_fill: bool,
    source_offset_ms: i64,
    fade_in_ms: u64,
    fade_out_ms: u64,
    loop_count: u16,
    jump_to_event_id: Option<TimelineEventId>,
) -> Result<(), String> {
    let snapshot = state.engine.snapshot();
    if !snapshot
        .timeline
        .events
        .iter()
        .any(|event| event.id == event_id)
    {
        return Err(format!("Timeline scene block {event_id} was not found"));
    }
    validate_timeline_scene_block_request(
        &snapshot,
        &format!("Timeline scene block {event_id}"),
        cue_id,
        time_ms,
        time_beats,
        duration_ms,
        duration_beats,
        conform_to_tempo,
        loop_fill,
        loop_count,
        jump_to_event_id,
    )?;
    state.engine.set_timeline_scene_block(
        event_id,
        cue_id,
        time_ms,
        time_beats,
        track,
        layer_id,
        duration_ms,
        duration_beats,
        conform_to_tempo,
        loop_fill,
        source_offset_ms,
        fade_in_ms.min(duration_ms),
        fade_out_ms.min(duration_ms),
        loop_count,
        jump_to_event_id,
    )
}

