#[tauri::command]
async fn refresh_video_layer_metadata(
    window: WebviewWindow,
    state: State<'_, AppState>,
    layer_id: VideoLayerId,
) -> Result<String, String> {
    // Operator/owner admission happens before even reading the local source.
    // The target is then re-captured during reserved relink Prepare against this
    // exact A authority, so a stale layer cannot update B after a reload.
    let operation = reserve_legacy_media_asset_compatibility_operation(&state, &window)?;
    let result = async {
        let target = legacy_media_asset_refresh_target(&state.engine.persistence_snapshot()?, layer_id)?;
        let replacement_path = target.source.path.clone().ok_or_else(|| {
            "Video layer local media source path is required".to_string()
        })?;
        let prepared = prepare_reserved_media_asset_relink_impl(
            &state,
            operation.request_id,
            operation.operation_generation,
            target.asset_id,
            replacement_path,
            // Metadata refresh never adopts different bytes. Same-path bytes
            // are rehashed/probed, then update the catalog and every layer
            // projection through one acknowledged MediaAssetTransaction::Update.
            MediaAssetRelinkPolicy::RequireContentMatch,
            operation.authority.epoch,
            &operation.owner_id,
            Some(&operation),
        )
        .await?;
        let prepared_relink_token = prepared.prepared_relink_token.ok_or_else(|| {
            format!(
                "Video layer metadata refresh did not produce an acknowledged relink: {:?}",
                prepared.outcome
            )
        })?;
        let refreshed_source = state.media_asset_operations.prepared_relink_exact(
            prepared_relink_token,
            operation.request_id,
            operation.operation_generation,
            &operation.owner_id,
        )?.replacement.source;
        let message = legacy_media_asset_refresh_message(&refreshed_source)?;
        let finalized = finalize_prepared_media_asset_relink_impl(
            &state,
            prepared_relink_token,
            operation.request_id,
            operation.operation_generation,
            operation.authority.epoch,
            &operation.owner_id,
            Some(&operation),
        )
        .await?;
        if finalized.prepared_relink_token != Some(prepared_relink_token) || finalized.outcome.is_some() {
            return Err("Video layer metadata refresh finalization was not acknowledged".to_string());
        }
        let committed = commit_prepared_media_asset_relink_authoritative_impl(
            &state,
            prepared_relink_token,
            operation.request_id,
            operation.operation_generation,
            operation.authority.epoch,
            operation.authority.revision,
            operation.authority.checkpoint_hash.clone(),
            &operation.owner_id,
            Some(&operation),
        )?;
        match committed.report.outcome {
            MediaAssetRelinkOutcome::Relinked { asset_id, .. } if asset_id == target.asset_id => {
                Ok(message)
            }
            outcome => Err(format!(
                "Video layer metadata refresh received an unexpected authoritative outcome: {outcome:?}"
            )),
        }
    }
    .await;
    if result.is_err() {
        cancel_legacy_media_asset_compatibility_operation(&state, &operation);
    }
    result
}

#[tauri::command]
fn add_video_input_layer(
    state: State<'_, AppState>,
    label: String,
    kind: VideoSourceKind,
    name: String,
    project_transaction_id: u64,
    expected_epoch: u64,
    owner_id: String,
) -> Result<VideoLayerId, String> {
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    let label = normalize_video_layer_label(label)?;
    let name = normalize_video_input_source_name(&kind, name)?;
    if !matches!(
        kind,
        VideoSourceKind::Camera
            | VideoSourceKind::ScreenCapture
            | VideoSourceKind::Ndi
            | VideoSourceKind::Spout
            | VideoSourceKind::Syphon
    ) {
        return Err(
            "Video input kind must be Camera, Screen Capture, NDI, Spout, or Syphon".to_string(),
        );
    }
    ensure_video_input_backend_available(&kind)?;
    let source = VideoSourceSummary {
        kind,
        path: None,
        name: Some(name),
        codec: None,
        metadata: None,
    };
    let (_external_admission, mut coordinator) = (
        lock_project_external_command_admission(&state)?,
        lock_project_coordinator(&state)?,
    );
    let authority = media_asset_prepare_authority(&coordinator);
    validate_media_asset_commit_ticket_and_authority(
        &state,
        &mut coordinator,
        project_transaction_id,
        expected_epoch,
        &owner_id,
        &authority,
    )?;
    let layer_id = state.engine.allocate_video_layer_id();
    let asset_id = state.engine.allocate_media_asset_id();
    let clip_slot_id = state.engine.allocate_video_clip_slot_id();
    state
        .engine
        .media_asset_transaction_published(MediaAssetTransaction::Import(
            MediaAssetImportCandidate {
                assets: vec![MediaAssetSummary {
                    id: asset_id,
                    label: label.clone(),
                    source: source.clone(),
                    content_hash: None,
                    byte_size: None,
                }],
                layers: vec![protocol::VideoLayerSummary {
                    id: layer_id,
                    label,
                    source,
                    media_asset_id: Some(asset_id),
                    blend_mode: VideoBlendMode::Normal,
                    state: VideoLayerState::default(),
                    isf_effect: None,
                    clip_slots: vec![VideoClipSlotSummary {
                        id: clip_slot_id,
                        media_asset_id: asset_id,
                        in_point_ms: 0,
                        out_point_ms: None,
                        loop_mode: Default::default(),
                        speed: 1.0,
                        cue_points: Vec::new(),
                        launch_quantization: Default::default(),
                        effect_overrides: Vec::new(),
                    }],
                    default_clip_slot_id: Some(clip_slot_id),
                }],
            },
        ))?;
    Ok(layer_id)
}

fn normalize_video_input_source_name(
    kind: &VideoSourceKind,
    name: String,
) -> Result<String, String> {
    let name = name.trim();
    if kind == &VideoSourceKind::ScreenCapture && name.is_empty() {
        return Ok(capture_transport::default_capture_endpoint("screen_capture").to_string());
    }
    if name.is_empty() {
        return Err("Video input source name is required".to_string());
    }
    Ok(name.to_string())
}

#[tauri::command]
fn duplicate_video_layer(
    state: State<'_, AppState>,
    source_layer_id: VideoLayerId,
    label: String,
) -> Result<VideoLayerId, String> {
    let snapshot = state.engine.snapshot();
    let source_layer = snapshot
        .video
        .layers
        .iter()
        .find(|layer| layer.id == source_layer_id)
        .ok_or_else(|| format!("Video layer {source_layer_id} was not found"))?;
    let added_source_bytes = source_layer
        .isf_effect
        .as_ref()
        .map(video_isf_effect_source_bytes)
        .transpose()?
        .unwrap_or(0);
    validate_project_isf_source_budget_after_addition(&snapshot, added_source_bytes)?;
    let label = normalize_video_layer_label(label)?;
    let new_layer_id = state.engine.allocate_video_layer_id();
    state
        .engine
        .duplicate_video_layer_published(source_layer_id, new_layer_id, label)?;
    Ok(new_layer_id)
}

#[tauri::command]
fn remove_video_layer(state: State<'_, AppState>, layer_id: VideoLayerId) -> Result<(), String> {
    state
        .engine
        .send(EngineCommand::RemoveVideoLayer(layer_id))
        .map_err(|error| error.to_string())?;
    let mut cleared_preview = false;
    if let Ok(mut transport) = state.vj_preview_transport.lock() {
        if transport
            .session
            .as_ref()
            .is_some_and(|session| session.layer_id == layer_id)
        {
            transport.clear_at(vj_preview_timestamp_ms());
            cleared_preview = true;
        }
    }
    if cleared_preview {
        reset_vj_preview_renderer(&state)?;
    }
    Ok(())
}

