fn video_isf_stage_from_root(effect: VideoIsfEffectSummary) -> VideoIsfEffectStageSummary {
    VideoIsfEffectStageSummary {
        enabled: effect.enabled,
        label: effect.label,
        source: effect.source,
        source_path: effect.source_path,
        description: effect.description,
        categories: effect.categories,
        controls: effect.controls,
    }
}

fn video_isf_root_from_stages(
    first: VideoIsfEffectStageSummary,
    stack: Vec<VideoIsfEffectStageSummary>,
) -> VideoIsfEffectSummary {
    VideoIsfEffectSummary {
        enabled: first.enabled,
        label: first.label,
        source: first.source,
        source_path: first.source_path,
        description: first.description,
        categories: first.categories,
        controls: first.controls,
        stack,
    }
}

fn sanitize_video_isf_stage(
    effect: VideoIsfEffectStageSummary,
) -> Result<VideoIsfEffectStageSummary, String> {
    let label = effect.label.trim();
    if label.is_empty() || label.chars().count() > 128 {
        return Err("ISF effect label must contain 1-128 characters".to_string());
    }
    let prepared =
        video::prepare_isf_shader(effect.source.as_ref()).map_err(|error| error.to_string())?;
    let resolved = video::resolved_isf_control_values_from_controls(&prepared, &effect.controls);
    let source_path = effect.source_path.and_then(|path| {
        let path = path.trim().to_string();
        (!path.is_empty()).then_some(path)
    });
    let canonical_root =
        video::isf_effect_from_prepared(label.to_string(), effect.source, source_path, &prepared);
    let mut canonical = video_isf_stage_from_root(canonical_root);
    canonical.enabled = effect.enabled;
    for (control, value) in canonical.controls.iter_mut().zip(resolved) {
        control.value = value;
    }
    Ok(canonical)
}

fn sanitize_video_isf_effect(
    effect: VideoIsfEffectSummary,
) -> Result<VideoIsfEffectSummary, String> {
    if 1 + effect.stack.len() > video::VIDEO_ISF_EFFECT_STACK_MAX_STAGES {
        return Err(format!(
            "ISF stack contains {} stages; the limit is {}",
            1 + effect.stack.len(),
            video::VIDEO_ISF_EFFECT_STACK_MAX_STAGES
        ));
    }
    let total_source_bytes = effect.source.len()
        + effect
            .stack
            .iter()
            .map(|stage| stage.source.len())
            .sum::<usize>();
    if total_source_bytes > video::ISF_MAX_SOURCE_BYTES {
        return Err(format!(
            "ISF stack source size is {total_source_bytes} bytes; the limit is {} bytes",
            video::ISF_MAX_SOURCE_BYTES
        ));
    }
    let VideoIsfEffectSummary {
        enabled,
        label,
        source,
        source_path,
        description,
        categories,
        controls,
        stack,
    } = effect;
    let first = sanitize_video_isf_stage(VideoIsfEffectStageSummary {
        enabled,
        label,
        source,
        source_path,
        description,
        categories,
        controls,
    })?;
    let stack = stack
        .into_iter()
        .enumerate()
        .map(|(index, stage)| {
            sanitize_video_isf_stage(stage)
                .map_err(|error| format!("ISF stage {} is invalid: {error}", index + 2))
        })
        .collect::<Result<Vec<_>, _>>()?;
    Ok(video_isf_root_from_stages(first, stack))
}

fn video_isf_effect_source_bytes(effect: &VideoIsfEffectSummary) -> Result<usize, String> {
    effect
        .stack
        .iter()
        .try_fold(effect.source.len(), |total, stage| {
            total
                .checked_add(stage.source.len())
                .ok_or_else(|| "Project ISF source size overflowed".to_string())
        })
}

fn project_isf_source_bytes(snapshot: &EngineSnapshot) -> Result<usize, String> {
    snapshot
        .video
        .layers
        .iter()
        .filter_map(|layer| layer.isf_effect.as_ref())
        .try_fold(0_usize, |total, effect| {
            total
                .checked_add(video_isf_effect_source_bytes(effect)?)
                .ok_or_else(|| "Project ISF source size overflowed".to_string())
        })
}

fn validate_project_isf_source_budget(total_source_bytes: usize) -> Result<(), String> {
    if total_source_bytes > PROJECT_ISF_SOURCE_MAX_BYTES {
        return Err(format!(
            "Project ISF source size exceeds the {} byte limit",
            PROJECT_ISF_SOURCE_MAX_BYTES
        ));
    }
    Ok(())
}

fn validate_project_isf_source_budget_after_addition(
    snapshot: &EngineSnapshot,
    added_source_bytes: usize,
) -> Result<(), String> {
    let total_source_bytes = project_isf_source_bytes(snapshot)?
        .checked_add(added_source_bytes)
        .ok_or_else(|| "Project ISF source size overflowed".to_string())?;
    validate_project_isf_source_budget(total_source_bytes)
}

fn validate_project_isf_source_budget_after_replacement(
    snapshot: &EngineSnapshot,
    layer_id: VideoLayerId,
    replacement: Option<&VideoIsfEffectSummary>,
) -> Result<(), String> {
    let current_source_bytes = snapshot
        .video
        .layers
        .iter()
        .find(|layer| layer.id == layer_id)
        .and_then(|layer| layer.isf_effect.as_ref())
        .map(video_isf_effect_source_bytes)
        .transpose()?
        .unwrap_or(0);
    let replacement_source_bytes = replacement
        .map(video_isf_effect_source_bytes)
        .transpose()?
        .unwrap_or(0);
    let total_source_bytes = project_isf_source_bytes(snapshot)?
        .checked_sub(current_source_bytes)
        .and_then(|total| total.checked_add(replacement_source_bytes))
        .ok_or_else(|| "Project ISF source size overflowed".to_string())?;
    validate_project_isf_source_budget(total_source_bytes)
}

#[tauri::command]
fn fade_video_layer_opacity(
    state: State<'_, AppState>,
    layer_id: VideoLayerId,
    opacity: f32,
    duration_ms: u64,
) -> Result<(), String> {
    if !opacity.is_finite() {
        return Err("Video layer opacity must be finite".to_string());
    }
    state
        .engine
        .send(EngineCommand::FadeVideoLayerOpacity {
            layer_id,
            opacity,
            duration_ms,
        })
        .map_err(|error| error.to_string())
}

#[tauri::command]
fn launch_video_clip(
    state: State<'_, AppState>,
    layer_id: VideoLayerId,
    fade_ms: u64,
) -> Result<(), String> {
    let snapshot = state.engine.snapshot();
    let layer = snapshot
        .video
        .layers
        .iter()
        .find(|layer| layer.id == layer_id)
        .ok_or_else(|| format!("Video layer {layer_id} was not found"))?;
    let next = launched_video_clip_state(&layer.state, fade_ms);
    state
        .engine
        .send(EngineCommand::SetVideoLayerState {
            layer_id,
            state: next,
        })
        .map_err(|error| error.to_string())?;
    if fade_ms > 0 {
        state
            .engine
            .send(EngineCommand::FadeVideoLayerOpacity {
                layer_id,
                opacity: 1.0,
                duration_ms: fade_ms,
            })
            .map_err(|error| error.to_string())?;
    }
    Ok(())
}

#[tauri::command]
fn take_video_clip(
    state: State<'_, AppState>,
    layer_id: VideoLayerId,
    fade_ms: u64,
) -> Result<(), String> {
    let snapshot = state.engine.snapshot();
    let now = Instant::now();
    let updated_at_ms = vj_preview_timestamp_ms();
    let (preview_take_state, preview_valid) = {
        let mut transport = state
            .vj_preview_transport
            .lock()
            .map_err(|_| "VJ Preview transport lock was poisoned".to_string())?;
        let valid = transport.reconcile_at(&snapshot, now, updated_at_ms);
        (
            transport.current_take_state_at(layer_id, now, updated_at_ms),
            valid,
        )
    };
    if !preview_valid {
        reset_vj_preview_renderer(&state)?;
    }
    let preview_take_state = preview_take_state.ok_or_else(|| {
        format!("Stage video layer {layer_id} in Preview before sending it to Program")
    })?;
    // Manual Program video must never wait for audio device/file I/O. Invalidating
    // the current generation is lock-free; any in-flight Auto audio job verifies
    // the token again after opening/decoding and rolls itself back if it lost.
    state.program_audio_handoff.invalidate_in_flight();
    let result = state
        .engine
        .exclusive_video_take(ExclusiveVideoTakeRequest {
            target_layer_id: layer_id,
            fade_ms,
            preview_position_ms: Some(preview_take_state.position_ms),
            preview_speed: Some(preview_take_state.speed),
        });
    let published = state.engine.snapshot();
    let mut program_handoff = state
        .program_audio_handoff
        .state
        .lock()
        .map_err(|_| "Program audio handoff lock was poisoned".to_string())?;
    if result.is_ok() {
        program_handoff.suppress_through(published.video.auto_vj.status.last_action.as_ref());
        if let Some(plan) = program_handoff.manual_take_plan(layer_id) {
            state
                .program_audio_handoff
                .queue_locked(&mut program_handoff, ProgramAudioJobKind::Handoff(plan));
        }
    } else if program_handoff.config.enabled {
        // The visual Take was rejected. Restore the audio that still belongs to
        // the published Program/Auto action instead of leaving a cancelled job silent.
        let recovery_layer_id = program_handoff
            .desired_layer_id
            .or(program_handoff.owned_layer_id)
            .or_else(|| {
                published
                    .video
                    .auto_vj
                    .status
                    .last_action
                    .as_ref()
                    .map(|action| action.layer_id)
            });
        program_handoff.suppress_through(published.video.auto_vj.status.last_action.as_ref());
        if let Some(recovery_layer_id) = recovery_layer_id {
            if let Some(plan) = program_handoff.manual_take_plan(recovery_layer_id) {
                state
                    .program_audio_handoff
                    .queue_locked(&mut program_handoff, ProgramAudioJobKind::Handoff(plan));
            }
        }
    }
    result
}

