#[tauri::command]
fn set_program_audio_handoff_config(
    state: State<'_, AppState>,
    enabled: bool,
    volume: f32,
    device_name: Option<String>,
) -> Result<(), String> {
    let config = ProgramAudioHandoffConfig::validated(enabled, volume, device_name)?;
    let snapshot = state.engine.video_audio_runtime_snapshot();
    let mut program_handoff = state
        .program_audio_handoff
        .state
        .lock()
        .map_err(|_| "Program audio handoff lock was poisoned".to_string())?;
    let previous_config = program_handoff.config.clone();
    let active_target = program_handoff
        .desired_layer_id
        .or(program_handoff.owned_layer_id);
    program_handoff.configure(config.clone(), snapshot.auto_vj_status.last_action.as_ref());
    if previous_config.enabled && !config.enabled {
        state
            .program_audio_handoff
            .queue_locked(&mut program_handoff, ProgramAudioJobKind::StopAll);
        program_handoff.owned_layer_id = None;
        program_handoff.desired_layer_id = None;
    } else if previous_config.enabled && config.enabled && previous_config != config {
        let unseen_action_plan = program_handoff.next_plan(&snapshot.auto_vj_status);
        let exclusive_plan = unseen_action_plan.or_else(|| {
            active_target.and_then(|layer_id| program_handoff.manual_take_plan(layer_id))
        });
        let job = exclusive_plan.map_or_else(
            || ProgramAudioJobKind::ReconfigureActive {
                previous_volume: previous_config.volume,
                volume: config.volume,
                device_name: config.device_name.clone(),
            },
            ProgramAudioJobKind::Handoff,
        );
        state
            .program_audio_handoff
            .queue_locked(&mut program_handoff, job);
    }
    state.program_audio_handoff.wake.notify_all();
    Ok(())
}

#[tauri::command]
fn set_timeline_guide_audio_config(
    state: State<'_, AppState>,
    enabled: bool,
    gain: f32,
    device_name: Option<String>,
) -> Result<TimelineGuideAudioStatus, String> {
    let status = {
        let mut audio = state
            .media_audio
            .lock()
            .map_err(|_| "Media audio playback lock was poisoned".to_string())?;
        audio.guide.configure(enabled, gain, device_name)?;
        audio.guide.status()
    };
    state.program_audio_handoff.wake.notify_all();
    Ok(status)
}

#[tauri::command]
fn get_timeline_guide_audio_status(
    state: State<'_, AppState>,
) -> Result<TimelineGuideAudioStatus, String> {
    state
        .media_audio
        .lock()
        .map(|audio| audio.guide.status())
        .map_err(|_| "Media audio playback lock was poisoned".to_string())
}

#[tauri::command]
fn set_video_ab_mix(
    state: State<'_, AppState>,
    layer_a_id: Option<VideoLayerId>,
    layer_b_id: Option<VideoLayerId>,
    mix: f32,
) -> Result<(), String> {
    if !mix.is_finite() {
        return Err("Video A/B mix must be finite".to_string());
    }
    if layer_a_id.is_some() && layer_a_id == layer_b_id {
        return Err("Video Deck A and Deck B must use different layers".to_string());
    }
    let snapshot = state.engine.snapshot();
    let updates = [
        (layer_a_id, 1.0 - mix.clamp(0.0, 1.0)),
        (layer_b_id, mix.clamp(0.0, 1.0)),
    ]
    .into_iter()
    .filter_map(|(layer_id, opacity)| layer_id.map(|layer_id| (layer_id, opacity)))
    .map(|(layer_id, opacity)| {
        let layer = snapshot
            .video
            .layers
            .iter()
            .find(|layer| layer.id == layer_id)
            .ok_or_else(|| format!("Video layer {layer_id} was not found"))?;
        let mut next = layer.state.clone();
        next.opacity = opacity;
        Ok((layer_id, next))
    })
    .collect::<Result<Vec<_>, String>>()?;
    for (layer_id, next) in updates {
        state
            .engine
            .send(EngineCommand::SetVideoLayerState {
                layer_id,
                state: next,
            })
            .map_err(|error| error.to_string())?;
    }
    Ok(())
}

#[tauri::command]
fn stop_video_clip(
    state: State<'_, AppState>,
    layer_id: VideoLayerId,
    fade_ms: u64,
) -> Result<(), String> {
    let snapshot = state.engine.snapshot();
    let layer = snapshot
        .video
        .layers
        .iter()
        .find(|layer| layer.id == layer_id)
        .ok_or_else(|| format!("Video layer {layer_id} was not found"))?;
    let next = stopped_video_clip_state(&layer.state, fade_ms);
    state
        .engine
        .send(EngineCommand::SetVideoLayerState {
            layer_id,
            state: next,
        })
        .map_err(|error| error.to_string())?;
    if fade_ms > 0 {
        state
            .engine
            .send(EngineCommand::FadeVideoLayerOpacity {
                layer_id,
                opacity: 0.0,
                duration_ms: fade_ms,
            })
            .map_err(|error| error.to_string())?;
    }
    Ok(())
}

#[tauri::command]
fn play_video_layer_audio_monitor(
    state: State<'_, AppState>,
    layer_id: VideoLayerId,
    volume: f32,
    device_name: Option<String>,
) -> Result<VideoAudioMonitorStatus, String> {
    if !volume.is_finite() {
        return Err("Audio monitor volume must be finite".to_string());
    }
    let snapshot = state.engine.snapshot();
    let layer = snapshot
        .video
        .layers
        .iter()
        .find(|layer| layer.id == layer_id)
        .ok_or_else(|| format!("Video layer {layer_id} was not found"))?;
    if layer.state.speed < 0.0 {
        return Err("Reverse video audio monitoring is not supported".to_string());
    }
    let path = layer
        .source
        .path
        .as_deref()
        .filter(|_| layer.source.kind == VideoSourceKind::File)
        .ok_or_else(|| "Audio monitoring requires a local video file layer".to_string())?;
    let (direct_generation, recovery_target) = {
        let mut handoff = state
            .program_audio_handoff
            .state
            .lock()
            .map_err(|_| "Program audio handoff lock was poisoned".to_string())?;
        let recovery_target = handoff
            .desired_layer_id
            .or(handoff.owned_layer_id)
            .filter(|target| *target != layer_id);
        let generation = state.program_audio_handoff.invalidate_in_flight();
        handoff.pending_job = None;
        handoff.owned_layer_id = None;
        handoff.desired_layer_id = None;
        handoff.suppress_through(snapshot.video.auto_vj.status.last_action.as_ref());
        (generation, recovery_target)
    };
    let result = state
        .media_audio
        .lock()
        .map_err(|_| "Media audio monitor lock was poisoned".to_string())
        .and_then(|mut audio| {
            audio.play(
                layer_id,
                Path::new(path),
                layer.state.position_ms,
                layer.state.speed,
                volume,
                device_name.as_deref(),
            )?;
            Ok(audio.status())
        });
    if result.is_err()
        && state
            .program_audio_handoff
            .generation
            .load(Ordering::Acquire)
            == direct_generation
    {
        if let Some(recovery_target) = recovery_target {
            if let Ok(mut handoff) = state.program_audio_handoff.state.lock() {
                if handoff.config.enabled
                    && handoff.pending_job.is_none()
                    && handoff.desired_layer_id.is_none()
                {
                    if let Some(plan) = handoff.manual_take_plan(recovery_target) {
                        state
                            .program_audio_handoff
                            .queue_locked(&mut handoff, ProgramAudioJobKind::Handoff(plan));
                        state.program_audio_handoff.wake.notify_all();
                    }
                }
            }
        }
    }
    result
}

#[tauri::command]
fn list_audio_output_devices() -> Result<Vec<String>, String> {
    use rodio::cpal::traits::{DeviceTrait, HostTrait};

    let mut names = rodio::cpal::default_host()
        .output_devices()
        .map_err(|error| format!("Failed to list audio output devices: {error}"))?
        .filter_map(|device| device.name().ok())
        .collect::<Vec<_>>();
    names.sort();
    names.dedup();
    Ok(names)
}

#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
struct LiveAudioInputBackendSummary {
    id: String,
    label: String,
    built: bool,
    requires_explicit_device: bool,
    distribution: String,
}

#[tauri::command]
fn live_audio_input_backends() -> Vec<LiveAudioInputBackendSummary> {
    #[cfg(all(target_os = "windows", feature = "asio"))]
    let asio_built = AsioBridgeLibrary::load()
        .map(|bridge| bridge.asio_compiled())
        .unwrap_or(false);
    #[cfg(not(all(target_os = "windows", feature = "asio")))]
    let asio_built = false;
    vec![
        LiveAudioInputBackendSummary {
            id: "wasapi_shared".to_string(),
            label: "WASAPI Shared".to_string(),
            built: cfg!(target_os = "windows"),
            requires_explicit_device: false,
            distribution: "default".to_string(),
        },
        LiveAudioInputBackendSummary {
            id: "asio".to_string(),
            label: "ASIO".to_string(),
            built: asio_built,
            requires_explicit_device: true,
            distribution: "separate_artifact".to_string(),
        },
    ]
}

#[tauri::command]
fn list_audio_input_devices(
    state: State<'_, AppState>,
    backend: Option<LiveAudioInputBackend>,
) -> Result<Vec<LiveAudioInputDeviceSummary>, String> {
    use rodio::cpal::traits::{DeviceTrait, HostTrait};

    if state
        .live_audio_input
        .lock()
        .map_err(|_| "Live audio input state lock was poisoned".to_string())?
        .is_some()
    {
        return Err("Stop live audio input before refreshing its device catalog".to_string());
    }
    let backend = backend.unwrap_or_default();
    let mut devices: Vec<(usize, String, String, LiveAudioInputDevice)> = match backend {
        LiveAudioInputBackend::WasapiShared => {
            let host = rodio::cpal::default_host();
            let host_label = host.id().name().to_string();
            host.input_devices()
                .map_err(|error| format!("Failed to list audio input devices: {error}"))?
                .enumerate()
                .map(|(ordinal, device)| {
                    let name = device
                        .name()
                        .unwrap_or_else(|_| format!("Unnamed audio input {}", ordinal + 1));
                    (
                        ordinal,
                        name,
                        host_label.clone(),
                        LiveAudioInputDevice::Wasapi(device),
                    )
                })
                .collect()
        }
        LiveAudioInputBackend::Asio => {
            #[cfg(all(target_os = "windows", feature = "asio"))]
            {
                AsioBridgeLibrary::load()?
                    .drivers()?
                    .into_iter()
                    .enumerate()
                    .map(|(ordinal, driver)| {
                        let name = if driver.name.trim().is_empty() {
                            format!("Unnamed ASIO input {}", ordinal + 1)
                        } else {
                            driver.name.clone()
                        };
                        (
                            ordinal,
                            name,
                            "ASIO".to_string(),
                            LiveAudioInputDevice::Asio(AsioBridgeDevice {
                                driver_id: driver.id,
                            }),
                        )
                    })
                    .collect()
            }
            #[cfg(not(all(target_os = "windows", feature = "asio")))]
            {
                return Err(
                    "ASIO input is not built into this artifact; use the separate ASIO build"
                        .to_string(),
                );
            }
        }
    };
    devices.sort_by(|left, right| {
        left.2
            .cmp(&right.2)
            .then_with(|| left.1.to_lowercase().cmp(&right.1.to_lowercase()))
            .then_with(|| left.0.cmp(&right.0))
    });
    let names = devices
        .iter()
        .map(|(_, name, _, _)| name.clone())
        .collect::<Vec<_>>();
    let labels = disambiguate_live_audio_input_labels(&names);
    let mut catalog = state
        .live_audio_input_devices
        .lock()
        .map_err(|_| "Live audio input device catalog lock was poisoned".to_string())?;
    catalog.generation = catalog.generation.wrapping_add(1).max(1);
    let generation = catalog.generation;
    catalog.entries.clear();
    let summaries = devices
        .into_iter()
        .zip(labels)
        .enumerate()
        .map(|(index, ((_, name, backend, device), label))| {
            let id = live_audio_input_device_id(&backend, generation, index);
            let summary = LiveAudioInputDeviceSummary {
                id: id.clone(),
                name,
                label,
                backend: backend.clone(),
            };
            catalog.entries.insert(
                id,
                LiveAudioInputDeviceEntry {
                    summary: summary.clone(),
                    device,
                },
            );
            summary
        })
        .collect();
    Ok(summaries)
}

fn live_audio_input_device_id(backend: &str, generation: u64, index: usize) -> String {
    format!("{}:{generation}:{index}", backend.to_ascii_lowercase())
}

fn disambiguate_live_audio_input_labels(names: &[String]) -> Vec<String> {
    let mut occurrences = HashMap::<&str, usize>::new();
    let mut used = HashSet::<String>::new();
    names
        .iter()
        .map(|name| {
            let occurrence = occurrences.entry(name.as_str()).or_default();
            *occurrence += 1;
            let mut suffix = *occurrence;
            let mut candidate = if suffix == 1 {
                name.clone()
            } else {
                format!("{name} ({suffix})")
            };
            while used.contains(&candidate) {
                suffix += 1;
                candidate = format!("{name} ({suffix})");
            }
            used.insert(candidate.clone());
            candidate
        })
        .collect()
}

fn resolve_live_audio_input_device(
    state: &AppState,
    backend: LiveAudioInputBackend,
    device_id: Option<&str>,
) -> Result<ResolvedLiveAudioInputDevice, String> {
    use rodio::cpal::traits::{DeviceTrait, HostTrait};

    if let Some(device_id) = device_id.map(str::trim).filter(|id| !id.is_empty()) {
        let catalog = state
            .live_audio_input_devices
            .lock()
            .map_err(|_| "Live audio input device catalog lock was poisoned".to_string())?;
        let entry = catalog.entries.get(device_id).ok_or_else(|| {
            "Audio input device selection is stale or unknown; refresh the device list".to_string()
        })?;
        if entry.device.backend() != backend {
            return Err(format!(
                "Audio input selection belongs to {}, not the requested {} backend; refresh and select again",
                entry.summary.backend,
                backend.label(),
            ));
        }
        return Ok(ResolvedLiveAudioInputDevice {
            device_id: Some(entry.summary.id.clone()),
            device_name: entry.summary.name.clone(),
            backend: entry.summary.backend.clone(),
            device: entry.device.clone(),
        });
    }

    if backend == LiveAudioInputBackend::Asio {
        return Err(
            "Select an explicit ASIO driver before reading capabilities or starting input"
                .to_string(),
        );
    }
    let host = rodio::cpal::default_host();
    let device = host
        .default_input_device()
        .ok_or_else(|| "No default audio input device is available".to_string())?;
    let device_name = device
        .name()
        .unwrap_or_else(|_| "System default audio input".to_string());
    Ok(ResolvedLiveAudioInputDevice {
        device_id: None,
        device_name,
        backend: host.id().name().to_string(),
        device: LiveAudioInputDevice::Wasapi(device),
    })
}

fn live_audio_buffer_capability(
    buffer_size: &rodio::cpal::SupportedBufferSize,
) -> LiveAudioBufferCapability {
    match *buffer_size {
        rodio::cpal::SupportedBufferSize::Range { min, max } => LiveAudioBufferCapability::Range {
            min_frames: min,
            max_frames: max,
        },
        rodio::cpal::SupportedBufferSize::Unknown => LiveAudioBufferCapability::Unknown,
    }
}

fn live_audio_input_config(config: &rodio::cpal::SupportedStreamConfig) -> LiveAudioInputConfig {
    LiveAudioInputConfig {
        channels: config.channels(),
        sample_rate: config.sample_rate().0,
        sample_format: config.sample_format().to_string(),
    }
}

fn live_audio_input_config_range(
    range: &rodio::cpal::SupportedStreamConfigRange,
) -> LiveAudioInputConfigRange {
    LiveAudioInputConfigRange {
        channels: range.channels(),
        min_sample_rate: range.min_sample_rate().0,
        max_sample_rate: range.max_sample_rate().0,
        sample_format: range.sample_format().to_string(),
        buffer_size: live_audio_buffer_capability(range.buffer_size()),
    }
}

#[cfg(all(target_os = "windows", feature = "asio"))]
fn live_audio_input_capabilities_asio(
    resolved: &ResolvedLiveAudioInputDevice,
    device: &AsioBridgeDevice,
    sample_rate: Option<u32>,
) -> Result<LiveAudioInputCapabilities, String> {
    let payload = AsioBridgeLibrary::load()?.capabilities_json(&device.driver_id)?;
    let capabilities: AsioBridgeCapabilities = serde_json::from_str(&payload)
        .map_err(|error| format!("ASIO capability response was invalid: {error}"))?;
    if capabilities.abi_version != SYNDOCAL_ASIO_ABI_VERSION
        || !capabilities.backend.eq_ignore_ascii_case("asio")
        || !capabilities.built
        || capabilities.driver.id != device.driver_id
        || capabilities.driver.name.trim().is_empty()
    {
        return Err(
            "ASIO capability response did not match the selected driver and ABI".to_string(),
        );
    }
    if capabilities.driver.input_channels == 0
        || capabilities.driver.sample_formats.is_empty()
        || capabilities.driver.sample_rates_hz.is_empty()
        || capabilities.driver.buffer_frames.min == 0
        || capabilities.driver.buffer_frames.min > capabilities.driver.buffer_frames.max
    {
        return Err("Selected ASIO driver reported incomplete input capabilities".to_string());
    }
    let requested_rate = match sample_rate {
        Some(0) => return Err("ASIO sample rate must be greater than zero".to_string()),
        Some(rate) => rate,
        None => [48_000, 44_100]
            .into_iter()
            .find(|rate| capabilities.driver.sample_rates_hz.contains(rate))
            .or_else(|| capabilities.driver.sample_rates_hz.iter().copied().min())
            .ok_or_else(|| "Selected ASIO driver reported no usable sample rate".to_string())?,
    };
    let format_rank = |format: &str| match format {
        "f32" => 0_u8,
        "i16" => 1,
        "i24" => 2,
        "i32" => 3,
        "f64" => 4,
        _ => u8::MAX,
    };
    let selected = capabilities
        .input_configs
        .iter()
        .filter(|config| {
            config.sample_rate_hz == requested_rate
                && config.channels > 0
                && config.channels <= capabilities.driver.input_channels
                && config.buffer_frames.min > 0
                && config.buffer_frames.min <= config.buffer_frames.max
                && format_rank(&config.sample_format) != u8::MAX
        })
        .min_by_key(|config| {
            (
                std::cmp::Reverse(config.channels),
                format_rank(&config.sample_format),
                config.buffer_frames.min,
            )
        })
        .ok_or_else(|| {
            format!(
                "Selected ASIO driver does not expose an input configuration at {requested_rate} Hz"
            )
        })?;
    let to_buffer = |range: AsioBridgeBufferRange| LiveAudioBufferCapability::Range {
        min_frames: range.min,
        max_frames: range.max,
    };
    let mut supported_configs = capabilities
        .input_configs
        .iter()
        .filter(|config| {
            config.channels > 0
                && config.sample_rate_hz > 0
                && config.buffer_frames.min > 0
                && config.buffer_frames.min <= config.buffer_frames.max
                && format_rank(&config.sample_format) != u8::MAX
        })
        .map(|config| LiveAudioInputConfigRange {
            channels: config.channels,
            min_sample_rate: config.sample_rate_hz,
            max_sample_rate: config.sample_rate_hz,
            sample_format: config.sample_format.clone(),
            buffer_size: to_buffer(config.buffer_frames),
        })
        .collect::<Vec<_>>();
    supported_configs.sort();
    supported_configs.dedup();
    let default_rate = [48_000, 44_100]
        .into_iter()
        .find(|rate| capabilities.driver.sample_rates_hz.contains(rate))
        .unwrap_or(requested_rate);
    let default_format = capabilities
        .driver
        .sample_formats
        .iter()
        .filter(|format| format_rank(format) != u8::MAX)
        .min_by_key(|format| format_rank(format))
        .cloned()
        .ok_or_else(|| "Selected ASIO driver exposes no supported PCM format".to_string())?;
    Ok(LiveAudioInputCapabilities {
        device_id: resolved.device_id.clone(),
        device_name: resolved.device_name.clone(),
        backend: "ASIO".to_string(),
        default_config: LiveAudioInputConfig {
            channels: capabilities.driver.input_channels,
            sample_rate: default_rate,
            sample_format: default_format,
        },
        supported_configs,
        resolved_config: LiveAudioInputResolvedConfig {
            channels: selected.channels,
            sample_rate: selected.sample_rate_hz,
            sample_format: selected.sample_format.clone(),
            buffer_size: to_buffer(selected.buffer_frames),
        },
        max_capture_frames: LIVE_AUDIO_CAPTURE_SLOT_COUNT * LIVE_AUDIO_CAPTURE_SLOT_FRAMES,
    })
}

#[cfg(all(target_os = "windows", feature = "asio"))]
fn asio_sample_format(format: &str) -> Option<rodio::cpal::SampleFormat> {
    match format {
        "f32" => Some(rodio::cpal::SampleFormat::F32),
        "i16" => Some(rodio::cpal::SampleFormat::I16),
        "i24" => Some(rodio::cpal::SampleFormat::I24),
        "i32" => Some(rodio::cpal::SampleFormat::I32),
        "f64" => Some(rodio::cpal::SampleFormat::F64),
        _ => None,
    }
}

#[cfg(all(target_os = "windows", feature = "asio"))]
fn resolve_asio_live_audio_start_config(
    resolved: &ResolvedLiveAudioInputDevice,
    device: &AsioBridgeDevice,
    request: &LiveAudioInputStartRequest,
) -> Result<SelectedLiveAudioInputConfig, String> {
    let sample_rate = request
        .sample_rate
        .filter(|rate| *rate > 0)
        .ok_or_else(|| "Select an explicit ASIO sample rate before Start".to_string())?;
    let channels = request
        .stream_channels
        .filter(|channels| *channels > 0)
        .ok_or_else(|| {
            "Select an explicit ASIO input channel configuration before Start".to_string()
        })?;
    let sample_format_name = request
        .sample_format
        .as_deref()
        .map(str::trim)
        .filter(|format| !format.is_empty())
        .ok_or_else(|| "Select an explicit ASIO sample format before Start".to_string())?;
    let sample_format = asio_sample_format(sample_format_name)
        .ok_or_else(|| format!("Unsupported ASIO sample format {sample_format_name}"))?;
    let buffer_frames = request
        .buffer_frames
        .filter(|frames| *frames > 0)
        .ok_or_else(|| "Select an explicit fixed ASIO buffer before Start".to_string())?;
    validate_live_audio_configured_buffer(buffer_frames, sample_rate)?;
    request.channel_mix.validate(channels)?;

    let capabilities = live_audio_input_capabilities_asio(resolved, device, Some(sample_rate))?;
    let matching = capabilities
        .supported_configs
        .iter()
        .find(|config| {
            config.channels == channels
                && config.min_sample_rate == sample_rate
                && config.max_sample_rate == sample_rate
                && config.sample_format == sample_format_name
                && live_audio_buffer_accepts(config.buffer_size, buffer_frames)
        })
        .ok_or_else(|| {
            format!(
                "ASIO configuration changed or is unsupported: {} Hz, {channels} ch, {sample_format_name}, {buffer_frames} frames",
                sample_rate
            )
        })?;
    Ok(SelectedLiveAudioInputConfig {
        stream_config: rodio::cpal::StreamConfig {
            channels,
            sample_rate: rodio::cpal::SampleRate(sample_rate),
            buffer_size: rodio::cpal::BufferSize::Fixed(buffer_frames),
        },
        sample_format,
        buffer_capability: matching.buffer_size,
        configured_buffer_frames: Some(buffer_frames),
        channel_mix: request.channel_mix,
    })
}

#[tauri::command]
fn get_live_audio_input_capabilities(
    state: State<'_, AppState>,
    backend: Option<LiveAudioInputBackend>,
    device_id: Option<String>,
    sample_rate: Option<u32>,
) -> Result<LiveAudioInputCapabilities, String> {
    use rodio::cpal::traits::DeviceTrait;

    let backend = backend.unwrap_or_default();
    let resolved = resolve_live_audio_input_device(&state, backend, device_id.as_deref())?;
    match &resolved.device {
        LiveAudioInputDevice::Wasapi(device) => {
            let default_config = device.default_input_config().map_err(|error| {
                format!("Failed to read default audio input configuration: {error}")
            })?;
            let supported_config_ranges = device
                .supported_input_configs()
                .map_err(|error| {
                    format!("Failed to read supported audio input configurations: {error}")
                })?
                .collect::<Vec<_>>();
            let selected = resolve_live_audio_stream_config(
                &default_config,
                &supported_config_ranges,
                &LiveAudioInputStartRequest {
                    backend,
                    sample_rate,
                    ..LiveAudioInputStartRequest::default()
                },
            )?;
            let mut supported_configs = supported_config_ranges
                .iter()
                .map(live_audio_input_config_range)
                .collect::<Vec<_>>();
            supported_configs.sort();
            supported_configs.dedup();
            Ok(LiveAudioInputCapabilities {
                device_id: resolved.device_id,
                device_name: resolved.device_name,
                backend: resolved.backend,
                default_config: live_audio_input_config(&default_config),
                supported_configs,
                resolved_config: LiveAudioInputResolvedConfig {
                    channels: selected.stream_config.channels,
                    sample_rate: selected.stream_config.sample_rate.0,
                    sample_format: selected.sample_format.to_string(),
                    buffer_size: selected.buffer_capability,
                },
                max_capture_frames: LIVE_AUDIO_CAPTURE_SLOT_COUNT * LIVE_AUDIO_CAPTURE_SLOT_FRAMES,
            })
        }
        #[cfg(all(target_os = "windows", feature = "asio"))]
        LiveAudioInputDevice::Asio(device) => {
            live_audio_input_capabilities_asio(&resolved, device, sample_rate)
        }
    }
}

fn live_audio_buffer_accepts(capability: LiveAudioBufferCapability, buffer_frames: u32) -> bool {
    match capability {
        LiveAudioBufferCapability::Range {
            min_frames,
            max_frames,
        } => (min_frames..=max_frames).contains(&buffer_frames),
        LiveAudioBufferCapability::Unknown => true,
    }
}

fn live_audio_sample_format_rank(
    format: rodio::cpal::SampleFormat,
    default_format: rodio::cpal::SampleFormat,
) -> u8 {
    if format == default_format {
        return 0;
    }
    match format {
        rodio::cpal::SampleFormat::F32 => 1,
        rodio::cpal::SampleFormat::I16 => 2,
        rodio::cpal::SampleFormat::U16 => 3,
        rodio::cpal::SampleFormat::F64 => 4,
        rodio::cpal::SampleFormat::I32 => 5,
        rodio::cpal::SampleFormat::I24 => 6,
        rodio::cpal::SampleFormat::I8 => 7,
        rodio::cpal::SampleFormat::U8 => 8,
        rodio::cpal::SampleFormat::I64 => 9,
        rodio::cpal::SampleFormat::U32 => 10,
        rodio::cpal::SampleFormat::U64 => 11,
        _ => u8::MAX,
    }
}

fn live_audio_channel_rank(channels: u16, default_channels: u16) -> (u8, u16) {
    if channels == default_channels {
        (0, channels)
    } else if channels == 2 {
        (1, channels)
    } else if channels == 1 {
        (2, channels)
    } else {
        (3, channels)
    }
}

fn validate_live_audio_configured_buffer(
    buffer_frames: u32,
    sample_rate: u32,
) -> Result<(), String> {
    if buffer_frames == 0 {
        return Err("Live audio buffer size must be greater than zero frames".to_string());
    }
    let max_capture_frames = LIVE_AUDIO_CAPTURE_SLOT_COUNT * LIVE_AUDIO_CAPTURE_SLOT_FRAMES;
    if buffer_frames as usize > max_capture_frames {
        return Err(format!(
            "Requested live audio buffer {buffer_frames} frames exceeds the {max_capture_frames}-frame capture pool"
        ));
    }
    let buffer_age = live_audio_frame_duration(buffer_frames as usize, sample_rate);
    if buffer_age > LIVE_AUDIO_MAX_CONFIGURED_BUFFER_AGE {
        return Err(format!(
            "Requested live audio buffer {buffer_frames} frames at {sample_rate} Hz spans {:.1} ms, above the {:.0} ms watchdog-safe limit",
            buffer_age.as_secs_f64() * 1_000.0,
            LIVE_AUDIO_MAX_CONFIGURED_BUFFER_AGE.as_secs_f64() * 1_000.0,
        ));
    }
    Ok(())
}

fn resolve_live_audio_stream_config(
    default_config: &rodio::cpal::SupportedStreamConfig,
    supported_configs: &[rodio::cpal::SupportedStreamConfigRange],
    request: &LiveAudioInputStartRequest,
) -> Result<SelectedLiveAudioInputConfig, String> {
    let default_channels = default_config.channels();
    let default_sample_rate = default_config.sample_rate().0;
    let default_sample_format = default_config.sample_format();
    if request.sample_rate == Some(0) {
        return Err("Live audio sample rate must be greater than zero".to_string());
    }
    if request.stream_channels == Some(0) {
        return Err("Live audio stream channel count must be greater than zero".to_string());
    }
    let requested_sample_format = request.sample_format.as_deref().map(str::trim);
    if requested_sample_format == Some("") {
        return Err("Live audio sample format must not be empty".to_string());
    }

    let target_sample_rate = request.sample_rate.unwrap_or(default_sample_rate);
    if let Some(buffer_frames) = request.buffer_frames {
        validate_live_audio_configured_buffer(buffer_frames, target_sample_rate)?;
    }
    let channels_match_default = request
        .stream_channels
        .map(|channels| channels == default_channels)
        .unwrap_or(true);
    let format_matches_default = requested_sample_format
        .map(|format| format == default_sample_format.to_string())
        .unwrap_or(true);
    if request.sample_rate.is_none() {
        if !channels_match_default {
            return Err(format!(
                "System-default live audio configuration uses {default_channels} channels, not {}",
                request.stream_channels.unwrap_or_default()
            ));
        }
        if !format_matches_default {
            return Err(format!(
                "System-default live audio configuration uses {default_sample_format}, not {}",
                requested_sample_format.unwrap_or_default()
            ));
        }
    }
    let use_default_stream = request.sample_rate.is_none()
        || (target_sample_rate == default_sample_rate
            && channels_match_default
            && format_matches_default);
    let (channels, sample_format, buffer_capability) = if use_default_stream {
        (
            default_channels,
            default_sample_format,
            live_audio_buffer_capability(default_config.buffer_size()),
        )
    } else {
        let candidate = supported_configs
            .iter()
            .filter(|range| {
                (range.min_sample_rate().0..=range.max_sample_rate().0)
                    .contains(&target_sample_rate)
                    && request
                        .stream_channels
                        .map(|channels| channels == range.channels())
                        .unwrap_or(true)
                    && requested_sample_format
                        .map(|format| format == range.sample_format().to_string())
                        .unwrap_or(true)
            })
            .min_by_key(|range| {
                let channel_rank = if request.stream_channels.is_some() {
                    (0, range.channels())
                } else {
                    live_audio_channel_rank(range.channels(), default_channels)
                };
                let buffer_rank = match live_audio_buffer_capability(range.buffer_size()) {
                    LiveAudioBufferCapability::Range {
                        min_frames,
                        max_frames,
                    } => (0_u8, min_frames, max_frames),
                    LiveAudioBufferCapability::Unknown => (1_u8, u32::MAX, u32::MAX),
                };
                (
                    channel_rank,
                    buffer_rank,
                    live_audio_sample_format_rank(range.sample_format(), default_sample_format),
                    range.min_sample_rate().0,
                    range.max_sample_rate().0,
                )
            })
            .ok_or_else(|| {
                format!(
                    "No supported live audio input configuration matches sample_rate={target_sample_rate}, channels={}, sample_format={}",
                    request
                        .stream_channels
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "auto".to_string()),
                    requested_sample_format.unwrap_or("auto"),
                )
            })?;
        (
            candidate.channels(),
            candidate.sample_format(),
            live_audio_buffer_capability(candidate.buffer_size()),
        )
    };

    request.channel_mix.validate(channels)?;
    if let Some(buffer_frames) = request.buffer_frames {
        if !live_audio_buffer_accepts(buffer_capability, buffer_frames) {
            return Err(format!(
                "Requested live audio buffer {buffer_frames} frames is outside the selected device range {buffer_capability:?}"
            ));
        }
    }
    Ok(SelectedLiveAudioInputConfig {
        stream_config: rodio::cpal::StreamConfig {
            channels,
            sample_rate: rodio::cpal::SampleRate(target_sample_rate),
            buffer_size: request
                .buffer_frames
                .map(rodio::cpal::BufferSize::Fixed)
                .unwrap_or(rodio::cpal::BufferSize::Default),
        },
        sample_format,
        buffer_capability,
        configured_buffer_frames: request.buffer_frames,
        channel_mix: request.channel_mix,
    })
}

#[derive(Clone)]
struct LiveAudioCaptureCallbackContext {
    channels: u16,
    sample_rate: u32,
    channel_mix: LiveAudioChannelMix,
    free_capture_slots: Arc<crossbeam_queue::ArrayQueue<LiveAudioSampleChunk>>,
    ready_capture_chunks: Arc<crossbeam_queue::ArrayQueue<LiveAudioSampleChunk>>,
    capture_telemetry: Arc<LiveAudioInputCaptureTelemetry>,
    safety: Arc<LiveAudioInputSafety>,
    worker_wake: std::thread::Thread,
}

#[derive(Clone)]
struct LiveAudioStreamErrorContext {
    deferred_terminal_fault: Arc<DeferredLiveAudioTerminalFaultLatch>,
    safety: Arc<LiveAudioInputSafety>,
    worker_wake: std::thread::Thread,
}

impl LiveAudioStreamErrorContext {
    fn defer_terminal_fault(&self, source: u32, kind: u32) -> bool {
        self.safety.mark_terminal_fault();
        let latched = self.deferred_terminal_fault.latch(source, kind);
        self.worker_wake.unpark();
        latched
    }
}

#[cfg(all(target_os = "windows", feature = "asio"))]
struct AsioBridgeCallbackContext {
    sample_rate: u32,
    capture: LiveAudioCaptureCallbackContext,
    errors: LiveAudioStreamErrorContext,
}

#[cfg(all(target_os = "windows", feature = "asio"))]
unsafe extern "C" fn asio_bridge_sample_callback(
    context: *mut std::ffi::c_void,
    samples: *const f32,
    len: usize,
    capture_delay_ns: u64,
    _callback_frames: u32,
) {
    if context.is_null() || samples.is_null() || len == 0 {
        return;
    }
    let context = unsafe { &*(context.cast::<AsioBridgeCallbackContext>()) };
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let samples = unsafe { std::slice::from_raw_parts(samples, len) };
        queue_live_audio_samples_with_delay(
            samples,
            1,
            context.sample_rate,
            LiveAudioChannelMix::AverageAll,
            Duration::from_nanos(capture_delay_ns),
            &context.capture.free_capture_slots,
            &context.capture.ready_capture_chunks,
            &context.capture.capture_telemetry,
            &context.capture.safety,
            &context.capture.worker_wake,
            |value| value,
        );
    }));
    if result.is_err() {
        context.errors.defer_terminal_fault(
            LIVE_AUDIO_TERMINAL_SOURCE_ASIO_ADAPTER,
            LIVE_AUDIO_TERMINAL_KIND_ADAPTER_PANIC,
        );
    }
}

#[cfg(all(target_os = "windows", feature = "asio"))]
unsafe extern "C" fn asio_bridge_event_callback(
    context: *mut std::ffi::c_void,
    severity: u32,
    kind: u32,
    _message: *const u8,
    _message_len: usize,
) {
    if context.is_null() || severity != 2 {
        return;
    }
    let context = unsafe { &*(context.cast::<AsioBridgeCallbackContext>()) };
    context
        .errors
        .defer_terminal_fault(LIVE_AUDIO_TERMINAL_SOURCE_ASIO_BRIDGE, kind);
}

#[cfg(all(target_os = "windows", feature = "asio"))]
struct AsioBridgeCapture {
    bridge: AsioBridgeLibrary,
    handle: usize,
    _callback_context: Box<AsioBridgeCallbackContext>,
}

#[cfg(all(target_os = "windows", feature = "asio"))]
impl AsioBridgeCapture {
    fn xrun_count(&self) -> u64 {
        unsafe { (self.bridge.api.xrun_count)(self.handle as *const std::ffi::c_void) }
    }
}

#[cfg(all(target_os = "windows", feature = "asio"))]
impl Drop for AsioBridgeCapture {
    fn drop(&mut self) {
        if self.handle == 0 {
            return;
        }
        let handle = self.handle as *mut std::ffi::c_void;
        let mut error = AsioBridgeString::default();
        let _ = unsafe { (self.bridge.api.stop)(handle, &mut error) };
        if !error.ptr.is_null() {
            let _ = self.bridge.take_string(error);
        }
        unsafe { (self.bridge.api.free)(handle) };
        self.handle = 0;
    }
}

#[cfg(all(target_os = "windows", feature = "asio"))]
fn build_asio_bridge_capture(
    device: &AsioBridgeDevice,
    selected: &SelectedLiveAudioInputConfig,
    capture: LiveAudioCaptureCallbackContext,
    errors: LiveAudioStreamErrorContext,
) -> Result<(AsioBridgeCapture, u32), String> {
    let configured_buffer_frames = selected
        .configured_buffer_frames
        .ok_or_else(|| "ASIO requires an explicit fixed buffer size".to_string())?;
    let sample_format = match selected.sample_format {
        rodio::cpal::SampleFormat::F32 => 1,
        rodio::cpal::SampleFormat::I16 => 2,
        rodio::cpal::SampleFormat::I24 => 3,
        rodio::cpal::SampleFormat::I32 => 4,
        rodio::cpal::SampleFormat::F64 => 5,
        format => return Err(format!("Unsupported ASIO sample format {format}")),
    };
    let channels = selected.stream_config.channels;
    let channel_mix = match selected.channel_mix {
        LiveAudioChannelMix::AverageAll => (0..channels)
            .map(|channel_index| AsioBridgeChannelMix {
                channel_index: u32::from(channel_index),
                gain: 1.0 / f32::from(channels.max(1)),
            })
            .collect::<Vec<_>>(),
        LiveAudioChannelMix::Single { channel_index } => vec![AsioBridgeChannelMix {
            channel_index: u32::from(channel_index),
            gain: 1.0,
        }],
        LiveAudioChannelMix::StereoPair {
            left_channel_index,
            right_channel_index,
        } => vec![
            AsioBridgeChannelMix {
                channel_index: u32::from(left_channel_index),
                gain: 0.5,
            },
            AsioBridgeChannelMix {
                channel_index: u32::from(right_channel_index),
                gain: 0.5,
            },
        ],
    };
    let bridge = AsioBridgeLibrary::load()?;
    let mut callback_context = Box::new(AsioBridgeCallbackContext {
        sample_rate: selected.stream_config.sample_rate.0,
        capture,
        errors,
    });
    let config = AsioBridgeStartConfig {
        struct_size: std::mem::size_of::<AsioBridgeStartConfig>() as u32,
        abi_version: SYNDOCAL_ASIO_ABI_VERSION,
        driver_id: device.driver_id.as_ptr(),
        driver_id_len: device.driver_id.len(),
        sample_rate_hz: selected.stream_config.sample_rate.0,
        input_channels: u32::from(channels),
        sample_format,
        fixed_buffer_frames: configured_buffer_frames,
        channel_mix: channel_mix.as_ptr(),
        channel_mix_len: channel_mix.len(),
        flags: 0,
        reserved: 0,
    };
    let mut handle = std::ptr::null_mut();
    let mut error = AsioBridgeString::default();
    let status = unsafe {
        (bridge.api.start)(
            &config,
            asio_bridge_sample_callback,
            asio_bridge_event_callback,
            callback_context.as_mut() as *mut AsioBridgeCallbackContext as *mut std::ffi::c_void,
            &mut handle,
            &mut error,
        )
    };
    let error = bridge.take_string(error);
    if status != 0 || handle.is_null() {
        let detail = if error.trim().is_empty() {
            format!("bridge status {status}")
        } else {
            error
        };
        return Err(format!("Failed to open explicit ASIO driver: {detail}"));
    }
    let capture = AsioBridgeCapture {
        bridge,
        handle: handle as usize,
        _callback_context: callback_context,
    };
    let mut actual_buffer_frames = 0_u32;
    let status = unsafe {
        (capture.bridge.api.actual_buffer_frames)(handle.cast_const(), &mut actual_buffer_frames)
    };
    if status != 0 || actual_buffer_frames == 0 {
        return Err(format!(
            "ASIO bridge could not report the opened buffer size (status {status})"
        ));
    }
    if actual_buffer_frames != configured_buffer_frames {
        return Err(format!(
            "ASIO opened {actual_buffer_frames} frames instead of the requested {configured_buffer_frames}; stream was closed"
        ));
    }
    Ok((capture, actual_buffer_frames))
}

fn build_live_audio_input_stream<T>(
    device: &rodio::cpal::Device,
    config: &rodio::cpal::StreamConfig,
    capture: LiveAudioCaptureCallbackContext,
    errors: LiveAudioStreamErrorContext,
) -> Result<rodio::cpal::Stream, rodio::cpal::BuildStreamError>
where
    T: rodio::cpal::SizedSample + Copy + Send + 'static,
    f32: rodio::cpal::FromSample<T>,
{
    use rodio::cpal::traits::DeviceTrait;

    let data_errors = errors.clone();
    device.build_input_stream(
        config,
        move |data: &[T], callback_info| {
            let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                queue_live_audio_samples(
                    data,
                    capture.channels,
                    capture.sample_rate,
                    capture.channel_mix,
                    callback_info,
                    &capture.free_capture_slots,
                    &capture.ready_capture_chunks,
                    &capture.capture_telemetry,
                    &capture.safety,
                    &capture.worker_wake,
                    |value| <f32 as rodio::cpal::Sample>::from_sample(value),
                )
            }));
            if result.is_err() {
                data_errors.defer_terminal_fault(
                    LIVE_AUDIO_TERMINAL_SOURCE_WASAPI_ADAPTER,
                    LIVE_AUDIO_TERMINAL_KIND_ADAPTER_PANIC,
                );
            }
        },
        move |error| {
            let kind = match error {
                rodio::cpal::StreamError::DeviceNotAvailable => {
                    LIVE_AUDIO_TERMINAL_KIND_DEVICE_NOT_AVAILABLE
                }
                rodio::cpal::StreamError::BackendSpecific { .. } => {
                    LIVE_AUDIO_TERMINAL_KIND_BACKEND_SPECIFIC
                }
            };
            errors.defer_terminal_fault(LIVE_AUDIO_TERMINAL_SOURCE_WASAPI_STREAM, kind);
        },
        None,
    )
}

fn build_wasapi_live_audio_capture(
    device: &rodio::cpal::Device,
    config: &rodio::cpal::StreamConfig,
    sample_format: rodio::cpal::SampleFormat,
    capture: LiveAudioCaptureCallbackContext,
    errors: LiveAudioStreamErrorContext,
) -> Result<LiveAudioCaptureStream, String> {
    use rodio::cpal::traits::StreamTrait;

    let stream = match sample_format {
        rodio::cpal::SampleFormat::I8 => {
            build_live_audio_input_stream::<i8>(device, config, capture.clone(), errors.clone())
        }
        rodio::cpal::SampleFormat::I16 => {
            build_live_audio_input_stream::<i16>(device, config, capture.clone(), errors.clone())
        }
        rodio::cpal::SampleFormat::I24 => build_live_audio_input_stream::<rodio::cpal::I24>(
            device,
            config,
            capture.clone(),
            errors.clone(),
        ),
        rodio::cpal::SampleFormat::I32 => {
            build_live_audio_input_stream::<i32>(device, config, capture.clone(), errors.clone())
        }
        rodio::cpal::SampleFormat::I64 => {
            build_live_audio_input_stream::<i64>(device, config, capture.clone(), errors.clone())
        }
        rodio::cpal::SampleFormat::U8 => {
            build_live_audio_input_stream::<u8>(device, config, capture.clone(), errors.clone())
        }
        rodio::cpal::SampleFormat::U16 => {
            build_live_audio_input_stream::<u16>(device, config, capture.clone(), errors.clone())
        }
        rodio::cpal::SampleFormat::U32 => {
            build_live_audio_input_stream::<u32>(device, config, capture.clone(), errors.clone())
        }
        rodio::cpal::SampleFormat::U64 => {
            build_live_audio_input_stream::<u64>(device, config, capture.clone(), errors.clone())
        }
        rodio::cpal::SampleFormat::F32 => {
            build_live_audio_input_stream::<f32>(device, config, capture.clone(), errors.clone())
        }
        rodio::cpal::SampleFormat::F64 => {
            build_live_audio_input_stream::<f64>(device, config, capture, errors)
        }
        format => return Err(format!("Unsupported audio input sample format {format:?}")),
    }
    .map_err(|error| format!("Failed to build audio input stream: {error}"))?;
    stream
        .play()
        .map_err(|error| format!("Failed to start audio input stream: {error}"))?;
    Ok(LiveAudioCaptureStream::Wasapi { _stream: stream })
}

#[tauri::command]
fn start_live_audio_input(
    state: State<'_, AppState>,
    request: LiveAudioInputStartRequest,
) -> Result<LiveAudioInputStatus, String> {
    use rodio::cpal::traits::DeviceTrait;

    let _lifecycle = state
        .live_audio_input_lifecycle
        .lock()
        .map_err(|_| "Live audio input lifecycle lock was poisoned".to_string())?;
    let mut active = state
        .live_audio_input
        .lock()
        .map_err(|_| "Live audio input state lock was poisoned".to_string())?;
    if active.is_some() {
        return Err(
            "Live audio input is already active or stopping; wait for Stop to finish".to_string(),
        );
    }

    let resolved =
        resolve_live_audio_input_device(&state, request.backend, request.device_id.as_deref())?;
    let device = resolved.device.clone();
    let selected = match &device {
        LiveAudioInputDevice::Wasapi(device) => {
            let default_config = device
                .default_input_config()
                .map_err(|error| format!("Failed to read audio input configuration: {error}"))?;
            let supported_configs = if request.sample_rate.is_some() {
                device
                    .supported_input_configs()
                    .map_err(|error| {
                        format!("Failed to read supported audio input configurations: {error}")
                    })?
                    .collect::<Vec<_>>()
            } else {
                Vec::new()
            };
            resolve_live_audio_stream_config(&default_config, &supported_configs, &request)?
        }
        #[cfg(all(target_os = "windows", feature = "asio"))]
        LiveAudioInputDevice::Asio(device) => {
            resolve_asio_live_audio_start_config(&resolved, device, &request)?
        }
    };
    let sample_format = selected.sample_format;
    let config = selected.stream_config.clone();
    let channels = config.channels.max(1);
    let sample_rate = config.sample_rate.0;
    let generation = allocate_live_audio_generation()?;
    let active_generation = Arc::new(AtomicU64::new(generation));
    let generation_gate = Arc::new(Mutex::new(()));
    let status = Arc::new(Mutex::new(LiveAudioInputStatus {
        running: true,
        device_id: resolved.device_id.clone(),
        device_name: Some(resolved.device_name.clone()),
        backend: Some(resolved.backend.clone()),
        sample_format: Some(sample_format.to_string()),
        configured_buffer_frames: selected.configured_buffer_frames,
        applied_buffer_frames: None,
        channel_mix: selected.channel_mix,
        sample_rate,
        channels,
        queue_capacity: LIVE_AUDIO_CAPTURE_SLOT_COUNT,
        ..LiveAudioInputStatus::default()
    }));
    let stop = Arc::new(AtomicBool::new(false));
    let capture_started = Arc::new(AtomicBool::new(false));
    let safety = Arc::new(LiveAudioInputSafety::default());
    let free_capture_slots = Arc::new(crossbeam_queue::ArrayQueue::new(
        LIVE_AUDIO_CAPTURE_SLOT_COUNT,
    ));
    let ready_capture_chunks = Arc::new(crossbeam_queue::ArrayQueue::new(
        LIVE_AUDIO_CAPTURE_SLOT_COUNT,
    ));
    for _ in 0..LIVE_AUDIO_CAPTURE_SLOT_COUNT {
        free_capture_slots
            .push(LiveAudioSampleChunk::new())
            .expect("preallocated live audio slot pool must have exact capacity");
    }
    let capture_telemetry = Arc::new(LiveAudioInputCaptureTelemetry::default());
    let deferred_terminal_fault = Arc::new(DeferredLiveAudioTerminalFaultLatch::default());
    let engine = state.engine.clone();
    let worker_stop = Arc::clone(&stop);
    let worker_capture_started = Arc::clone(&capture_started);
    let worker_status = Arc::clone(&status);
    let worker_safety = Arc::clone(&safety);
    let worker_free_slots = Arc::clone(&free_capture_slots);
    let worker_ready_chunks = Arc::clone(&ready_capture_chunks);
    let worker_telemetry = Arc::clone(&capture_telemetry);
    let worker_generation = Arc::clone(&active_generation);
    let worker_generation_gate = Arc::clone(&generation_gate);
    let worker_deferred_terminal_fault = Arc::clone(&deferred_terminal_fault);
    let worker_engine = engine.clone();
    let worker = std::thread::Builder::new()
        .name("syndocal-live-audio-fft".to_string())
        .spawn(move || {
            let run_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                run_live_audio_fft(
                    worker_free_slots,
                    worker_ready_chunks,
                    worker_telemetry,
                    sample_rate,
                    Arc::clone(&worker_generation),
                    Arc::clone(&worker_generation_gate),
                    worker_engine.clone(),
                    Arc::clone(&worker_stop),
                    worker_capture_started,
                    Arc::clone(&worker_status),
                    Arc::clone(&worker_safety),
                    worker_deferred_terminal_fault,
                )
            }));
            if run_result.is_err() && !worker_stop.load(Ordering::Acquire) {
                let _generation_gate = worker_generation_gate
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                fail_closed_live_audio(
                    &worker_engine,
                    worker_generation.load(Ordering::Acquire),
                    &worker_status,
                    &worker_safety,
                    true,
                    "Live audio FFT worker stopped unexpectedly".to_string(),
                );
            }
        })
        .map_err(|error| format!("Failed to start live audio FFT worker: {error}"))?;
    let worker_wake = worker.thread().clone();
    let capture_context = LiveAudioCaptureCallbackContext {
        channels,
        sample_rate,
        channel_mix: selected.channel_mix,
        free_capture_slots: Arc::clone(&free_capture_slots),
        ready_capture_chunks: Arc::clone(&ready_capture_chunks),
        capture_telemetry: Arc::clone(&capture_telemetry),
        safety: Arc::clone(&safety),
        worker_wake: worker_wake.clone(),
    };
    let error_context = LiveAudioStreamErrorContext {
        deferred_terminal_fault,
        safety: Arc::clone(&safety),
        worker_wake: worker_wake.clone(),
    };
    let stream_result: Result<(LiveAudioCaptureStream, Option<u32>), String> = match &device {
        LiveAudioInputDevice::Wasapi(device) => build_wasapi_live_audio_capture(
            device,
            &config,
            sample_format,
            capture_context,
            error_context,
        )
        .map(|stream| (stream, None)),
        #[cfg(all(target_os = "windows", feature = "asio"))]
        LiveAudioInputDevice::Asio(device) => {
            build_asio_bridge_capture(device, &selected, capture_context, error_context).map(
                |(stream, applied_buffer_frames)| {
                    (
                        LiveAudioCaptureStream::Asio { _stream: stream },
                        Some(applied_buffer_frames),
                    )
                },
            )
        }
    };
    let (stream, applied_buffer_frames) = match stream_result {
        Ok(stream) => stream,
        Err(error) => {
            stop.store(true, Ordering::Release);
            worker_wake.unpark();
            let _ = worker.join();
            return Err(error);
        }
    };
    if let Ok(mut current) = status.lock() {
        current.applied_buffer_frames = applied_buffer_frames;
    }
    capture_started.store(true, Ordering::Release);
    worker_wake.unpark();
    *active = Some(LiveAudioInput {
        generation: active_generation,
        generation_gate,
        stream: Some(stream),
        stop,
        worker: Some(worker),
        status: Arc::clone(&status),
        safety,
        ready_capture_chunks,
        capture_telemetry,
        engine,
    });
    drop(active);
    status
        .lock()
        .map_err(|_| "Live audio input status lock was poisoned".to_string())
        .map(|status| status.clone())
}

fn live_audio_frame_duration(frames: usize, sample_rate: u32) -> Duration {
    if sample_rate == 0 {
        return Duration::ZERO;
    }
    let nanos = (frames as u128)
        .saturating_mul(1_000_000_000)
        .checked_div(u128::from(sample_rate))
        .unwrap_or_default()
        .min(u64::MAX as u128) as u64;
    Duration::from_nanos(nanos)
}

fn mix_live_audio_frame<T: Copy>(
    frame: &[T],
    channel_mix: LiveAudioChannelMix,
    convert: &impl Fn(T) -> f32,
) -> f32 {
    let finite = |value: T| {
        let converted = convert(value);
        if converted.is_finite() {
            converted
        } else {
            0.0
        }
    };
    match channel_mix {
        LiveAudioChannelMix::AverageAll => {
            if frame.is_empty() {
                0.0
            } else {
                frame.iter().copied().map(finite).sum::<f32>() / frame.len() as f32
            }
        }
        LiveAudioChannelMix::Single { channel_index } => frame
            .get(channel_index as usize)
            .copied()
            .map(finite)
            .unwrap_or(0.0),
        LiveAudioChannelMix::StereoPair {
            left_channel_index,
            right_channel_index,
        } => match (
            frame.get(left_channel_index as usize),
            frame.get(right_channel_index as usize),
        ) {
            (Some(left), Some(right)) => (finite(*left) + finite(*right)) * 0.5,
            _ => 0.0,
        },
    }
}

fn queue_live_audio_samples<T: Copy>(
    data: &[T],
    channels: u16,
    sample_rate: u32,
    channel_mix: LiveAudioChannelMix,
    callback_info: &rodio::cpal::InputCallbackInfo,
    free_capture_slots: &crossbeam_queue::ArrayQueue<LiveAudioSampleChunk>,
    ready_capture_chunks: &crossbeam_queue::ArrayQueue<LiveAudioSampleChunk>,
    capture_telemetry: &LiveAudioInputCaptureTelemetry,
    safety: &LiveAudioInputSafety,
    worker_wake: &std::thread::Thread,
    convert: impl Fn(T) -> f32,
) {
    let timestamp = callback_info.timestamp();
    let device_delay = timestamp
        .callback
        .duration_since(&timestamp.capture)
        .unwrap_or_default();
    queue_live_audio_samples_with_delay(
        data,
        channels,
        sample_rate,
        channel_mix,
        device_delay,
        free_capture_slots,
        ready_capture_chunks,
        capture_telemetry,
        safety,
        worker_wake,
        convert,
    );
}

fn queue_live_audio_samples_with_delay<T: Copy>(
    data: &[T],
    channels: u16,
    sample_rate: u32,
    channel_mix: LiveAudioChannelMix,
    device_delay: Duration,
    free_capture_slots: &crossbeam_queue::ArrayQueue<LiveAudioSampleChunk>,
    ready_capture_chunks: &crossbeam_queue::ArrayQueue<LiveAudioSampleChunk>,
    capture_telemetry: &LiveAudioInputCaptureTelemetry,
    safety: &LiveAudioInputSafety,
    worker_wake: &std::thread::Thread,
    convert: impl Fn(T) -> f32,
) {
    if safety.terminal_faulted() {
        return;
    }
    let channels = channels.max(1) as usize;
    let callback_frames = data.len().div_ceil(channels);
    capture_telemetry
        .callback_count
        .fetch_add(1, Ordering::Relaxed);
    capture_telemetry
        .last_callback_frames
        .store(callback_frames as u64, Ordering::Relaxed);
    capture_telemetry
        .min_callback_frames
        .fetch_min(callback_frames as u64, Ordering::Relaxed);
    capture_telemetry
        .max_callback_frames
        .fetch_max(callback_frames as u64, Ordering::Relaxed);
    let callback_at = Instant::now();
    let capture_capacity_frames =
        LIVE_AUDIO_CAPTURE_SLOT_COUNT.saturating_mul(LIVE_AUDIO_CAPTURE_SLOT_FRAMES);
    let mut frame_offset = callback_frames.saturating_sub(capture_capacity_frames);
    if frame_offset > 0 {
        capture_telemetry.dropped_chunks.fetch_add(
            frame_offset.div_ceil(LIVE_AUDIO_CAPTURE_SLOT_FRAMES) as u64,
            Ordering::Relaxed,
        );
        capture_telemetry
            .dropped_frames
            .fetch_add(frame_offset as u64, Ordering::Relaxed);
    }
    while frame_offset < callback_frames {
        if safety.terminal_faulted() {
            return;
        }
        let mut chunk = if let Some(chunk) = free_capture_slots.pop() {
            chunk
        } else if let Some(chunk) = ready_capture_chunks.pop() {
            capture_telemetry
                .dropped_chunks
                .fetch_add(1, Ordering::Relaxed);
            capture_telemetry
                .dropped_frames
                .fetch_add(chunk.len as u64, Ordering::Relaxed);
            chunk
        } else {
            capture_telemetry
                .dropped_chunks
                .fetch_add(1, Ordering::Relaxed);
            capture_telemetry
                .dropped_frames
                .fetch_add((callback_frames - frame_offset) as u64, Ordering::Relaxed);
            break;
        };
        let chunk_frames = (callback_frames - frame_offset).min(LIVE_AUDIO_CAPTURE_SLOT_FRAMES);
        for local_frame in 0..chunk_frames {
            if safety.terminal_faulted() {
                chunk.len = 0;
                let _ = free_capture_slots.push(chunk);
                return;
            }
            let sample_start = (frame_offset + local_frame) * channels;
            let sample_end = (sample_start + channels).min(data.len());
            let mono = mix_live_audio_frame(&data[sample_start..sample_end], channel_mix, &convert);
            chunk.samples[local_frame] = if mono.is_finite() { mono } else { 0.0 };
        }
        chunk.len = chunk_frames;
        chunk.callback_at = callback_at;
        chunk.device_delay =
            device_delay.saturating_sub(live_audio_frame_duration(frame_offset, sample_rate));
        if let Err(mut chunk) = ready_capture_chunks.push(chunk) {
            capture_telemetry
                .dropped_chunks
                .fetch_add(1, Ordering::Relaxed);
            capture_telemetry
                .dropped_frames
                .fetch_add(chunk.len as u64, Ordering::Relaxed);
            chunk.len = 0;
            let _ = free_capture_slots.push(chunk);
            break;
        }
        capture_telemetry
            .queue_depth_high_water
            .fetch_max(ready_capture_chunks.len() as u64, Ordering::Relaxed);
        frame_offset += chunk_frames;
    }
    worker_wake.unpark();
}

fn sync_live_audio_capture_telemetry(
    status: &Mutex<LiveAudioInputStatus>,
    ready_capture_chunks: &crossbeam_queue::ArrayQueue<LiveAudioSampleChunk>,
    capture_telemetry: &LiveAudioInputCaptureTelemetry,
) {
    if let Ok(mut status) = status.lock() {
        status.dropped_chunks = capture_telemetry.dropped_chunks.load(Ordering::Relaxed);
        status.dropped_frames = capture_telemetry.dropped_frames.load(Ordering::Relaxed);
        status.callback_count = capture_telemetry.callback_count.load(Ordering::Relaxed);
        status.last_callback_frames = capture_telemetry
            .last_callback_frames
            .load(Ordering::Relaxed);
        status.applied_buffer_frames = u32::try_from(status.last_callback_frames)
            .ok()
            .filter(|frames| *frames > 0)
            .or(status.applied_buffer_frames);
        let min_callback_frames = capture_telemetry
            .min_callback_frames
            .load(Ordering::Relaxed);
        status.min_callback_frames = if min_callback_frames == u64::MAX {
            0
        } else {
            min_callback_frames
        };
        status.max_callback_frames = capture_telemetry
            .max_callback_frames
            .load(Ordering::Relaxed);
        status.capture_to_worker_us = capture_telemetry
            .capture_to_worker_us
            .load(Ordering::Relaxed);
        status.max_capture_to_worker_us = capture_telemetry
            .max_capture_to_worker_us
            .load(Ordering::Relaxed);
        status.queue_depth = ready_capture_chunks.len();
        status.queue_capacity = ready_capture_chunks.capacity();
        status.queue_depth_high_water = capture_telemetry
            .queue_depth_high_water
            .load(Ordering::Relaxed)
            .min(usize::MAX as u64) as usize;
    }
}

fn zero_live_audio_input_status(status: &mut LiveAudioInputStatus, error: String) {
    status.stale = true;
    status.bass = 0.0;
    status.mid = 0.0;
    status.high = 0.0;
    status.bands.fill(0.0);
    status.band_count = 0;
    status.rms = 0.0;
    status.peak = 0.0;
    status.spectral_flux = 0.0;
    status.spectral_centroid = 0.0;
    status.spectral_density_fast = 0.0;
    status.spectral_density_slow = 0.0;
    status.kick_strength = 0.0;
    status.snare_strength = 0.0;
    status.kick_event = false;
    status.snare_event = false;
    status.onset = false;
    status.onset_strength = 0.0;
    status.bpm = None;
    status.bpm_confidence = 0.0;
    status.beat_phase = 0.0;
    status.feature_sequence = 0;
    status.last_error = Some(error);
}

fn fail_closed_live_audio_with(
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
    terminal: bool,
    error: String,
    send_clear: impl FnOnce() -> Result<(), String>,
) {
    if !terminal && safety.terminal_faulted() {
        return;
    }
    if terminal && !safety.claim_terminal_fault_finalization() {
        return;
    }
    match status.lock() {
        Ok(mut status) => {
            if !terminal && safety.terminal_faulted() {
                return;
            }
            zero_live_audio_input_status(&mut status, error);
            status.safety_clear_pending = true;
            let result = send_clear();
            status.safety_clear_pending = result.is_err();
            safety.record_clear_result(&result);
        }
        Err(_) => {
            if !terminal && safety.terminal_faulted() {
                return;
            }
            let result = send_clear();
            safety.record_clear_result(&result);
        }
    }
}

fn latch_terminal_live_audio_fault_with(
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
    error: String,
    send_clear: impl FnOnce() -> Result<(), String>,
) {
    fail_closed_live_audio_with(status, safety, true, error, send_clear);
}

fn fail_closed_live_audio(
    engine: &EngineHandle,
    generation: u64,
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
    terminal: bool,
    error: String,
) {
    let send_clear = || engine.clear_live_audio_input(generation);
    if terminal {
        latch_terminal_live_audio_fault_with(status, safety, error, send_clear);
    } else {
        fail_closed_live_audio_with(status, safety, false, error, send_clear);
    }
}

fn deferred_live_audio_terminal_fault_message(fault: DeferredLiveAudioTerminalFault) -> String {
    match fault.source {
        LIVE_AUDIO_TERMINAL_SOURCE_WASAPI_STREAM => match fault.kind {
            LIVE_AUDIO_TERMINAL_KIND_DEVICE_NOT_AVAILABLE => {
                "WASAPI input device is no longer available".to_string()
            }
            LIVE_AUDIO_TERMINAL_KIND_BACKEND_SPECIFIC => {
                "WASAPI input stream reported a backend-specific fault".to_string()
            }
            kind => format!("WASAPI input stream reported terminal fault kind {kind}"),
        },
        LIVE_AUDIO_TERMINAL_SOURCE_WASAPI_ADAPTER => {
            "WASAPI sample callback panicked inside the application adapter".to_string()
        }
        LIVE_AUDIO_TERMINAL_SOURCE_ASIO_BRIDGE => {
            let detail = match fault.kind {
                1 => "ASIO input xrun",
                2 => "ASIO driver requested stream reset",
                3 => "ASIO driver requested resynchronization",
                4 => "ASIO driver changed the configured sample rate",
                5 => "explicit ASIO input device was lost",
                6 => "ASIO input callback gap exceeded 250 ms",
                7 => "ASIO realtime scheduling was denied",
                8 => "terminal ASIO backend error",
                9 => "ASIO callback payload was malformed",
                10 => "ASIO callback frame count changed after Start",
                _ => "ASIO bridge reported a terminal fault",
            };
            format!("ASIO terminal fault kind {}: {detail}", fault.kind)
        }
        LIVE_AUDIO_TERMINAL_SOURCE_ASIO_ADAPTER => {
            "ASIO sample callback panicked inside the application adapter".to_string()
        }
        source => format!(
            "Live audio callback reported terminal fault source {source} kind {}",
            fault.kind
        ),
    }
}

fn finalize_deferred_live_audio_terminal_fault_with(
    deferred: &DeferredLiveAudioTerminalFaultLatch,
    generation_gate: &Mutex<()>,
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
    send_clear: impl FnOnce() -> Result<(), String>,
) -> bool {
    let Some(fault) = deferred.claim() else {
        return false;
    };
    let error = deferred_live_audio_terminal_fault_message(fault);
    let _generation_gate = generation_gate
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    fail_closed_live_audio_with(status, safety, true, error, send_clear);
    true
}

fn finalize_deferred_live_audio_terminal_fault(
    deferred: &DeferredLiveAudioTerminalFaultLatch,
    generation: &AtomicU64,
    generation_gate: &Mutex<()>,
    engine: &EngineHandle,
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
) -> bool {
    finalize_deferred_live_audio_terminal_fault_with(
        deferred,
        generation_gate,
        status,
        safety,
        || engine.clear_live_audio_input(generation.load(Ordering::Acquire)),
    )
}

fn fail_closed_live_audio_if_worker_heartbeat_stale_with(
    generation: &AtomicU64,
    generation_gate: &Mutex<()>,
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
    mut worker_heartbeat_is_stale: impl FnMut() -> bool,
    send_clear: impl FnOnce(u64) -> Result<(), String>,
) -> Result<bool, String> {
    if !worker_heartbeat_is_stale() || safety.terminal_faulted() {
        return Ok(false);
    }

    let _generation_gate = generation_gate
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let status_already_stale = status
        .lock()
        .map_err(|_| "Live audio input status lock was poisoned".to_string())?
        .stale;
    if !worker_heartbeat_is_stale() || status_already_stale || safety.terminal_faulted() {
        return Ok(false);
    }

    let generation = generation.load(Ordering::Acquire);
    fail_closed_live_audio_with(
        status,
        safety,
        false,
        LIVE_AUDIO_WORKER_STALE_ERROR.to_string(),
        || send_clear(generation),
    );
    Ok(true)
}

fn request_live_audio_shutdown_with(
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
    send_clear: impl FnOnce() -> Result<(), String>,
) {
    safety.request_shutdown();
    fail_closed_live_audio_with(
        status,
        safety,
        true,
        "Live audio input Stop requested; waiting for the engine safety clear".to_string(),
        send_clear,
    );
}

fn request_live_audio_shutdown(
    engine: &EngineHandle,
    generation: u64,
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
) {
    request_live_audio_shutdown_with(status, safety, || engine.clear_live_audio_input(generation));
}

fn retry_live_audio_clear_with(
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
    send_clear: impl FnOnce() -> Result<(), String>,
) -> bool {
    if !safety.clear_pending() {
        return true;
    }
    let mut output_gate = status.lock().ok();
    if !safety.clear_pending() {
        return true;
    }
    let clear_result = send_clear();
    let cleared = clear_result.is_ok();
    if let Some(status) = output_gate.as_mut() {
        status.safety_clear_pending = !cleared;
    }
    safety.record_clear_result(&clear_result);
    cleared
}

fn retry_live_audio_clear(
    engine: &EngineHandle,
    generation: u64,
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
) -> bool {
    retry_live_audio_clear_with(status, safety, || engine.clear_live_audio_input(generation))
}

fn send_live_audio_clear_bounded_with(
    timeout: Duration,
    retry_interval: Duration,
    mut send_clear: impl FnMut() -> Result<(), String>,
) -> bool {
    let deadline = Instant::now() + timeout;
    loop {
        if send_clear().is_ok() {
            return true;
        }
        let now = Instant::now();
        if now >= deadline {
            return false;
        }
        std::thread::park_timeout(retry_interval.min(deadline.saturating_duration_since(now)));
    }
}

fn send_current_live_audio_clear_bounded_with(
    generation: &AtomicU64,
    timeout: Duration,
    retry_interval: Duration,
    mut send_clear: impl FnMut(u64) -> Result<(), String>,
) -> bool {
    let generation = generation.load(Ordering::Acquire);
    send_live_audio_clear_bounded_with(timeout, retry_interval, || send_clear(generation))
}

fn send_current_live_audio_clear_bounded(engine: &EngineHandle, generation: &AtomicU64) -> bool {
    send_current_live_audio_clear_bounded_with(
        generation,
        LIVE_AUDIO_STOP_CLEAR_RETRY,
        LIVE_AUDIO_STOP_CLEAR_RETRY_INTERVAL,
        |generation| engine.clear_live_audio_input(generation),
    )
}

fn recover_live_audio_input_status(
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
) -> bool {
    let Ok(mut status) = status.lock() else {
        safety.mark_terminal_fault();
        return false;
    };
    if safety.terminal_faulted() {
        return false;
    }
    if safety.clear_pending() || status.safety_clear_pending {
        return false;
    }
    status.stale = false;
    if status.last_error.as_deref() == Some(LIVE_AUDIO_STALE_ERROR) {
        status.last_error = None;
    }
    if status.last_error.as_deref() == Some(LIVE_AUDIO_WORKER_STALE_ERROR) {
        status.last_error = None;
    }
    true
}

#[derive(Debug, Clone, Copy)]
struct LiveAudioFeaturePresentation {
    frame: audio::live_features::LiveAudioFeatureFrame,
    beat_phase: f32,
}

#[derive(Debug, Default)]
struct PendingLiveAudioOnsets {
    sequences: [u64; protocol::MAX_LIVE_AUDIO_FRAME_ONSETS],
    len: usize,
}

impl PendingLiveAudioOnsets {
    fn push(&mut self, sequence: u64) -> Result<(), &'static str> {
        let Some(slot) = self.sequences.get_mut(self.len) else {
            return Err(LIVE_AUDIO_ONSET_QUEUE_OVERFLOW_ERROR);
        };
        *slot = sequence;
        self.len += 1;
        Ok(())
    }

    fn clear(&mut self) {
        self.len = 0;
    }

    fn frame_payload(&self) -> ([u64; protocol::MAX_LIVE_AUDIO_FRAME_ONSETS], u8) {
        (
            self.sequences,
            u8::try_from(self.len).expect("fixed live audio onset capacity must fit in u8"),
        )
    }

    fn publish_frame_with(
        &mut self,
        publish: impl FnOnce([u64; protocol::MAX_LIVE_AUDIO_FRAME_ONSETS], u8) -> Result<(), String>,
    ) -> Result<(), String> {
        let (sequences, count) = self.frame_payload();
        publish(sequences, count)?;
        self.clear();
        Ok(())
    }
}

fn finite_live_audio_level(value: f32) -> f32 {
    if value.is_finite() {
        value.clamp(0.0, 1.0)
    } else {
        0.0
    }
}

fn publish_live_audio_analysis_with(
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
    spectrum: &protocol::AudioSpectrumPoint,
    features: Option<&LiveAudioFeaturePresentation>,
    send_spectrum: impl FnOnce() -> Result<(), String>,
    send_clear: impl FnOnce() -> Result<(), String>,
) -> bool {
    let Ok(mut status) = status.lock() else {
        if safety.claim_terminal_fault_finalization() {
            let clear_result = send_clear();
            safety.record_clear_result(&clear_result);
        }
        return false;
    };
    if safety.terminal_faulted() || status.stale {
        return false;
    }
    match send_spectrum() {
        Ok(()) => {
            if safety.terminal_faulted() {
                return false;
            }
            status.safety_clear_pending = false;
            status.bass = finite_live_audio_level(spectrum.bass);
            status.mid = finite_live_audio_level(spectrum.mid);
            status.high = finite_live_audio_level(spectrum.high);
            if let Some(features) = features {
                let frame = features.frame;
                let band_count = frame
                    .band_count
                    .min(audio::live_features::MAX_LIVE_AUDIO_BANDS);
                status.band_count = band_count;
                status.bands.fill(0.0);
                for (target, source) in status.bands[..band_count].iter_mut().zip(frame.bands) {
                    *target = finite_live_audio_level(source);
                }
                status.rms = finite_live_audio_level(frame.rms);
                status.peak = finite_live_audio_level(frame.peak);
                status.spectral_flux = finite_live_audio_level(frame.spectral_flux);
                status.spectral_centroid = finite_live_audio_level(frame.spectral_centroid);
                status.spectral_density_fast = finite_live_audio_level(frame.spectral_density_fast);
                status.spectral_density_slow = finite_live_audio_level(frame.spectral_density_slow);
                status.kick_strength = finite_live_audio_level(frame.kick_strength);
                status.snare_strength = finite_live_audio_level(frame.snare_strength);
                status.kick_event = frame.kick_pulse;
                status.snare_event = frame.snare_pulse;
                status.onset = frame.onset;
                status.onset_strength = finite_live_audio_level(frame.onset_strength);
                status.bpm = frame.bpm.filter(|bpm| bpm.is_finite() && *bpm > 0.0);
                status.bpm_confidence = finite_live_audio_level(frame.bpm_confidence);
                status.beat_phase = if features.beat_phase.is_finite() {
                    features.beat_phase.rem_euclid(1.0)
                } else {
                    0.0
                };
                status.feature_sequence = frame.sequence;
            }
            status.analyzed_windows = status.analyzed_windows.saturating_add(1);
            true
        }
        Err(error) => {
            if !safety.claim_terminal_fault_finalization() {
                return false;
            }
            zero_live_audio_input_status(
                &mut status,
                format!("Live audio spectrum publish failed: {error}"),
            );
            status.safety_clear_pending = true;
            let clear_result = send_clear();
            status.safety_clear_pending = clear_result.is_err();
            safety.record_clear_result(&clear_result);
            false
        }
    }
}

#[cfg(test)]
fn publish_live_audio_spectrum_with(
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
    spectrum: &protocol::AudioSpectrumPoint,
    send_spectrum: impl FnOnce() -> Result<(), String>,
    send_clear: impl FnOnce() -> Result<(), String>,
) -> bool {
    publish_live_audio_analysis_with(status, safety, spectrum, None, send_spectrum, send_clear)
}

fn publish_live_audio_features(
    engine: &EngineHandle,
    generation: u64,
    captured_at: Instant,
    status: &Mutex<LiveAudioInputStatus>,
    safety: &LiveAudioInputSafety,
    spectrum: &protocol::AudioSpectrumPoint,
    features: &LiveAudioFeaturePresentation,
    pending_onsets: &mut PendingLiveAudioOnsets,
) -> bool {
    let published_spectrum = spectrum.clone();
    let feature_sequence = features.frame.sequence;
    let reactive_features = live_audio_reactive_features(features);
    publish_live_audio_analysis_with(
        status,
        safety,
        spectrum,
        Some(features),
        || {
            pending_onsets.publish_frame_with(|onset_feature_sequences, onset_count| {
                engine
                    .send(EngineCommand::PublishLiveAudioFrame {
                        frame: protocol::LiveAudioFrame {
                            generation,
                            feature_sequence,
                            spectrum: published_spectrum,
                            features: reactive_features,
                            onset_feature_sequences,
                            onset_count,
                        },
                        captured_at,
                    })
                    .map_err(|error| error.to_string())
            })
        },
        || engine.clear_live_audio_input(generation),
    )
}

fn live_audio_reactive_features(
    presentation: &LiveAudioFeaturePresentation,
) -> protocol::LiveAudioReactiveFeatures {
    let frame = presentation.frame;
    let band_count = frame
        .band_count
        .min(audio::live_features::MAX_LIVE_AUDIO_BANDS)
        .min(protocol::LIVE_AUDIO_FEATURE_BAND_CAPACITY);
    let mut bands = [0.0; protocol::LIVE_AUDIO_FEATURE_BAND_CAPACITY];
    for (target, source) in bands[..band_count].iter_mut().zip(frame.bands) {
        *target = finite_live_audio_level(source);
    }
    protocol::LiveAudioReactiveFeatures {
        band_count: u8::try_from(band_count)
            .expect("fixed live audio band capacity must fit in u8"),
        bands,
        rms: finite_live_audio_level(frame.rms),
        peak: finite_live_audio_level(frame.peak),
        spectral_flux: finite_live_audio_level(frame.spectral_flux),
        spectral_centroid: finite_live_audio_level(frame.spectral_centroid),
        spectral_density_fast: finite_live_audio_level(frame.spectral_density_fast),
        spectral_density_slow: finite_live_audio_level(frame.spectral_density_slow),
        kick_strength: finite_live_audio_level(frame.kick_strength),
        snare_strength: finite_live_audio_level(frame.snare_strength),
        kick_event: frame.kick_pulse,
        snare_event: frame.snare_pulse,
        onset: frame.onset,
        onset_strength: finite_live_audio_level(frame.onset_strength),
        bpm: frame.bpm.filter(|bpm| bpm.is_finite() && *bpm > 0.0),
        bpm_confidence: finite_live_audio_level(frame.bpm_confidence),
        beat_phase: if presentation.beat_phase.is_finite() {
            presentation.beat_phase.rem_euclid(1.0)
        } else {
            0.0
        },
    }
}

fn coalesce_live_audio_feature_pulses(
    frame: &mut audio::live_features::LiveAudioFeatureFrame,
    previous: Option<&audio::live_features::LiveAudioFeatureFrame>,
) {
    if let Some(previous) = previous {
        // The wire format exposes one pulse bit per published analysis frame. Preserve at
        // least one event while the worker coalesces analysis frames without allocating.
        frame.kick_pulse |= previous.kick_pulse;
        frame.snare_pulse |= previous.snare_pulse;
    }
}

fn live_audio_feature_spectrum(
    frame: &audio::live_features::LiveAudioFeatureFrame,
) -> protocol::AudioSpectrumPoint {
    let band_count = frame
        .band_count
        .min(audio::live_features::MAX_LIVE_AUDIO_BANDS);
    let maximum = |range: std::ops::Range<usize>| {
        range
            .take_while(|index| *index < band_count)
            .fold(0.0_f32, |level, index| {
                level.max(finite_live_audio_level(frame.bands[index]))
            })
    };
    protocol::AudioSpectrumPoint {
        time_ms: (frame.end_sample as f64 / f64::from(frame.sample_rate.max(1)) * 1_000.0) as u64,
        bass: maximum(0..5),
        mid: maximum(5..10),
        high: maximum(10..audio::live_features::MAX_LIVE_AUDIO_BANDS),
    }
}

fn live_audio_feature_beat_phase(
    frame: &audio::live_features::LiveAudioFeatureFrame,
    last_onset_end_sample: Option<u64>,
) -> f32 {
    let Some(bpm) = frame.bpm.filter(|bpm| bpm.is_finite() && *bpm > 0.0) else {
        return 0.0;
    };
    let Some(last_onset_end_sample) = last_onset_end_sample else {
        return 0.0;
    };
    let elapsed_samples = frame.end_sample.saturating_sub(last_onset_end_sample);
    let elapsed_seconds = elapsed_samples as f32 / frame.sample_rate.max(1) as f32;
    (elapsed_seconds * bpm / 60.0).rem_euclid(1.0)
}

fn run_live_audio_fft(
    free_capture_slots: Arc<crossbeam_queue::ArrayQueue<LiveAudioSampleChunk>>,
    ready_capture_chunks: Arc<crossbeam_queue::ArrayQueue<LiveAudioSampleChunk>>,
    capture_telemetry: Arc<LiveAudioInputCaptureTelemetry>,
    sample_rate: u32,
    generation: Arc<AtomicU64>,
    generation_gate: Arc<Mutex<()>>,
    engine: EngineHandle,
    stop: Arc<AtomicBool>,
    capture_started: Arc<AtomicBool>,
    status: Arc<Mutex<LiveAudioInputStatus>>,
    safety: Arc<LiveAudioInputSafety>,
    deferred_terminal_fault: Arc<DeferredLiveAudioTerminalFaultLatch>,
) {
    capture_telemetry.mark_worker_heartbeat();
    while !stop.load(Ordering::Acquire) && !capture_started.load(Ordering::Acquire) {
        std::thread::park_timeout(LIVE_AUDIO_RECEIVE_POLL_INTERVAL);
        capture_telemetry.mark_worker_heartbeat();
    }
    if stop.load(Ordering::Acquire) {
        return;
    }
    let mut feature_config =
        audio::live_features::LiveAudioFeatureConfig::for_sample_rate(sample_rate);
    feature_config.hop_size = (sample_rate as usize / 30).clamp(1, feature_config.fft_size);
    let mut analyzer = audio::live_features::LiveAudioFeatureAnalyzer::new(feature_config)
        .expect("validated live audio stream configuration must support feature analysis");
    let mut latest_feature = None;
    let mut latest_feature_captured_at: Option<Instant> = None;
    let mut last_onset_end_sample = None;
    let mut last_onset_strength = 0.0_f32;
    let mut pending_real_onsets = PendingLiveAudioOnsets::default();
    let mut onset_queue_overflowed = false;
    let mut watchdog = LiveAudioInputWatchdog::new(Instant::now());
    while !stop.load(Ordering::Acquire) {
        capture_telemetry.mark_worker_heartbeat();
        if finalize_deferred_live_audio_terminal_fault(
            &deferred_terminal_fault,
            &generation,
            &generation_gate,
            &engine,
            &status,
            &safety,
        ) {
            continue;
        }
        {
            let _generation_gate = generation_gate
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            retry_live_audio_clear(
                &engine,
                generation.load(Ordering::Acquire),
                &status,
                &safety,
            );
        }
        sync_live_audio_capture_telemetry(&status, &ready_capture_chunks, &capture_telemetry);
        if safety.terminal_faulted() {
            std::thread::park_timeout(LIVE_AUDIO_RECEIVE_POLL_INTERVAL);
            continue;
        }
        let mut received_samples = false;
        while let Some(mut chunk) = ready_capture_chunks.pop() {
            let chunk_captured_at = chunk
                .callback_at
                .checked_sub(chunk.device_delay)
                .unwrap_or(chunk.callback_at);
            let capture_to_worker = chunk
                .callback_at
                .elapsed()
                .saturating_add(chunk.device_delay);
            let capture_to_worker_us = capture_to_worker.as_micros().min(u64::MAX as u128) as u64;
            capture_telemetry
                .capture_to_worker_us
                .store(capture_to_worker_us, Ordering::Relaxed);
            capture_telemetry
                .max_capture_to_worker_us
                .fetch_max(capture_to_worker_us, Ordering::Relaxed);
            if capture_to_worker < LIVE_AUDIO_STALE_AFTER {
                received_samples |= chunk.len > 0;
                analyzer.push_samples(&chunk.samples[..chunk.len], |mut frame| {
                    coalesce_live_audio_feature_pulses(&mut frame, latest_feature.as_ref());
                    if frame.onset {
                        if pending_real_onsets.push(frame.sequence).is_err() {
                            onset_queue_overflowed = true;
                        }
                        last_onset_end_sample = Some(frame.end_sample);
                        last_onset_strength = frame.onset_strength;
                    }
                    let onset_age = last_onset_end_sample
                        .map(|sample| frame.end_sample.saturating_sub(sample))
                        .unwrap_or(u64::MAX);
                    let onset_hold_samples = u64::from(frame.sample_rate) / 10;
                    if onset_age <= onset_hold_samples {
                        frame.onset = true;
                        let release = 1.0 - onset_age as f32 / onset_hold_samples.max(1) as f32;
                        frame.onset_strength = frame
                            .onset_strength
                            .max(last_onset_strength * release.clamp(0.0, 1.0));
                    }
                    latest_feature = Some(frame);
                    latest_feature_captured_at = Some(
                        latest_feature_captured_at
                            .map_or(chunk_captured_at, |oldest| oldest.min(chunk_captured_at)),
                    );
                });
            }
            chunk.len = 0;
            free_capture_slots
                .push(chunk)
                .expect("live audio worker must return each capture slot exactly once");
        }
        if onset_queue_overflowed {
            pending_real_onsets.clear();
            let _generation_gate = generation_gate
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            fail_closed_live_audio(
                &engine,
                generation.load(Ordering::Acquire),
                &status,
                &safety,
                true,
                LIVE_AUDIO_ONSET_QUEUE_OVERFLOW_ERROR.to_string(),
            );
            continue;
        }
        sync_live_audio_capture_telemetry(&status, &ready_capture_chunks, &capture_telemetry);
        if !received_samples {
            if stop.load(Ordering::Acquire) || safety.terminal_faulted() {
                continue;
            }
            let now = Instant::now();
            if watchdog.mark_stale_if_due(now) {
                analyzer.reset();
                latest_feature = None;
                latest_feature_captured_at = None;
                last_onset_end_sample = None;
                last_onset_strength = 0.0;
                pending_real_onsets.clear();
                let _generation_gate = generation_gate
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                fail_closed_live_audio(
                    &engine,
                    generation.load(Ordering::Acquire),
                    &status,
                    &safety,
                    false,
                    LIVE_AUDIO_STALE_ERROR.to_string(),
                );
            }
            std::thread::park_timeout(watchdog.receive_wait(Instant::now()));
            continue;
        }
        if safety.terminal_faulted() {
            continue;
        }
        let status_requires_recovery = status.lock().map(|status| status.stale).unwrap_or(true);
        if watchdog.record_chunk(Instant::now()) || status_requires_recovery {
            analyzer.reset();
            latest_feature = None;
            latest_feature_captured_at = None;
            last_onset_end_sample = None;
            last_onset_strength = 0.0;
            pending_real_onsets.clear();
            let _generation_gate = generation_gate
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            if safety.terminal_faulted() {
                continue;
            }
            if rotate_live_audio_generation(&generation).is_err() {
                fail_closed_live_audio(
                    &engine,
                    generation.load(Ordering::Acquire),
                    &status,
                    &safety,
                    true,
                    "Live audio input generation counter was exhausted".to_string(),
                );
                continue;
            }
            if !recover_live_audio_input_status(&status, &safety) {
                watchdog.defer_recovery();
                continue;
            }
        }
        if let Some(frame) = latest_feature.take() {
            let Some(captured_at) = latest_feature_captured_at.take() else {
                let _generation_gate = generation_gate
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                fail_closed_live_audio(
                    &engine,
                    generation.load(Ordering::Acquire),
                    &status,
                    &safety,
                    true,
                    "Live audio feature timestamp was unavailable".to_string(),
                );
                continue;
            };
            let spectrum = live_audio_feature_spectrum(&frame);
            let beat_phase = live_audio_feature_beat_phase(&frame, last_onset_end_sample);
            let presentation = LiveAudioFeaturePresentation { frame, beat_phase };
            if !publish_live_audio_features(
                &engine,
                generation.load(Ordering::Acquire),
                captured_at,
                &status,
                &safety,
                &spectrum,
                &presentation,
                &mut pending_real_onsets,
            ) {
                continue;
            }
        }
    }
}

#[tauri::command]
fn stop_live_audio_input(state: State<'_, AppState>) -> Result<LiveAudioInputStatus, String> {
    let _lifecycle = state
        .live_audio_input_lifecycle
        .lock()
        .map_err(|_| "Live audio input lifecycle lock was poisoned".to_string())?;
    let (status, safety, engine, generation, generation_gate) = {
        let active = state
            .live_audio_input
            .lock()
            .map_err(|_| "Live audio input state lock was poisoned".to_string())?;
        let Some(input) = active.as_ref() else {
            return Ok(LiveAudioInputStatus::default());
        };
        (
            Arc::clone(&input.status),
            Arc::clone(&input.safety),
            input.engine.clone(),
            Arc::clone(&input.generation),
            Arc::clone(&input.generation_gate),
        )
    };
    {
        let _generation_gate = generation_gate
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        request_live_audio_shutdown(
            &engine,
            generation.load(Ordering::Acquire),
            &status,
            &safety,
        );
    }
    let pending_status = status
        .lock()
        .map_err(|_| "Live audio input status lock was poisoned".to_string())?
        .clone();
    if pending_status.safety_clear_pending {
        return Ok(pending_status);
    }
    let input = state
        .live_audio_input
        .lock()
        .map_err(|_| "Live audio input state lock was poisoned".to_string())?
        .take();
    drop(input);
    status
        .lock()
        .map_err(|_| "Live audio input status lock was poisoned".to_string())
        .map(|status| status.clone())
}

#[tauri::command]
fn live_audio_input_status(state: State<'_, AppState>) -> Result<LiveAudioInputStatus, String> {
    let _lifecycle = state
        .live_audio_input_lifecycle
        .lock()
        .map_err(|_| "Live audio input lifecycle lock was poisoned".to_string())?;
    let mut active = state
        .live_audio_input
        .lock()
        .map_err(|_| "Live audio input state lock was poisoned".to_string())?;
    let Some(input) = active.as_ref() else {
        return Ok(LiveAudioInputStatus::default());
    };
    let worker_finished = input
        .worker
        .as_ref()
        .is_some_and(|worker| worker.is_finished());
    if worker_finished && !input.safety.terminal_faulted() {
        let _generation_gate = input
            .generation_gate
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        fail_closed_live_audio(
            &input.engine,
            input.generation.load(Ordering::Acquire),
            &input.status,
            &input.safety,
            true,
            "Live audio FFT worker stopped unexpectedly".to_string(),
        );
    }
    fail_closed_live_audio_if_worker_heartbeat_stale_with(
        &input.generation,
        &input.generation_gate,
        &input.status,
        &input.safety,
        || input.capture_telemetry.worker_heartbeat_is_stale(),
        |generation| input.engine.clear_live_audio_input(generation),
    )?;
    if input.safety.clear_pending() {
        let _generation_gate = input
            .generation_gate
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        retry_live_audio_clear(
            &input.engine,
            input.generation.load(Ordering::Acquire),
            &input.status,
            &input.safety,
        );
    }
    sync_live_audio_capture_telemetry(
        &input.status,
        &input.ready_capture_chunks,
        &input.capture_telemetry,
    );
    #[cfg(all(target_os = "windows", feature = "asio"))]
    if let Some(LiveAudioCaptureStream::Asio { _stream }) = input.stream.as_ref() {
        if let Ok(mut status) = input.status.lock() {
            status.backend_xruns = _stream.xrun_count();
        }
    }
    let status = Arc::clone(&input.status);
    let shutdown_ready = input.safety.shutdown_requested()
        && !input.safety.clear_pending()
        && !status
            .lock()
            .map_err(|_| "Live audio input status lock was poisoned".to_string())?
            .safety_clear_pending;
    if !shutdown_ready {
        return status
            .lock()
            .map_err(|_| "Live audio input status lock was poisoned".to_string())
            .map(|status| status.clone());
    }
    let input = active.take();
    drop(active);
    drop(input);
    status
        .lock()
        .map_err(|_| "Live audio input status lock was poisoned".to_string())
        .map(|status| status.clone())
}

#[tauri::command]
fn live_audio_input_levels(state: State<'_, AppState>) -> Result<LiveAudioInputLevels, String> {
    let active = state
        .live_audio_input
        .lock()
        .map_err(|_| "Live audio input state lock was poisoned".to_string())?;
    let Some(input) = active.as_ref() else {
        return Ok(LiveAudioInputLevels::default());
    };
    input
        .status
        .lock()
        .map_err(|_| "Live audio input status lock was poisoned".to_string())
        .map(|status| LiveAudioInputLevels::from_status(&status))
}

#[tauri::command]
fn stop_video_layer_audio_monitor(
    state: State<'_, AppState>,
    layer_id: VideoLayerId,
) -> Result<VideoAudioMonitorStatus, String> {
    let current_action = state
        .engine
        .video_audio_runtime_snapshot()
        .auto_vj_status
        .last_action;
    {
        let mut handoff = state
            .program_audio_handoff
            .state
            .lock()
            .map_err(|_| "Program audio handoff lock was poisoned".to_string())?;
        if handoff.desired_layer_id == Some(layer_id) {
            state.program_audio_handoff.invalidate_in_flight();
            handoff.pending_job = None;
            handoff.desired_layer_id = None;
            if handoff.owned_layer_id == Some(layer_id) {
                handoff.owned_layer_id = None;
            }
            handoff.suppress_stopped_layer_action(layer_id, current_action.as_ref());
        } else if handoff.owned_layer_id == Some(layer_id) {
            handoff.owned_layer_id = None;
        }
    }
    let mut audio = state
        .media_audio
        .lock()
        .map_err(|_| "Media audio monitor lock was poisoned".to_string())?;
    audio.stop(layer_id);
    Ok(audio.status())
}

#[tauri::command]
fn set_video_layer_audio_monitor_volume(
    state: State<'_, AppState>,
    layer_id: VideoLayerId,
    volume: f32,
) -> Result<VideoAudioMonitorStatus, String> {
    if !volume.is_finite() {
        return Err("Audio monitor volume must be finite".to_string());
    }
    let mut audio = state
        .media_audio
        .lock()
        .map_err(|_| "Media audio monitor lock was poisoned".to_string())?;
    audio.set_volume(layer_id, volume)?;
    Ok(audio.status())
}

#[tauri::command]
fn video_audio_monitor_status(
    state: State<'_, AppState>,
) -> Result<VideoAudioMonitorStatus, String> {
    state
        .media_audio
        .lock()
        .map_err(|_| "Media audio monitor lock was poisoned".to_string())
        .map(|mut audio| audio.status())
}

fn launched_video_clip_state(current: &VideoLayerState, fade_ms: u64) -> VideoLayerState {
    let mut next = current.clone();
    next.enabled = true;
    next.playing = true;
    next.position_ms = if next.loop_enabled {
        next.loop_start_ms
    } else {
        0
    };
    next.opacity = if fade_ms == 0 { 1.0 } else { 0.0 };
    next
}

fn stopped_video_clip_state(current: &VideoLayerState, fade_ms: u64) -> VideoLayerState {
    let mut next = current.clone();
    next.playing = false;
    if fade_ms == 0 {
        next.opacity = 0.0;
    }
    next
}

