fn validate_effect_update_kind(
    snapshot: &EngineSnapshot,
    effect_id: EffectId,
    expected: EffectKind,
) -> Result<(), String> {
    let effect = snapshot
        .effects
        .iter()
        .find(|effect| effect.id == effect_id)
        .ok_or_else(|| format!("Effect {effect_id} was not found"))?;
    if effect.effect_type != expected {
        return Err(format!(
            "Effect {effect_id} is {:?}, not {:?}; change the Type to start a new effect",
            effect.effect_type, expected
        ));
    }
    Ok(())
}

#[tauri::command]
fn save_node_graph(
    state: State<'_, AppState>,
    mut graph: NodeGraphSummary,
) -> Result<NodeGraphId, String> {
    if graph.id == 0 {
        graph.id = state.engine.allocate_node_graph_id();
    }
    graph.audio_runtime.clear();
    validate_node_graph_summary(&graph, &state.engine.snapshot())?;
    state.engine.upsert_node_graph(graph.clone())?;
    Ok(graph.id)
}

#[tauri::command]
fn set_node_graph_enabled(
    state: State<'_, AppState>,
    graph_id: NodeGraphId,
    enabled: bool,
) -> Result<(), String> {
    if !state
        .engine
        .snapshot()
        .node_graphs
        .iter()
        .any(|graph| graph.id == graph_id)
    {
        return Err(format!("Node graph {graph_id} was not found"));
    }
    state.engine.set_node_graph_enabled(graph_id, enabled)
}

