#[tauri::command]
fn sync_external_video_transports(
    state: State<'_, AppState>,
) -> Result<ExternalVideoTransportSyncResponse, String> {
    let _transition_guard = state.output_ownership_transition.lock().map_err(|_| {
        let error = "Output ownership transition lock was poisoned".to_string();
        state
            .engine
            .mark_output_ownership_transition_failure(error.clone());
        error
    })?;
    #[cfg(all(feature = "spout", target_os = "windows", target_arch = "x86_64"))]
    harvest_spout_output_failures(state.spout_transport.as_ref(), &state.engine)?;
    let role = state.engine.output_ownership_status().role;
    let mut transition = state
        .engine
        .begin_output_ownership_transition(role)
        .map_err(|error| format!("External video sync admission failed: {error}"))?;
    if let Err(error) = state.engine.fence_output_ownership() {
        transition.fail(error.clone());
        return Err(error);
    }
    let snapshot = state.engine.snapshot();
    let result = sync_external_video_transports_from_snapshot(
        &snapshot,
        role,
        state.external_video_transport.as_ref(),
        state.external_video_transport_events.as_ref(),
        state.capture_transport.as_ref(),
        #[cfg(feature = "ndi")]
        state.ndi_transport.as_ref(),
        #[cfg(all(feature = "spout", target_os = "windows", target_arch = "x86_64"))]
        state.spout_transport.as_ref(),
        #[cfg(any(
            feature = "ndi",
            all(feature = "spout", target_os = "windows", target_arch = "x86_64")
        ))]
        &state.engine,
        #[cfg(any(
            feature = "ndi",
            all(feature = "spout", target_os = "windows", target_arch = "x86_64")
        ))]
        None,
        Some(&mut transition),
    );
    finish_external_video_transport_maintenance_transition(transition, result)
}

#[tauri::command]
fn get_video_runtime_status() -> VideoRuntimeStatus {
    video::video_runtime_status()
}

#[tauri::command]
fn get_video_preview_diagnostics(
    state: State<'_, AppState>,
) -> Result<VideoPreviewDiagnostics, String> {
    let snapshot = state.engine.snapshot();
    let renderer = state
        .video_preview
        .lock()
        .map_err(|_| "Video preview renderer lock was poisoned".to_string())?;
    let provider = renderer.frame_provider();
    let config = renderer.config();
    let prefetch_count = provider.prefetch_count();
    let prefetch_interval_ms = provider.prefetch_interval_ms();
    let bpm = provider.bpm();
    Ok(VideoPreviewDiagnostics {
        queue_count: renderer.queue_count(),
        frame_queue_capacity: config.frame_queue_capacity,
        still_image_cache_len: provider.still_image_cache_len(),
        decoder_cache_len: provider.decoder().cache_len(),
        decoder_diagnostics: provider.decoder().diagnostics(),
        isf_pipeline_count: renderer.isf_pipeline_count(),
        isf_last_stack_stage_count: renderer.isf_last_stack_stage_count(),
        isf_last_stack_render_us: renderer.isf_last_stack_render_us(),
        last_isf_error: renderer.last_isf_error().map(str::to_string),
        isf_stage_errors: renderer.last_isf_stage_errors().to_vec(),
        prefetch_count,
        prefetch_interval_ms,
        bpm,
        layer_queues: snapshot
            .video
            .layers
            .iter()
            .map(|layer| {
                let queue_len = renderer.queue_len(layer.id);
                let expected_positions_ms = video::preview_prefetch_positions_ms(
                    layer,
                    prefetch_count,
                    prefetch_interval_ms,
                    bpm,
                );
                let expected_queue_len = expected_positions_ms
                    .len()
                    .min(config.frame_queue_capacity.max(1));
                VideoPreviewQueueSummary {
                    layer_id: layer.id,
                    label: layer.label.clone(),
                    source_kind: layer.source.kind.clone(),
                    position_ms: layer.state.position_ms,
                    source_duration_ms: layer
                        .source
                        .metadata
                        .as_ref()
                        .and_then(|metadata| metadata.duration_ms),
                    playing: layer.state.playing,
                    effective_speed: video::effective_speed(&layer.state, provider.bpm()),
                    queue_len,
                    expected_queue_len,
                    expected_positions_ms,
                    ready: queue_len >= expected_queue_len,
                }
            })
            .collect(),
        output_decode_previews: video_output_decode_preview_summaries(
            &snapshot.video,
            config,
            prefetch_count,
            prefetch_interval_ms,
            bpm,
        ),
    })
}

fn video_output_decode_preview_summaries(
    snapshot: &protocol::VideoSnapshot,
    config: video::VideoRuntimeConfig,
    prefetch_count: usize,
    prefetch_interval_ms: u64,
    bpm: Option<f32>,
) -> Vec<VideoOutputDecodePreviewSummary> {
    let scheduler_capacity = snapshot
        .layers
        .len()
        .max(1)
        .saturating_mul(prefetch_count.saturating_add(1).max(1));
    snapshot
        .outputs
        .iter()
        .map(|output| {
            let mut scheduler = video::VideoDecodeScheduler::new(scheduler_capacity.max(1));
            let result = scheduler.push_output_preview(
                snapshot,
                output.id,
                config.preview_width,
                config.preview_height,
                prefetch_count,
                prefetch_interval_ms,
                bpm,
            );
            let (report, error) = match result {
                Ok(report) => (Some(report), None),
                Err(error) => (None, Some(format!("{error:?}"))),
            };
            VideoOutputDecodePreviewSummary {
                output_id: output.id,
                label: output.label.clone(),
                width: output.width,
                height: output.height,
                enabled: output.enabled,
                blackout: output.blackout,
                report,
                error,
            }
        })
        .collect()
}

#[cfg(test)]
fn expected_video_preview_queue_len(
    layer: &protocol::VideoLayerSummary,
    prefetch_count: usize,
) -> usize {
    if matches!(layer.source.kind, VideoSourceKind::StillImage) || prefetch_count == 0 {
        1
    } else {
        prefetch_count.saturating_add(1)
    }
}

#[tauri::command]
fn start_video_output_recording(
    window: WebviewWindow,
    state: State<'_, AppState>,
    output_id: VideoOutputId,
    frame_rate: Option<u32>,
    include_audio: Option<bool>,
) -> Result<Option<VideoRecordingStatus>, String> {
    let snapshot = state.engine.snapshot();
    let output = snapshot
        .video
        .outputs
        .iter()
        .find(|output| output.id == output_id)
        .ok_or_else(|| format!("Video output {output_id} was not found"))?;
    if output.width == 0 || output.height == 0 || output.width > 4096 || output.height > 4096 {
        return Err("Recording output dimensions must be between 1 and 4096 pixels".to_string());
    }
    let frame_rate = frame_rate.unwrap_or(30).clamp(1, 60);
    let audio_requested = include_audio.unwrap_or(false);
    let audio_inputs = if audio_requested {
        let media_audio = state
            .media_audio
            .lock()
            .map_err(|_| "Media audio state lock was poisoned".to_string())?;
        recording_audio_inputs(&snapshot, output_id, &media_audio.sources)
    } else {
        Vec::new()
    };
    let default_name = format!(
        "{}-{}.mp4",
        sanitize_file_name_component(&output.label),
        current_unix_ms()
    );
    let Some(path) = parented_file_dialog(&window)
        .add_filter("MP4 video", &["mp4"])
        .set_file_name(&default_name)
        .save_file()
    else {
        return Ok(None);
    };
    let mut runtime = state
        .video_recording
        .lock()
        .map_err(|_| "Video recording state lock was poisoned".to_string())?;
    if runtime
        .status
        .lock()
        .map(|status| status.active)
        .unwrap_or(false)
    {
        return Err("A video output recording is already active".to_string());
    }
    if let Some(worker) = runtime.worker.take() {
        let _ = worker.join();
    }
    let stop = Arc::new(AtomicBool::new(false));
    let status = Arc::new(Mutex::new(VideoRecordingStatus {
        active: true,
        output_id: Some(output_id),
        path: Some(path.to_string_lossy().to_string()),
        width: output.width,
        height: output.height,
        frame_rate,
        frames_written: 0,
        dropped_frames: 0,
        audio_requested,
        audio_included: !audio_inputs.is_empty(),
        audio_track_count: audio_inputs.len(),
        started_unix_ms: Some(current_unix_ms().min(u64::MAX as u128) as u64),
        last_error: None,
    }));
    let worker_stop = Arc::clone(&stop);
    let worker_status = Arc::clone(&status);
    let renderer = Arc::clone(&state.video_preview);
    let engine = state.engine.clone();
    let width = output.width;
    let height = output.height;
    let worker = std::thread::Builder::new()
        .name("syndocal-video-recorder".to_string())
        .spawn(move || {
            run_video_output_recording(
                engine,
                renderer,
                output_id,
                path,
                width,
                height,
                frame_rate,
                audio_inputs,
                worker_stop,
                worker_status,
            );
        })
        .map_err(|error| format!("Failed to start video recording worker: {error}"))?;
    runtime.stop = Some(stop);
    runtime.worker = Some(worker);
    runtime.status = status;
    Ok(runtime.status.lock().ok().map(|status| status.clone()))
}

fn recording_audio_inputs(
    snapshot: &EngineSnapshot,
    output_id: VideoOutputId,
    sources: &HashMap<VideoLayerId, MediaAudioSourceConfig>,
) -> Vec<RecordingAudioInput> {
    let Some(output) = snapshot
        .video
        .outputs
        .iter()
        .find(|output| output.id == output_id)
    else {
        return Vec::new();
    };
    let layer_ids = snapshot
        .video
        .compositions
        .iter()
        .find(|composition| composition.id == output.composition_id)
        .map(|composition| {
            composition
                .layer_ids
                .iter()
                .copied()
                .collect::<HashSet<_>>()
        })
        .unwrap_or_default();
    let mut inputs = sources
        .iter()
        .filter_map(|(layer_id, source)| {
            if !layer_ids.contains(layer_id) || source.volume <= 0.0 {
                return None;
            }
            let layer = snapshot
                .video
                .layers
                .iter()
                .find(|layer| layer.id == *layer_id)?;
            if !layer.state.enabled || !layer.state.playing {
                return None;
            }
            Some((
                *layer_id,
                RecordingAudioInput {
                    path: source.path.clone(),
                    position_ms: layer.state.position_ms,
                    volume: source.volume.clamp(0.0, 2.0),
                    speed: layer.state.speed.abs().clamp(0.25, 4.0),
                    loop_enabled: layer.state.loop_enabled,
                },
            ))
        })
        .collect::<Vec<_>>();
    inputs.sort_by_key(|(layer_id, _)| *layer_id);
    inputs.into_iter().map(|(_, input)| input).collect()
}

fn sanitize_file_name_component(value: &str) -> String {
    let sanitized = value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() || matches!(character, '-' | '_') {
                character
            } else {
                '_'
            }
        })
        .collect::<String>();
    let sanitized = sanitized.trim_matches('_');
    if sanitized.is_empty() {
        "syndocal-output".to_string()
    } else {
        sanitized.to_string()
    }
}

fn video_recording_ffmpeg_command(
    ffmpeg: impl AsRef<OsStr>,
    path: &Path,
    width: u32,
    height: u32,
    frame_rate: u32,
    audio_inputs: &[RecordingAudioInput],
) -> Command {
    let dimensions = format!("{width}x{height}");
    let rate = frame_rate.to_string();
    let mut command = Command::new(ffmpeg);
    command
        .args(["-hide_banner", "-loglevel", "error", "-y", "-f", "rawvideo"])
        .args([
            "-pix_fmt",
            "rgba",
            "-s",
            &dimensions,
            "-r",
            &rate,
            "-i",
            "pipe:0",
        ]);
    let audio_filter = configure_recording_audio_inputs(&mut command, audio_inputs);
    command.args(["-map", "0:v:0"]);
    if let Some(audio_filter) = audio_filter {
        command
            .args(["-filter_complex", &audio_filter, "-map", "[aout]"])
            .args(["-c:a", "aac", "-b:a", "192k", "-shortest"]);
    } else {
        command.arg("-an");
    }
    command
        .args([
            "-c:v", "libx264", "-preset", "veryfast", "-pix_fmt", "yuv420p",
        ])
        .arg(path)
        .stdin(Stdio::piped())
        .stderr(Stdio::piped());
    command
}

/// A single output-preview input captured in the same order as the NDI and
/// Spout output workers. The ownership epoch fences all C1 renderer caches,
/// while the snapshot carries the matching runtime clip-slot truth.
///
/// Keep the epoch read before the snapshot: this is the output ownership
/// boundary used by the production transport renderers as well.
struct VideoOutputPreviewEffectSnapshot {
    snapshot: EngineSnapshot,
    project_render_epoch: u64,
}

impl VideoOutputPreviewEffectSnapshot {
    fn render_context(&self) -> video::VideoEffectRenderContext<'_> {
        video::VideoEffectRenderContext {
            clip_runtime: &self.snapshot.video_clip_runtime,
            project_render_epoch: self.project_render_epoch,
        }
    }
}

fn capture_video_output_preview_effect_snapshot(
    engine: &EngineHandle,
) -> VideoOutputPreviewEffectSnapshot {
    let project_render_epoch = engine.output_ownership_status().epoch;
    let snapshot = engine.snapshot();
    VideoOutputPreviewEffectSnapshot {
        snapshot,
        project_render_epoch,
    }
}

fn run_video_output_recording(
    engine: EngineHandle,
    renderer: Arc<Mutex<AppVideoPreviewRenderer>>,
    output_id: VideoOutputId,
    path: PathBuf,
    width: u32,
    height: u32,
    frame_rate: u32,
    audio_inputs: Vec<RecordingAudioInput>,
    stop: Arc<AtomicBool>,
    status: Arc<Mutex<VideoRecordingStatus>>,
) {
    let ffmpeg = env::var_os("SYNDOCAL_FFMPEG").unwrap_or_else(|| "ffmpeg".into());
    let mut command =
        video_recording_ffmpeg_command(ffmpeg, &path, width, height, frame_rate, &audio_inputs);
    let mut child = match command.spawn() {
        Ok(child) => child,
        Err(error) => {
            finish_video_recording_status(
                &status,
                Some(format!("Failed to start FFmpeg: {error}")),
            );
            return;
        }
    };
    let Some(mut stdin) = child.stdin.take() else {
        finish_video_recording_status(&status, Some("FFmpeg stdin was unavailable".to_string()));
        let _ = child.kill();
        return;
    };
    let frame_interval = Duration::from_secs_f64(1.0 / frame_rate as f64);
    let mut next_frame_at = Instant::now();
    while !stop.load(Ordering::Relaxed) {
        let output_preview = capture_video_output_preview_effect_snapshot(&engine);
        let frame = renderer.lock().ok().and_then(|mut renderer| {
            renderer
                .frame_provider_mut()
                .set_bpm(Some(output_preview.snapshot.clock.bpm));
            renderer
                .render_output_preview_with_effects_and_transitions(
                    &output_preview.snapshot.video,
                    output_preview.render_context(),
                    &output_preview.snapshot.video_transition_runtime,
                    output_id,
                    width,
                    height,
                )
                .ok()
        });
        match frame {
            Some(frame) if frame.format == video::VideoPixelFormat::Rgba8 => {
                if let Err(error) = stdin.write_all(&frame.data) {
                    finish_video_recording_status(
                        &status,
                        Some(format!("FFmpeg pipe failed: {error}")),
                    );
                    let _ = child.kill();
                    return;
                }
                if let Ok(mut current) = status.lock() {
                    current.frames_written = current.frames_written.saturating_add(1);
                }
            }
            _ => {
                if let Ok(mut current) = status.lock() {
                    current.dropped_frames = current.dropped_frames.saturating_add(1);
                }
            }
        }
        next_frame_at += frame_interval;
        let now = Instant::now();
        if next_frame_at > now {
            std::thread::sleep(next_frame_at - now);
        } else if now.duration_since(next_frame_at) > frame_interval {
            let missed = (now.duration_since(next_frame_at).as_secs_f64()
                / frame_interval.as_secs_f64()) as u64;
            if let Ok(mut current) = status.lock() {
                current.dropped_frames = current.dropped_frames.saturating_add(missed);
            }
            next_frame_at = now;
        }
    }
    drop(stdin);
    match child.wait_with_output() {
        Ok(output) if output.status.success() => finish_video_recording_status(&status, None),
        Ok(output) => finish_video_recording_status(
            &status,
            Some(format!(
                "FFmpeg exited with {}: {}",
                output.status,
                String::from_utf8_lossy(&output.stderr).trim()
            )),
        ),
        Err(error) => {
            finish_video_recording_status(&status, Some(format!("FFmpeg wait failed: {error}")))
        }
    }
}

fn configure_recording_audio_inputs(
    command: &mut Command,
    inputs: &[RecordingAudioInput],
) -> Option<String> {
    if inputs.is_empty() {
        return None;
    }
    let mut chains = Vec::with_capacity(inputs.len() + 1);
    for (index, input) in inputs.iter().enumerate() {
        if input.loop_enabled {
            command.args(["-stream_loop", "-1"]);
        }
        command
            .args(["-ss", &format!("{:.6}", input.position_ms as f64 / 1_000.0)])
            .arg("-i")
            .arg(&input.path);
        let output_label = if inputs.len() == 1 {
            "aout".to_string()
        } else {
            format!("a{index}")
        };
        chains.push(format!(
            "[{}:a]volume={:.6},{},apad[{}]",
            index + 1,
            input.volume,
            ffmpeg_atempo_filter(input.speed),
            output_label
        ));
    }
    if inputs.len() > 1 {
        let labels = (0..inputs.len())
            .map(|index| format!("[a{index}]"))
            .collect::<String>();
        chains.push(format!(
            "{labels}amix=inputs={}:duration=longest:dropout_transition=0[aout]",
            inputs.len()
        ));
    }
    Some(chains.join(";"))
}

fn ffmpeg_atempo_filter(speed: f32) -> String {
    let mut remaining = if speed.is_finite() {
        speed.abs().clamp(0.25, 4.0)
    } else {
        1.0
    };
    let mut filters = Vec::new();
    while remaining < 0.5 - f32::EPSILON {
        filters.push("atempo=0.5".to_string());
        remaining /= 0.5;
    }
    while remaining > 2.0 + f32::EPSILON {
        filters.push("atempo=2".to_string());
        remaining /= 2.0;
    }
    filters.push(format!("atempo={remaining:.6}"));
    filters.join(",")
}

fn finish_video_recording_status(status: &Mutex<VideoRecordingStatus>, error: Option<String>) {
    if let Ok(mut current) = status.lock() {
        current.active = false;
        current.last_error = error;
    }
}

#[tauri::command]
fn stop_video_output_recording(state: State<'_, AppState>) -> Result<VideoRecordingStatus, String> {
    stop_video_output_recording_runtime(&state.video_recording)
}

#[tauri::command]
fn video_output_recording_status(
    state: State<'_, AppState>,
) -> Result<VideoRecordingStatus, String> {
    let runtime = state
        .video_recording
        .lock()
        .map_err(|_| "Video recording state lock was poisoned".to_string())?;
    runtime
        .status
        .lock()
        .map_err(|_| "Video recording status lock was poisoned".to_string())
        .map(|status| status.clone())
}

#[tauri::command]
fn get_video_layer_thumbnail(
    state: State<'_, AppState>,
    layer_id: VideoLayerId,
    width: u32,
    height: u32,
) -> Result<video::VideoFrame, String> {
    if width == 0 || height == 0 || width > 512 || height > 512 {
        return Err("Video thumbnail dimensions must be between 1 and 512 pixels".to_string());
    }
    let snapshot = state.engine.snapshot();
    let mut renderer = state
        .video_preview
        .lock()
        .map_err(|_| "Video preview renderer lock was poisoned".to_string())?;
    renderer
        .frame_provider_mut()
        .set_bpm(Some(snapshot.clock.bpm));
    renderer
        .render_layer_preview(&snapshot.video, layer_id, width, height)
        .map_err(|error| format!("{error:?}"))
}

const MEDIA_ASSET_THUMBNAIL_MAX_EDGE: u32 = 512;
const MEDIA_ASSET_PREVIEW_MAX_POSITION_MS: u64 = 24 * 60 * 60 * 1_000;

fn validate_media_asset_thumbnail_dimensions(width: u32, height: u32) -> Result<(), String> {
    if width == 0
        || height == 0
        || width > MEDIA_ASSET_THUMBNAIL_MAX_EDGE
        || height > MEDIA_ASSET_THUMBNAIL_MAX_EDGE
    {
        return Err(format!(
            "Media asset thumbnail dimensions must be between 1 and {MEDIA_ASSET_THUMBNAIL_MAX_EDGE} pixels"
        ));
    }
    Ok(())
}

fn validate_media_asset_preview_position(position_ms: u64) -> Result<(), String> {
    if position_ms > MEDIA_ASSET_PREVIEW_MAX_POSITION_MS {
        return Err(format!(
            "Media asset preview position must not exceed {MEDIA_ASSET_PREVIEW_MAX_POSITION_MS} ms"
        ));
    }
    Ok(())
}

/// Capture a media-library entry from the persistence checkpoint without
/// reconciling it. A thumbnail is a read-only machine-local operation: it must
/// never advance the revision/history merely to make a stale catalog appear
/// current.
fn capture_media_asset_thumbnail_asset(
    state: &AppState,
    asset_id: MediaAssetId,
) -> Result<(MediaAssetPrepareAuthority, MediaAssetSummary), String> {
    let _external_admission = lock_project_external_command_admission(state)?;
    let coordinator = lock_project_coordinator(state)?;
    ensure_no_pending_project_transaction(&coordinator)?;
    let checkpoint = project_checkpoint_for_coordinator(state, &coordinator)?;
    media_asset_thumbnail_asset_for_checkpoint(&coordinator, &checkpoint, asset_id)
}

fn capture_media_asset_preview_asset_for_window(
    state: &AppState,
    window: &WebviewWindow,
    asset_id: MediaAssetId,
) -> Result<(String, MediaAssetPrepareAuthority, MediaAssetSummary), String> {
    let _external_admission = lock_project_external_command_admission(state)?;
    let coordinator = lock_project_coordinator(state)?;
    let owner_id = {
        let owners = state
            .project_transaction_owners
            .lock()
            .map_err(|_| "Project transaction owner registry lock was poisoned".to_string())?;
        legacy_media_asset_compatibility_owner_for_window_label(&owners, window.label())?
    };
    ensure_no_pending_project_transaction(&coordinator)?;
    let checkpoint = project_checkpoint_for_coordinator(state, &coordinator)?;
    let (authority, asset) =
        media_asset_thumbnail_asset_for_checkpoint(&coordinator, &checkpoint, asset_id)?;
    Ok((owner_id, authority, asset))
}

fn capture_media_asset_preview_owner_for_window(
    state: &AppState,
    window: &WebviewWindow,
) -> Result<String, String> {
    let _external_admission = lock_project_external_command_admission(state)?;
    let owners = state
        .project_transaction_owners
        .lock()
        .map_err(|_| "Project transaction owner registry lock was poisoned".to_string())?;
    legacy_media_asset_compatibility_owner_for_window_label(&owners, window.label())
}

/// The Begin linearization point. The verified copy was prepared outside all
/// project locks; this repeats the exact window-owner and E/R/H/full-asset
/// capture then inserts the session before the admission boundary is released.
fn insert_media_asset_preview_session_if_current(
    state: &AppState,
    window: &WebviewWindow,
    expected_owner: &str,
    expected_authority: &MediaAssetPrepareAuthority,
    expected_asset: &MediaAssetSummary,
    private_copy: PrivateMediaSnapshot,
) -> Result<MediaAssetPreviewSessionTicket, String> {
    let _external_admission = lock_project_external_command_admission(state)?;
    let coordinator = lock_project_coordinator(state)?;
    let owner_id = {
        let owners = state
            .project_transaction_owners
            .lock()
            .map_err(|_| "Project transaction owner registry lock was poisoned".to_string())?;
        legacy_media_asset_compatibility_owner_for_window_label(&owners, window.label())?
    };
    if owner_id != expected_owner {
        return Err("Renderer owner changed while media preview was prepared; retry".to_string());
    }
    ensure_no_pending_project_transaction(&coordinator)?;
    let checkpoint = project_checkpoint_for_coordinator(state, &coordinator)?;
    let (authority, asset) =
        media_asset_thumbnail_asset_for_checkpoint(&coordinator, &checkpoint, expected_asset.id)?;
    ensure_media_asset_thumbnail_still_authoritative(
        expected_authority,
        expected_asset,
        &authority,
        &asset,
    )?;
    state.media_asset_operations.insert_preview_session(
        owner_id,
        window.label().to_string(),
        authority,
        asset,
        private_copy,
    )
}

fn media_asset_thumbnail_asset_for_checkpoint(
    coordinator: &ProjectCoordinator,
    checkpoint: &ProjectCheckpoint,
    asset_id: MediaAssetId,
) -> Result<(MediaAssetPrepareAuthority, MediaAssetSummary), String> {
    if checkpoint.epoch != coordinator.epoch
        || checkpoint.revision != coordinator.revision
        || checkpoint.hash != coordinator.checkpoint_hash
    {
        return Err(
            "Project changed outside the current authority checkpoint; retry the media thumbnail"
                .to_string(),
        );
    }
    let asset = media_asset_catalog_for_snapshot(&checkpoint.project.snapshot)
        .iter()
        .find(|asset| asset.id == asset_id)
        .cloned()
        .ok_or_else(|| format!("Media asset {asset_id} was not found"))?;
    validate_media_asset_thumbnail_contract(&asset)?;
    Ok((media_asset_prepare_authority(coordinator), asset))
}

/// This is deliberately stricter than the generic catalog schema. Rendering a
/// thumbnail consumes a local file, so legacy entries without a persisted
/// byte/hash identity are not authoritative enough to race safely.
fn validate_media_asset_thumbnail_contract(asset: &MediaAssetSummary) -> Result<(), String> {
    if !matches!(
        asset.source.kind,
        VideoSourceKind::File | VideoSourceKind::StillImage
    ) {
        return Err(
            "Media asset thumbnails are available for local File and Still Image sources only"
                .to_string(),
        );
    }
    if asset
        .source
        .path
        .as_deref()
        .is_none_or(|path| path.trim().is_empty())
    {
        return Err("Media asset thumbnail requires a local source path".to_string());
    }
    if asset.content_hash.is_none() || asset.byte_size.is_none() {
        return Err(
            "Media asset thumbnail requires the catalog's exact local content identity".to_string(),
        );
    }
    Ok(())
}

fn media_asset_thumbnail_snapshot(
    asset: &MediaAssetSummary,
    private_path: &Path,
    position_ms: u64,
) -> protocol::VideoSnapshot {
    let mut snapshot = protocol::VideoSnapshot::default();
    let mut private_source = asset.source.clone();
    private_source.path = Some(private_path.to_string_lossy().into_owned());
    snapshot.layers.push(protocol::VideoLayerSummary {
        // The layer and its source are strictly ephemeral. Do not attach the
        // catalog ID: the renderer must decode only the private verified copy,
        // never the user-controlled catalog path again.
        id: asset.id,
        label: asset.label.clone(),
        source: private_source,
        media_asset_id: None,
        blend_mode: VideoBlendMode::Normal,
        state: VideoLayerState {
            position_ms,
            ..VideoLayerState::default()
        },
        isf_effect: None,
        clip_slots: Vec::new(),
        default_clip_slot_id: None,
    });
    snapshot
}

fn media_asset_thumbnail_prepared_matches_asset(
    prepared: &PreparedLocalMediaAsset,
    asset: &MediaAssetSummary,
) -> bool {
    asset.content_hash.as_ref() == Some(&prepared.content_hash)
        && asset.byte_size == Some(prepared.byte_size)
        && asset.source == prepared.source
}

fn create_media_asset_preview_private_copy(
    asset: &MediaAssetSummary,
) -> Result<PrivateMediaSnapshot, String> {
    let path = asset
        .source
        .path
        .clone()
        .ok_or_else(|| "Media asset thumbnail requires a local source path".to_string())?;
    let cancel = AtomicBool::new(false);
    let before =
        prepare_one_local_media_asset(0, asset.source.kind.clone(), path.clone(), &cancel)?;
    if !media_asset_thumbnail_prepared_matches_asset(&before, asset) {
        return Err("Media asset content no longer matches its catalog identity".to_string());
    }
    let mut private_copy = PrivateMediaSnapshot::create(Path::new(&path))?;
    #[cfg(windows)]
    let mut source = open_windows_media_file_deny_write(Path::new(&path))?;
    #[cfg(unix)]
    let mut source = fs::File::open(&path)
        .map_err(|error| format!("Unable to open media source for preview copy: {error}"))?;
    let (copy_hash, copy_size) =
        copy_and_hash_into_snapshot(&mut source, &mut private_copy, &cancel)?;
    if asset.content_hash.as_ref() != Some(&copy_hash) || asset.byte_size != Some(copy_size) {
        return Err("Media asset changed while its preview copy was being created".to_string());
    }
    drop(source);
    let after = prepare_one_local_media_asset(0, asset.source.kind.clone(), path, &cancel)?;
    if !media_asset_thumbnail_prepared_matches_asset(&after, asset)
        || !local_media_source_fingerprint_matches(&before.fingerprint, &after.fingerprint)
    {
        return Err("Media asset changed while its preview copy was being created".to_string());
    }
    Ok(private_copy)
}

fn render_media_asset_preview_from_private_copy(
    asset: &MediaAssetSummary,
    private_copy: &PrivateMediaSnapshot,
    position_ms: u64,
    width: u32,
    height: u32,
) -> Result<video::VideoFrame, String> {
    let snapshot = media_asset_thumbnail_snapshot(asset, &private_copy.path, position_ms);
    let mut renderer = new_vj_preview_renderer();
    renderer
        .render_layer_preview(&snapshot, asset.id, width, height)
        .map_err(|error| format!("{error:?}"))
}

fn render_media_asset_thumbnail(
    asset: MediaAssetSummary,
    position_ms: u64,
    width: u32,
    height: u32,
) -> Result<video::VideoFrame, String> {
    let private_copy = create_media_asset_preview_private_copy(&asset)?;
    render_media_asset_preview_from_private_copy(&asset, &private_copy, position_ms, width, height)
}

fn ensure_media_asset_thumbnail_still_authoritative(
    authority: &MediaAssetPrepareAuthority,
    asset: &MediaAssetSummary,
    current_authority: &MediaAssetPrepareAuthority,
    current_asset: &MediaAssetSummary,
) -> Result<(), String> {
    if current_authority != authority || current_asset != asset {
        return Err(
            "Project or media asset changed while its thumbnail was decoded; retry".to_string(),
        );
    }
    Ok(())
}

#[tauri::command]
async fn get_media_asset_thumbnail(
    state: State<'_, AppState>,
    asset_id: MediaAssetId,
    width: u32,
    height: u32,
) -> Result<video::VideoFrame, String> {
    validate_media_asset_thumbnail_dimensions(width, height)?;
    let (authority, asset) = capture_media_asset_thumbnail_asset(&state, asset_id)?;
    let render_asset = asset.clone();
    let frame = tauri::async_runtime::spawn_blocking(move || {
        render_media_asset_thumbnail(render_asset, 0, width, height)
    })
    .await
    .map_err(|error| format!("Media asset thumbnail worker failed: {error}"))??;
    let (current_authority, current_asset) = capture_media_asset_thumbnail_asset(&state, asset_id)?;
    ensure_media_asset_thumbnail_still_authoritative(
        &authority,
        &asset,
        &current_authority,
        &current_asset,
    )?;
    Ok(frame)
}

#[tauri::command]
async fn begin_media_asset_preview(
    state: State<'_, AppState>,
    window: WebviewWindow,
    asset_id: MediaAssetId,
) -> Result<MediaAssetPreviewSessionTicket, String> {
    let (owner_id, authority, asset) =
        capture_media_asset_preview_asset_for_window(&state, &window, asset_id)?;
    let copy_asset = asset.clone();
    let private_copy = tauri::async_runtime::spawn_blocking(move || {
        create_media_asset_preview_private_copy(&copy_asset)
    })
    .await
    .map_err(|error| format!("Media asset preview setup worker failed: {error}"))??;
    insert_media_asset_preview_session_if_current(
        &state,
        &window,
        &owner_id,
        &authority,
        &asset,
        private_copy,
    )
}

#[tauri::command]
async fn get_media_asset_preview_frame(
    state: State<'_, AppState>,
    window: WebviewWindow,
    session_id: u64,
    asset_id: MediaAssetId,
    position_ms: u64,
    width: u32,
    height: u32,
) -> Result<video::VideoFrame, String> {
    validate_media_asset_thumbnail_dimensions(width, height)?;
    validate_media_asset_preview_position(position_ms)?;
    let (owner_id, authority, asset) =
        capture_media_asset_preview_asset_for_window(&state, &window, asset_id)?;
    let session = state.media_asset_operations.preview_session_for_frame(
        session_id,
        &owner_id,
        window.label(),
        asset_id,
        Instant::now(),
    )?;
    ensure_media_asset_thumbnail_still_authoritative(
        &session.authority,
        &session.asset,
        &authority,
        &asset,
    )?;
    let render_session = Arc::clone(&session);
    let frame = tauri::async_runtime::spawn_blocking(move || {
        render_media_asset_preview_from_private_copy(
            &render_session.asset,
            &render_session.private_copy,
            position_ms,
            width,
            height,
        )
    })
    .await
    .map_err(|error| format!("Media asset preview frame worker failed: {error}"))??;
    let (current_owner, current_authority, current_asset) =
        capture_media_asset_preview_asset_for_window(&state, &window, asset_id)?;
    if current_owner != owner_id {
        return Err("Renderer owner changed while media preview was decoded; retry".to_string());
    }
    ensure_media_asset_thumbnail_still_authoritative(
        &session.authority,
        &session.asset,
        &current_authority,
        &current_asset,
    )?;
    state
        .media_asset_operations
        .refresh_preview_session(&session, Instant::now())?;
    Ok(frame)
}

#[tauri::command]
fn end_media_asset_preview(
    state: State<'_, AppState>,
    window: WebviewWindow,
    session_id: u64,
    asset_id: MediaAssetId,
) -> Result<(), String> {
    let owner_id = capture_media_asset_preview_owner_for_window(&state, &window)?;
    state.media_asset_operations.end_preview_session(
        session_id,
        &owner_id,
        window.label(),
        asset_id,
    )
}

#[tauri::command]
fn get_debug_video_preview(
    state: State<'_, AppState>,
    width: u32,
    height: u32,
) -> Result<video::VideoFrame, String> {
    let snapshot = state.engine.snapshot();
    let mut renderer = state
        .video_preview
        .lock()
        .map_err(|_| "Video preview renderer lock was poisoned".to_string())?;
    renderer
        .frame_provider_mut()
        .set_bpm(Some(snapshot.clock.bpm));
    let decode_budget = video_preview_decode_budget(&renderer, snapshot.video.layers.len());
    renderer
        .warm_first_composition_decode_queue(&snapshot.video, width, height, decode_budget)
        .map_err(|error| format!("{error:?}"))?;
    renderer
        .render(&snapshot.video, width, height)
        .map_err(|error| format!("{error:?}"))
}

#[tauri::command]
fn get_debug_video_output_preview(
    state: State<'_, AppState>,
    output_id: VideoOutputId,
    width: u32,
    height: u32,
    decode_budget: Option<usize>,
) -> Result<video::VideoFrame, String> {
    let output_preview = capture_video_output_preview_effect_snapshot(&state.engine);
    let mut renderer = state
        .video_preview
        .lock()
        .map_err(|_| "Video preview renderer lock was poisoned".to_string())?;
    renderer
        .frame_provider_mut()
        .set_bpm(Some(output_preview.snapshot.clock.bpm));
    let decode_budget = resolved_video_preview_decode_budget(
        &renderer,
        output_preview.snapshot.video.layers.len(),
        decode_budget,
    );
    renderer
        .warm_output_decode_queue(
            &output_preview.snapshot.video,
            output_id,
            width,
            height,
            decode_budget,
        )
        .map_err(|error| format!("{error:?}"))?;
    renderer
        .render_output_preview_with_effects_and_transitions(
            &output_preview.snapshot.video,
            output_preview.render_context(),
            &output_preview.snapshot.video_transition_runtime,
            output_id,
            width,
            height,
        )
        .map_err(|error| format!("{error:?}"))
}

#[tauri::command]
fn get_vj_preview_transport(
    state: State<'_, AppState>,
) -> Result<VjPreviewTransportSummary, String> {
    let snapshot = state.engine.snapshot();
    let now = Instant::now();
    let updated_at_ms = vj_preview_timestamp_ms();
    let mut transport = state
        .vj_preview_transport
        .lock()
        .map_err(|_| "VJ Preview transport lock was poisoned".to_string())?;
    let valid = transport.reconcile_at(&snapshot, now, updated_at_ms);
    let summary = transport.summary_at(now, updated_at_ms);
    drop(transport);
    if !valid {
        reset_vj_preview_renderer(&state)?;
    }
    Ok(summary)
}

#[tauri::command]
fn stage_vj_preview_layer(
    state: State<'_, AppState>,
    layer_id: VideoLayerId,
    expected_epoch: Option<u64>,
    expected_revision: Option<u64>,
    expected_checkpoint_hash: Option<String>,
) -> Result<VjPreviewTransportSummary, String> {
    let expected_authority = vj_preview_project_authority_expectation(
        expected_epoch,
        expected_revision,
        expected_checkpoint_hash,
    )?;
    if let Some(expected_authority) = expected_authority {
        // Project replacement takes the same admission -> coordinator order.
        // Keep both guards through snapshot selection and staging so C cannot
        // publish between the exact B check and this runtime-only side effect.
        let _external_admission = lock_project_external_command_admission(&state)?;
        let mut coordinator = lock_project_coordinator(&state)?;
        ensure_no_pending_project_transaction(&coordinator)?;
        reconcile_project_checkpoint_for_coordinator(&state, &mut coordinator)?;
        return with_exact_vj_preview_project_authority(&coordinator, &expected_authority, || {
            let snapshot = state.engine.snapshot();
            stage_vj_preview_layer_from_snapshot(&state, &snapshot, layer_id)
        });
    }

    let snapshot = state.engine.snapshot();
    stage_vj_preview_layer_from_snapshot(&state, &snapshot, layer_id)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct VjPreviewProjectAuthorityExpectation {
    epoch: u64,
    revision: u64,
    checkpoint_hash: String,
}

fn vj_preview_project_authority_expectation(
    expected_epoch: Option<u64>,
    expected_revision: Option<u64>,
    expected_checkpoint_hash: Option<String>,
) -> Result<Option<VjPreviewProjectAuthorityExpectation>, String> {
    match (expected_epoch, expected_revision, expected_checkpoint_hash) {
        (None, None, None) => Ok(None),
        (Some(epoch), Some(revision), Some(checkpoint_hash))
            if !checkpoint_hash.trim().is_empty() =>
        {
            Ok(Some(VjPreviewProjectAuthorityExpectation {
                epoch,
                revision,
                checkpoint_hash,
            }))
        }
        _ => Err(
            "VJ Preview authority requires epoch, revision, and checkpoint hash together"
                .to_string(),
        ),
    }
}

fn with_exact_vj_preview_project_authority<T>(
    coordinator: &ProjectCoordinator,
    expected: &VjPreviewProjectAuthorityExpectation,
    stage: impl FnOnce() -> Result<T, String>,
) -> Result<T, String> {
    if coordinator.epoch != expected.epoch
        || coordinator.revision != expected.revision
        || coordinator.checkpoint_hash != expected.checkpoint_hash
    {
        return Err("Project changed before VJ Preview staging; nothing was staged".to_string());
    }
    stage()
}

fn stage_vj_preview_layer_from_snapshot(
    state: &State<'_, AppState>,
    snapshot: &EngineSnapshot,
    layer_id: VideoLayerId,
) -> Result<VjPreviewTransportSummary, String> {
    let layer = snapshot
        .video
        .layers
        .iter()
        .find(|layer| layer.id == layer_id)
        .ok_or_else(|| format!("Video layer {layer_id} was not found"))?;
    let source = VjPreviewSourceIdentity::from_layer(layer);
    let mut transport = state
        .vj_preview_transport
        .lock()
        .map_err(|_| "VJ Preview transport lock was poisoned".to_string())?;
    let reset_renderer = transport
        .session
        .as_ref()
        .is_some_and(|session| session.layer_id != layer_id || session.source != source);
    let summary = transport.stage_at(layer, Instant::now(), vj_preview_timestamp_ms())?;
    drop(transport);
    if reset_renderer {
        reset_vj_preview_renderer(state)?;
    }
    Ok(summary)
}

#[tauri::command]
fn set_vj_preview_playing(
    state: State<'_, AppState>,
    playing: bool,
) -> Result<VjPreviewTransportSummary, String> {
    let snapshot = state.engine.snapshot();
    let now = Instant::now();
    let updated_at_ms = vj_preview_timestamp_ms();
    let mut transport = state
        .vj_preview_transport
        .lock()
        .map_err(|_| "VJ Preview transport lock was poisoned".to_string())?;
    let valid = transport.reconcile_at(&snapshot, now, updated_at_ms);
    let result = transport.set_playing_at(playing, now, updated_at_ms);
    drop(transport);
    if !valid {
        reset_vj_preview_renderer(&state)?;
    }
    result
}

#[tauri::command]
fn seek_vj_preview(
    state: State<'_, AppState>,
    position_ms: u64,
) -> Result<VjPreviewTransportSummary, String> {
    let snapshot = state.engine.snapshot();
    let now = Instant::now();
    let updated_at_ms = vj_preview_timestamp_ms();
    let mut transport = state
        .vj_preview_transport
        .lock()
        .map_err(|_| "VJ Preview transport lock was poisoned".to_string())?;
    let valid = transport.reconcile_at(&snapshot, now, updated_at_ms);
    let result = transport.seek_at(position_ms, now, updated_at_ms);
    drop(transport);
    if !valid {
        reset_vj_preview_renderer(&state)?;
    }
    result
}

#[tauri::command]
fn set_vj_preview_speed(
    state: State<'_, AppState>,
    speed: f32,
) -> Result<VjPreviewTransportSummary, String> {
    let snapshot = state.engine.snapshot();
    let now = Instant::now();
    let updated_at_ms = vj_preview_timestamp_ms();
    let mut transport = state
        .vj_preview_transport
        .lock()
        .map_err(|_| "VJ Preview transport lock was poisoned".to_string())?;
    let valid = transport.reconcile_at(&snapshot, now, updated_at_ms);
    let result = transport.set_speed_at(speed, now, updated_at_ms);
    drop(transport);
    if !valid {
        reset_vj_preview_renderer(&state)?;
    }
    result
}

#[tauri::command]
fn clear_vj_preview(state: State<'_, AppState>) -> Result<VjPreviewTransportSummary, String> {
    let summary = state
        .vj_preview_transport
        .lock()
        .map_err(|_| "VJ Preview transport lock was poisoned".to_string())
        .map(|mut transport| transport.clear_at(vj_preview_timestamp_ms()))?;
    reset_vj_preview_renderer(&state)?;
    Ok(summary)
}

fn vj_preview_render_snapshot(
    snapshot: &EngineSnapshot,
    layer_id: VideoLayerId,
    position_ms: u64,
) -> Result<protocol::VideoSnapshot, String> {
    let mut layer = snapshot
        .video
        .layers
        .iter()
        .find(|layer| layer.id == layer_id)
        .cloned()
        .ok_or_else(|| format!("Video layer {layer_id} was not found"))?;
    validate_vj_preview_layer(&layer)?;
    layer.state.position_ms = position_ms;
    layer.state.playing = false;
    // render_layer_preview treats position zero as an invitation to use loop_start_ms.
    // The independent transport must be able to seek to an actual zero frame.
    layer.state.loop_start_ms = 0;
    Ok(protocol::VideoSnapshot {
        layers: vec![layer],
        media_assets: Vec::new(),
        effect_chains: Vec::new(),
        effect_presets: Vec::new(),
        layer_groups: Vec::new(),
        transition_buses: Vec::new(),
        compositions: Vec::new(),
        outputs: Vec::new(),
        mapping_presets: Vec::new(),
        auto_vj: protocol::AutoVjSnapshot::default(),
        master_opacity: 1.0,
        blackout: false,
    })
}

fn vj_preview_frame_is_current(
    rendered: &VjPreviewTransportSummary,
    current: &VjPreviewTransportSummary,
    source_is_valid: bool,
) -> bool {
    source_is_valid
        && rendered.layer_id.is_some()
        && rendered.layer_id == current.layer_id
        && rendered.generation == current.generation
}

const LIVE_VIDEO_MONITOR_MAGIC: [u8; 4] = *b"SYLV";
const LIVE_VIDEO_MONITOR_VERSION: u8 = 1;
const LIVE_VIDEO_MONITOR_STATUS_FRAME: u8 = 0;
const LIVE_VIDEO_MONITOR_STATUS_BUSY: u8 = 1;
const LIVE_VIDEO_MONITOR_HEADER_LEN: usize = 40;
const LIVE_VIDEO_MONITOR_MAX_WIDTH: u32 = 640;
const LIVE_VIDEO_MONITOR_MAX_HEIGHT: u32 = 360;
const LIVE_VIDEO_MONITOR_MAX_PIXELS: u32 =
    LIVE_VIDEO_MONITOR_MAX_WIDTH * LIVE_VIDEO_MONITOR_MAX_HEIGHT;
const LIVE_VIDEO_MONITOR_DEFAULT_JPEG_QUALITY: u8 = 68;
const LIVE_VIDEO_MONITOR_MIN_JPEG_QUALITY: u8 = 40;
const LIVE_VIDEO_MONITOR_MAX_JPEG_QUALITY: u8 = 90;
const LIVE_VIDEO_MONITOR_MAX_DECODE_BUDGET: usize = 2;

#[derive(Debug, Clone, Copy, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
enum LiveVideoMonitorKind {
    Program,
    Preview,
}

impl LiveVideoMonitorKind {
    fn packet_value(self) -> u8 {
        match self {
            Self::Program => 0,
            Self::Preview => 1,
        }
    }
}

fn live_video_monitor_dimensions(width: u32, height: u32) -> (u32, u32) {
    let width = width.clamp(1, LIVE_VIDEO_MONITOR_MAX_WIDTH);
    let height = height.clamp(1, LIVE_VIDEO_MONITOR_MAX_HEIGHT);
    if width.saturating_mul(height) <= LIVE_VIDEO_MONITOR_MAX_PIXELS {
        return (width, height);
    }
    (width, (LIVE_VIDEO_MONITOR_MAX_PIXELS / width).max(1))
}

fn live_video_monitor_quality(quality: Option<u8>) -> u8 {
    quality
        .unwrap_or(LIVE_VIDEO_MONITOR_DEFAULT_JPEG_QUALITY)
        .clamp(
            LIVE_VIDEO_MONITOR_MIN_JPEG_QUALITY,
            LIVE_VIDEO_MONITOR_MAX_JPEG_QUALITY,
        )
}

fn live_video_monitor_elapsed_us(started: Instant) -> u32 {
    started.elapsed().as_micros().min(u128::from(u32::MAX)) as u32
}

#[allow(clippy::too_many_arguments)]
fn live_video_monitor_packet(
    status: u8,
    kind: LiveVideoMonitorKind,
    sequence: u64,
    pts_ms: u64,
    render_us: u32,
    encode_us: u32,
    width: u32,
    height: u32,
    jpeg: &[u8],
) -> Result<Vec<u8>, String> {
    let width = u16::try_from(width)
        .map_err(|_| "Live video monitor frame width exceeded the packet format".to_string())?;
    let height = u16::try_from(height)
        .map_err(|_| "Live video monitor frame height exceeded the packet format".to_string())?;
    let jpeg_len = u32::try_from(jpeg.len())
        .map_err(|_| "Live video monitor JPEG exceeded the packet format".to_string())?;
    let mut packet = Vec::with_capacity(LIVE_VIDEO_MONITOR_HEADER_LEN + jpeg.len());
    packet.extend_from_slice(&LIVE_VIDEO_MONITOR_MAGIC);
    packet.push(LIVE_VIDEO_MONITOR_VERSION);
    packet.push(status);
    packet.push(kind.packet_value());
    packet.push(0);
    packet.extend_from_slice(&sequence.to_le_bytes());
    packet.extend_from_slice(&pts_ms.to_le_bytes());
    packet.extend_from_slice(&render_us.to_le_bytes());
    packet.extend_from_slice(&encode_us.to_le_bytes());
    packet.extend_from_slice(&width.to_le_bytes());
    packet.extend_from_slice(&height.to_le_bytes());
    packet.extend_from_slice(&jpeg_len.to_le_bytes());
    debug_assert_eq!(packet.len(), LIVE_VIDEO_MONITOR_HEADER_LEN);
    packet.extend_from_slice(jpeg);
    Ok(packet)
}

fn encode_live_video_monitor_jpeg(
    frame: &video::VideoFrame,
    quality: u8,
) -> Result<Vec<u8>, String> {
    if frame.format != video::VideoPixelFormat::Rgba8 {
        return Err(format!(
            "Live video monitor expected RGBA8, received {:?}",
            frame.format
        ));
    }
    let expected_len = u64::from(frame.width)
        .saturating_mul(u64::from(frame.height))
        .saturating_mul(4);
    if expected_len != frame.data.len() as u64 {
        return Err(format!(
            "Live video monitor RGBA8 buffer has {} bytes; expected {expected_len}",
            frame.data.len()
        ));
    }
    let mut jpeg = Vec::new();
    image::codecs::jpeg::JpegEncoder::new_with_quality(&mut jpeg, quality)
        .encode(
            &frame.data,
            frame.width,
            frame.height,
            image::ColorType::Rgba8,
        )
        .map_err(|error| format!("Could not encode live video monitor JPEG: {error}"))?;
    Ok(jpeg)
}

/// Returns one bounded Preview or Program monitor frame as a raw ArrayBuffer.
///
/// The fixed 40-byte little-endian header is: magic[4], version/status/kind/reserved,
/// sequence(u64), pts_ms(u64), render_us(u32), encode_us(u32), width/height(u16),
/// jpeg_len(u32), followed by JPEG bytes. A busy response has status 1 and no payload.
#[tauri::command]
fn get_live_video_monitor_frame(
    state: State<'_, AppState>,
    monitor_kind: LiveVideoMonitorKind,
    output_id: Option<VideoOutputId>,
    layer_id: Option<VideoLayerId>,
    width: u32,
    height: u32,
    quality: Option<u8>,
    decode_budget: Option<usize>,
) -> Result<tauri::ipc::Response, String> {
    let sequence = LIVE_VIDEO_MONITOR_SEQUENCE.fetch_add(1, Ordering::Relaxed);
    let (width, height) = live_video_monitor_dimensions(width, height);
    let quality = live_video_monitor_quality(quality);
    let (snapshot, program_render_epoch) = match monitor_kind {
        LiveVideoMonitorKind::Program => {
            let output_preview = capture_video_output_preview_effect_snapshot(&state.engine);
            (
                output_preview.snapshot,
                Some(output_preview.project_render_epoch),
            )
        }
        LiveVideoMonitorKind::Preview => (state.engine.snapshot(), None),
    };
    let render_started = Instant::now();
    let mut rendered_preview_summary: Option<VjPreviewTransportSummary> = None;
    let frame = match monitor_kind {
        LiveVideoMonitorKind::Program => {
            let output_id =
                output_id.ok_or_else(|| "Program monitor requires an outputId".to_string())?;
            let mut renderer = match state.video_preview.try_lock() {
                Ok(renderer) => renderer,
                Err(TryLockError::WouldBlock) => {
                    let packet = live_video_monitor_packet(
                        LIVE_VIDEO_MONITOR_STATUS_BUSY,
                        monitor_kind,
                        sequence,
                        0,
                        0,
                        0,
                        width,
                        height,
                        &[],
                    )?;
                    return Ok(tauri::ipc::Response::new(packet));
                }
                Err(TryLockError::Poisoned(_)) => {
                    return Err("Video preview renderer lock was poisoned".to_string());
                }
            };
            renderer
                .frame_provider_mut()
                .set_bpm(Some(snapshot.clock.bpm));
            let decode_budget = resolved_video_preview_decode_budget(
                &renderer,
                snapshot.video.layers.len(),
                Some(
                    decode_budget
                        .unwrap_or(1)
                        .clamp(1, LIVE_VIDEO_MONITOR_MAX_DECODE_BUDGET),
                ),
            );
            renderer
                .warm_output_decode_queue(&snapshot.video, output_id, width, height, decode_budget)
                .map_err(|error| format!("{error:?}"))?;
            renderer
                .render_output_preview_with_effects_and_transitions(
                    &snapshot.video,
                    video::VideoEffectRenderContext {
                        clip_runtime: &snapshot.video_clip_runtime,
                        project_render_epoch: program_render_epoch
                            .expect("Program monitor captures an output render epoch"),
                    },
                    &snapshot.video_transition_runtime,
                    output_id,
                    width,
                    height,
                )
                .map_err(|error| format!("{error:?}"))?
        }
        LiveVideoMonitorKind::Preview => {
            // layer_id remains in the binary IPC contract for compatibility, but Preview is
            // rendered exclusively from the explicitly staged ephemeral transport.
            let _ = layer_id;
            let now = Instant::now();
            let updated_at_ms = vj_preview_timestamp_ms();
            let (summary, valid) = {
                let mut transport = state
                    .vj_preview_transport
                    .lock()
                    .map_err(|_| "VJ Preview transport lock was poisoned".to_string())?;
                let valid = transport.reconcile_at(&snapshot, now, updated_at_ms);
                (transport.summary_at(now, updated_at_ms), valid)
            };
            if !valid {
                reset_vj_preview_renderer(&state)?;
            }
            let layer_id = summary
                .layer_id
                .ok_or_else(|| "Preview monitor has no staged layer".to_string())?;
            let preview_video =
                vj_preview_render_snapshot(&snapshot, layer_id, summary.position_ms)?;
            let mut renderer = match state.vj_preview_renderer.try_lock() {
                Ok(renderer) => renderer,
                Err(TryLockError::WouldBlock) => {
                    let packet = live_video_monitor_packet(
                        LIVE_VIDEO_MONITOR_STATUS_BUSY,
                        monitor_kind,
                        sequence,
                        summary.position_ms,
                        0,
                        0,
                        width,
                        height,
                        &[],
                    )?;
                    return Ok(tauri::ipc::Response::new(packet));
                }
                Err(TryLockError::Poisoned(_)) => {
                    return Err("VJ Preview renderer lock was poisoned".to_string());
                }
            };
            if state
                .vj_preview_renderer_reset_pending
                .swap(false, Ordering::AcqRel)
            {
                *renderer = new_vj_preview_renderer();
            }
            renderer
                .frame_provider_mut()
                .set_bpm(Some(snapshot.clock.bpm));
            let frame = renderer
                .render_layer_preview(&preview_video, layer_id, width, height)
                .map_err(|error| format!("{error:?}"))?;
            drop(renderer);

            // A seek, restage, clear, layer removal, or source replacement may race a slow
            // decode. Do not publish that stale frame into the Preview bus.
            let latest_snapshot = state.engine.snapshot();
            let check_now = Instant::now();
            let check_timestamp_ms = vj_preview_timestamp_ms();
            let (current, valid) = {
                let mut transport = state
                    .vj_preview_transport
                    .lock()
                    .map_err(|_| "VJ Preview transport lock was poisoned".to_string())?;
                let valid = transport.reconcile_at(&latest_snapshot, check_now, check_timestamp_ms);
                (transport.summary_at(check_now, check_timestamp_ms), valid)
            };
            if !valid {
                reset_vj_preview_renderer(&state)?;
            }
            if !vj_preview_frame_is_current(&summary, &current, valid) {
                let packet = live_video_monitor_packet(
                    LIVE_VIDEO_MONITOR_STATUS_BUSY,
                    monitor_kind,
                    sequence,
                    current.position_ms,
                    live_video_monitor_elapsed_us(render_started),
                    0,
                    width,
                    height,
                    &[],
                )?;
                return Ok(tauri::ipc::Response::new(packet));
            }
            rendered_preview_summary = Some(summary);
            frame
        }
    };
    let render_us = live_video_monitor_elapsed_us(render_started);

    let encode_started = Instant::now();
    let jpeg = encode_live_video_monitor_jpeg(&frame, quality)?;
    let encode_us = live_video_monitor_elapsed_us(encode_started);
    if let Some(rendered) = rendered_preview_summary.as_ref() {
        // Encoding is intentionally outside the transport lock. Recheck after it too, so a
        // seek/clear/project transition during JPEG work can never publish one stale packet.
        let latest_snapshot = state.engine.snapshot();
        let check_now = Instant::now();
        let check_timestamp_ms = vj_preview_timestamp_ms();
        let (current, valid) = {
            let mut transport = state
                .vj_preview_transport
                .lock()
                .map_err(|_| "VJ Preview transport lock was poisoned".to_string())?;
            let valid = transport.reconcile_at(&latest_snapshot, check_now, check_timestamp_ms);
            (transport.summary_at(check_now, check_timestamp_ms), valid)
        };
        if !valid {
            reset_vj_preview_renderer(&state)?;
        }
        if !vj_preview_frame_is_current(rendered, &current, valid) {
            let packet = live_video_monitor_packet(
                LIVE_VIDEO_MONITOR_STATUS_BUSY,
                monitor_kind,
                sequence,
                current.position_ms,
                render_us,
                encode_us,
                width,
                height,
                &[],
            )?;
            return Ok(tauri::ipc::Response::new(packet));
        }
    }
    let packet = live_video_monitor_packet(
        LIVE_VIDEO_MONITOR_STATUS_FRAME,
        monitor_kind,
        sequence,
        frame.pts_ms,
        render_us,
        encode_us,
        frame.width,
        frame.height,
        &jpeg,
    )?;
    Ok(tauri::ipc::Response::new(packet))
}

#[cfg(test)]
mod vj_preview_transport_tests {
    use super::*;

    fn file_layer(
        id: VideoLayerId,
        position_ms: u64,
        duration_ms: Option<u64>,
    ) -> protocol::VideoLayerSummary {
        protocol::VideoLayerSummary {
            id,
            label: format!("Clip {id}"),
            source: VideoSourceSummary {
                kind: VideoSourceKind::File,
                path: Some(format!("clip-{id}.mp4")),
                name: Some(format!("Source {id}")),
                codec: Some("h264".to_string()),
                metadata: Some(protocol::VideoMediaMetadata {
                    duration_ms,
                    width: Some(1_920),
                    height: Some(1_080),
                    frame_rate: Some(30.0),
                    has_audio: true,
                }),
            },
            media_asset_id: None,
            blend_mode: VideoBlendMode::Normal,
            state: VideoLayerState {
                position_ms,
                speed: 1.0,
                ..VideoLayerState::default()
            },
            isf_effect: None,
            clip_slots: Vec::new(),
            default_clip_slot_id: None,
        }
    }

    fn snapshot_with_layer(layer: protocol::VideoLayerSummary) -> EngineSnapshot {
        let mut snapshot = EngineSnapshot::default();
        snapshot.video.layers.push(layer);
        snapshot
    }

    #[test]
    fn authoritative_preview_stage_rejects_stale_or_partial_authority_before_effect() {
        let mut coordinator = ProjectCoordinator::default();
        coordinator.epoch = 4;
        coordinator.revision = 9;
        coordinator.checkpoint_hash = "checkpoint-b".to_string();
        let exact = VjPreviewProjectAuthorityExpectation {
            epoch: 4,
            revision: 9,
            checkpoint_hash: "checkpoint-b".to_string(),
        };
        let stale = VjPreviewProjectAuthorityExpectation {
            epoch: 5,
            ..exact.clone()
        };
        let mut staged = 0_u8;

        let stale_error = with_exact_vj_preview_project_authority(&coordinator, &stale, || {
            staged += 1;
            Ok(())
        })
        .unwrap_err();
        assert_eq!(staged, 0);
        assert!(stale_error.contains("nothing was staged"));

        with_exact_vj_preview_project_authority(&coordinator, &exact, || {
            staged += 1;
            Ok(())
        })
        .unwrap();
        assert_eq!(staged, 1);

        assert!(vj_preview_project_authority_expectation(None, None, None)
            .unwrap()
            .is_none());
        assert!(vj_preview_project_authority_expectation(
            Some(4),
            Some(9),
            Some("checkpoint-b".to_string()),
        )
        .unwrap()
        .is_some());
        assert!(vj_preview_project_authority_expectation(
            Some(4),
            None,
            Some("checkpoint-b".to_string()),
        )
        .is_err());
    }

    #[test]
    fn preview_requires_explicit_stage_and_uses_no_decode_prefetch() {
        let now = Instant::now();
        let mut runtime = VjPreviewTransportRuntime::default();
        let empty = runtime.summary_at(now, 1);
        assert_eq!(empty.layer_id, None);
        assert!(!empty.playing);

        let renderer = new_vj_preview_renderer();
        assert_eq!(renderer.frame_provider().prefetch_count(), 0);
    }

    #[test]
    fn preview_clock_is_independent_and_monitor_snapshot_uses_preview_position() {
        let snapshot = snapshot_with_layer(file_layer(7, 250, Some(5_000)));
        let started = Instant::now();
        let mut runtime = VjPreviewTransportRuntime::default();
        let initial = runtime
            .stage_at(&snapshot.video.layers[0], started, 1_000)
            .unwrap();
        let staged = runtime.seek_at(1_750, started, 1_001).unwrap();

        assert_eq!(snapshot.video.layers[0].state.position_ms, 250);
        assert_eq!(staged.position_ms, 1_750);
        assert!(staged.generation > initial.generation);
        assert_eq!(staged.updated_at_ms, 1_001);
        let preview = vj_preview_render_snapshot(&snapshot, 7, staged.position_ms).unwrap();
        assert_eq!(preview.layers.len(), 1);
        assert_eq!(preview.layers[0].state.position_ms, 1_750);
        assert_eq!(snapshot.video.layers[0].state.position_ms, 250);

        assert!(vj_preview_frame_is_current(&staged, &staged, true));
        let changed = runtime.seek_at(1_800, started, 1_002).unwrap();
        assert!(!vj_preview_frame_is_current(&staged, &changed, true));
        assert!(!vj_preview_frame_is_current(&changed, &changed, false));
    }

    #[test]
    fn preview_clock_advances_pauses_and_seeks_without_engine_commands() {
        let snapshot = snapshot_with_layer(file_layer(1, 100, Some(5_000)));
        let started = Instant::now();
        let mut runtime = VjPreviewTransportRuntime::default();
        runtime
            .stage_at(&snapshot.video.layers[0], started, 10)
            .unwrap();
        runtime.set_playing_at(true, started, 11).unwrap();

        let advanced = runtime.summary_at(started + Duration::from_millis(250), 261);
        assert_eq!(advanced.position_ms, 250);
        assert!(advanced.playing);
        let paused = runtime
            .set_playing_at(false, started + Duration::from_millis(250), 262)
            .unwrap();
        assert_eq!(paused.position_ms, 250);
        let held = runtime.summary_at(started + Duration::from_secs(5), 5_011);
        assert_eq!(held.position_ms, 250);
        assert!(!held.playing);
        let sought = runtime
            .seek_at(9_999, started + Duration::from_secs(5), 5_012)
            .unwrap();
        assert_eq!(sought.position_ms, 5_000);
    }

    #[test]
    fn preview_clock_wraps_forward_and_reverse_inside_sanitized_loop() {
        let mut layer = file_layer(2, 100, Some(1_000));
        layer.state.loop_enabled = true;
        layer.state.loop_start_ms = 100;
        layer.state.loop_end_ms = 300;
        let started = Instant::now();
        let mut runtime = VjPreviewTransportRuntime::default();
        runtime.stage_at(&layer, started, 20).unwrap();
        runtime.set_playing_at(true, started, 21).unwrap();
        let forward = runtime.summary_at(started + Duration::from_millis(250), 271);
        assert_eq!(forward.position_ms, 150);

        runtime
            .seek_at(150, started + Duration::from_millis(250), 272)
            .unwrap();
        runtime
            .set_speed_at(-1.0, started + Duration::from_millis(250), 273)
            .unwrap();
        let reverse = runtime.summary_at(started + Duration::from_millis(350), 373);
        assert_eq!(reverse.position_ms, 250);
        assert_eq!(reverse.speed, -1.0);
    }

    #[test]
    fn preview_reverse_stops_at_zero_and_speed_is_sanitized() {
        let layer = file_layer(3, 100, Some(1_000));
        let started = Instant::now();
        let mut runtime = VjPreviewTransportRuntime::default();
        runtime.stage_at(&layer, started, 30).unwrap();
        assert!(runtime.set_speed_at(f32::NAN, started, 31).is_err());
        assert_eq!(
            runtime.set_speed_at(-99.0, started, 32).unwrap().speed,
            VJ_PREVIEW_MIN_SPEED
        );
        runtime.seek_at(100, started, 33).unwrap();
        runtime.set_playing_at(true, started, 34).unwrap();
        let stopped = runtime.summary_at(started + Duration::from_millis(100), 133);
        assert_eq!(stopped.position_ms, 0);
        assert!(!stopped.playing);
    }

    #[test]
    fn preview_rejects_external_or_pathless_sources_and_stills_never_run() {
        let mut external = file_layer(4, 0, Some(1_000));
        external.source.kind = VideoSourceKind::Ndi;
        external.source.path = None;
        external.source.name = Some("Camera feed".to_string());
        assert!(validate_vj_preview_layer(&external)
            .unwrap_err()
            .contains("File and Still Image"));

        let mut pathless = file_layer(5, 0, Some(1_000));
        pathless.source.path = Some("  ".to_string());
        assert!(validate_vj_preview_layer(&pathless)
            .unwrap_err()
            .contains("local source path"));

        let mut still = file_layer(6, 0, None);
        still.source.kind = VideoSourceKind::StillImage;
        let started = Instant::now();
        let mut runtime = VjPreviewTransportRuntime::default();
        let staged = runtime.stage_at(&still, started, 40).unwrap();
        assert_eq!(staged.duration_ms, Some(0));
        let playing = runtime.set_playing_at(true, started, 41).unwrap();
        assert!(!playing.playing);
        assert_eq!(
            runtime
                .summary_at(started + Duration::from_secs(10), 10_041)
                .position_ms,
            0
        );
    }

    #[test]
    fn preview_is_cleared_when_layer_disappears_or_source_identity_changes() {
        let original = file_layer(8, 0, Some(1_000));
        let snapshot = snapshot_with_layer(original.clone());
        let started = Instant::now();
        let mut runtime = VjPreviewTransportRuntime::default();
        let staged = runtime.stage_at(&original, started, 50).unwrap();
        assert_eq!(staged.layer_id, Some(8));

        let mut replaced = snapshot.clone();
        replaced.video.layers[0].source.path = Some("replacement.mp4".to_string());
        assert!(!runtime.reconcile_at(&replaced, started, 51));
        assert_eq!(runtime.summary_at(started, 51).layer_id, None);

        runtime.stage_at(&original, started, 52).unwrap();
        let empty = EngineSnapshot::default();
        assert!(!runtime.reconcile_at(&empty, started, 53));
        assert_eq!(runtime.summary_at(started, 53).layer_id, None);
    }

    #[test]
    fn staging_rewinds_to_the_in_point_instead_of_copying_program_position() {
        let started = Instant::now();
        let mut runtime = VjPreviewTransportRuntime::default();
        let ended = file_layer(9, 900, Some(1_000));
        assert_eq!(
            runtime.stage_at(&ended, started, 60).unwrap().position_ms,
            0
        );

        let mut looped = file_layer(10, 900, Some(1_000));
        looped.state.loop_enabled = true;
        looped.state.loop_start_ms = 240;
        looped.state.loop_end_ms = 800;
        assert_eq!(
            runtime.stage_at(&looped, started, 61).unwrap().position_ms,
            240
        );
    }
}

#[cfg(test)]
mod live_video_monitor_tests {
    use super::*;

    fn read_u16(packet: &[u8], offset: usize) -> u16 {
        u16::from_le_bytes(packet[offset..offset + 2].try_into().unwrap())
    }

    fn read_u32(packet: &[u8], offset: usize) -> u32 {
        u32::from_le_bytes(packet[offset..offset + 4].try_into().unwrap())
    }

    fn read_u64(packet: &[u8], offset: usize) -> u64 {
        u64::from_le_bytes(packet[offset..offset + 8].try_into().unwrap())
    }

    #[test]
    fn c1_output_preview_effect_context_uses_runtime_clip_truth_and_ownership_epoch() {
        let mut snapshot = EngineSnapshot::default();
        snapshot
            .video_clip_runtime
            .layers
            .push(protocol::VideoClipLayerRuntimeSummary {
                layer_id: 17,
                active_slot_id: Some(VideoClipSlotId(23)),
                ..Default::default()
            });
        let captured = VideoOutputPreviewEffectSnapshot {
            snapshot,
            project_render_epoch: 41,
        };

        let context = captured.render_context();

        assert_eq!(context.project_render_epoch, 41);
        assert_eq!(context.clip_runtime, &captured.snapshot.video_clip_runtime);
        assert_eq!(context.clip_runtime.layers[0].layer_id, 17);
        assert_eq!(
            context.clip_runtime.layers[0].active_slot_id,
            Some(VideoClipSlotId(23))
        );
    }

    #[test]
    fn c1_effect_aware_output_preview_production_seams_are_wired() {
        let source = include_str!("main.rs");
        let routes = [
            (
                "run_video_output_recording",
                "fn finish_video_recording_status",
            ),
            (
                "get_debug_video_output_preview",
                "fn get_vj_preview_transport",
            ),
            (
                "get_live_video_monitor_frame",
                "fn video_preview_decode_budget",
            ),
        ];

        for (route, next_route) in routes {
            let route_start = source
                .find(&format!("fn {route}("))
                .unwrap_or_else(|| panic!("missing output preview route {route}"));
            let route_end = source[route_start..]
                .find(next_route)
                .map(|offset| route_start + offset)
                .unwrap_or_else(|| panic!("missing boundary after output preview route {route}"));
            let route_source = &source[route_start..route_end];
            assert!(
                route_source.contains("capture_video_output_preview_effect_snapshot"),
                "{route} must sample the NDI/Spout-order ownership epoch with its snapshot"
            );
            assert!(
                route_source.contains("render_output_preview_with_effects"),
                "{route} must retain output mapping/blackout/last-valid behavior through the C1 renderer"
            );
        }
    }

    #[test]
    fn live_video_monitor_packet_has_stable_40_byte_header() {
        let jpeg = [0xff, 0xd8, 0xff, 0xd9];
        let packet = live_video_monitor_packet(
            LIVE_VIDEO_MONITOR_STATUS_FRAME,
            LiveVideoMonitorKind::Preview,
            0x0102_0304_0506_0708,
            12_345,
            678,
            90,
            320,
            180,
            &jpeg,
        )
        .unwrap();

        assert_eq!(&packet[0..4], b"SYLV");
        assert_eq!(packet[4], LIVE_VIDEO_MONITOR_VERSION);
        assert_eq!(packet[5], LIVE_VIDEO_MONITOR_STATUS_FRAME);
        assert_eq!(packet[6], LiveVideoMonitorKind::Preview.packet_value());
        assert_eq!(packet[7], 0);
        assert_eq!(read_u64(&packet, 8), 0x0102_0304_0506_0708);
        assert_eq!(read_u64(&packet, 16), 12_345);
        assert_eq!(read_u32(&packet, 24), 678);
        assert_eq!(read_u32(&packet, 28), 90);
        assert_eq!(read_u16(&packet, 32), 320);
        assert_eq!(read_u16(&packet, 34), 180);
        assert_eq!(read_u32(&packet, 36), jpeg.len() as u32);
        assert_eq!(&packet[LIVE_VIDEO_MONITOR_HEADER_LEN..], jpeg);
    }

    #[test]
    fn live_video_monitor_request_limits_are_clamped() {
        assert_eq!(live_video_monitor_dimensions(0, 0), (1, 1));
        assert_eq!(
            live_video_monitor_dimensions(u32::MAX, u32::MAX),
            (LIVE_VIDEO_MONITOR_MAX_WIDTH, LIVE_VIDEO_MONITOR_MAX_HEIGHT)
        );
        assert_eq!(live_video_monitor_quality(None), 68);
        assert_eq!(live_video_monitor_quality(Some(0)), 40);
        assert_eq!(live_video_monitor_quality(Some(u8::MAX)), 90);
    }

    #[test]
    fn live_video_monitor_encodes_a_decodable_jpeg() {
        let frame = video::VideoFrame {
            layer_id: 1,
            width: 2,
            height: 2,
            pts_ms: 42,
            duration_ms: 33,
            format: video::VideoPixelFormat::Rgba8,
            data: vec![
                255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255, 255, 255, 255, 255,
            ],
        };

        let jpeg = encode_live_video_monitor_jpeg(&frame, 68).unwrap();
        assert_eq!(&jpeg[..2], &[0xff, 0xd8]);
        assert_eq!(&jpeg[jpeg.len() - 2..], &[0xff, 0xd9]);
        let decoded = image::load_from_memory_with_format(&jpeg, image::ImageFormat::Jpeg).unwrap();
        assert_eq!(decoded.width(), frame.width);
        assert_eq!(decoded.height(), frame.height);

        let mut invalid = frame;
        invalid.data.pop();
        assert!(encode_live_video_monitor_jpeg(&invalid, 68).is_err());
    }
}

fn video_preview_decode_budget(renderer: &AppVideoPreviewRenderer, layer_count: usize) -> usize {
    video_preview_decode_budget_from_prefetch(
        layer_count,
        renderer.frame_provider().prefetch_count(),
    )
}

fn video_preview_decode_budget_from_prefetch(layer_count: usize, prefetch_count: usize) -> usize {
    layer_count
        .max(1)
        .saturating_mul(prefetch_count.saturating_add(1).max(1))
}

fn resolved_video_preview_decode_budget(
    renderer: &AppVideoPreviewRenderer,
    layer_count: usize,
    requested: Option<usize>,
) -> usize {
    let full_budget = video_preview_decode_budget(renderer, layer_count);
    requested.unwrap_or(full_budget).clamp(1, full_budget)
}

