fn validate_existing_file_path(path: String, label: &str) -> Result<String, String> {
    let trimmed = path.trim();
    if trimmed.is_empty() {
        return Err(format!("{label} path is required"));
    }
    let metadata =
        fs::metadata(trimmed).map_err(|_| format!("{label} path was not found: {trimmed}"))?;
    if !metadata.is_file() {
        return Err(format!("{label} path must be a file: {trimmed}"));
    }
    Ok(trimmed.to_string())
}

fn validate_video_cue_point_color(color: &str) -> Result<(), String> {
    let trimmed = color.trim();
    let hex = trimmed.strip_prefix('#').unwrap_or(trimmed);
    if hex.len() == 6 && hex.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        Ok(())
    } else {
        Err("Video cue point color must be #RRGGBB".to_string())
    }
}

fn video_source_file_dialog_filter(
    kind: &VideoSourceKind,
) -> Result<(&'static str, &'static [&'static str]), String> {
    match kind {
        VideoSourceKind::File => Ok(("Video and Audio Files", VIDEO_FILE_EXTENSIONS)),
        VideoSourceKind::StillImage => Ok(("Still Images", STILL_IMAGE_EXTENSIONS)),
        VideoSourceKind::Camera
        | VideoSourceKind::ScreenCapture
        | VideoSourceKind::Ndi
        | VideoSourceKind::Spout
        | VideoSourceKind::Syphon => {
            Err("Only file and still-image sources can browse local media".to_string())
        }
    }
}

fn normalize_group_ids(group_ids: Vec<String>) -> Result<Vec<String>, String> {
    let mut normalized = Vec::new();
    let mut seen = HashSet::new();
    for group_id in group_ids {
        let group_id = normalize_group_id(&group_id)?;
        if seen.insert(group_id.clone()) {
            normalized.push(group_id);
        }
    }
    Ok(normalized)
}

fn normalize_group_id(group_id: &str) -> Result<String, String> {
    let trimmed = group_id.trim();
    if trimmed.is_empty() {
        return Err("Group IDs must not be empty".to_string());
    }
    let segments = trimmed.split('/').map(str::trim).collect::<Vec<_>>();
    if segments.iter().any(|segment| segment.is_empty()) {
        return Err("Group path segments must not be empty".to_string());
    }
    Ok(segments.join("/"))
}

fn group_matches(fixture_group_id: &str, requested_group_id: &str) -> bool {
    let Ok(fixture_group_id) = normalize_group_id(fixture_group_id) else {
        return false;
    };
    let Ok(requested_group_id) = normalize_group_id(requested_group_id) else {
        return false;
    };
    fixture_group_id == requested_group_id
        || fixture_group_id
            .strip_prefix(&requested_group_id)
            .is_some_and(|suffix| suffix.starts_with('/'))
}

fn validate_gdtf_share_credentials(user: &str, password: &str) -> Result<(), String> {
    if user.trim().is_empty() {
        return Err("GDTF Share user is required".to_string());
    }
    if password.is_empty() {
        return Err("GDTF Share password is required".to_string());
    }
    Ok(())
}

fn gdtf_share_cookie_path() -> PathBuf {
    std::env::temp_dir().join(format!(
        "syndocal-gdtf-share-{}-{}.cookies",
        std::process::id(),
        current_unix_ms()
    ))
}

fn gdtf_share_api_url(endpoint: &str) -> String {
    format!("https://gdtf-share.com/apis/public/{endpoint}")
}

fn run_curl(args: &[&OsStr]) -> Result<Vec<u8>, String> {
    let output = Command::new(curl_binary_name())
        .args(args)
        .output()
        .map_err(|error| format!("Failed to start curl: {error}"))?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
        let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
        let detail = if !stderr.is_empty() {
            stderr
        } else if !stdout.is_empty() {
            stdout
        } else {
            output
                .status
                .code()
                .map(|code| format!("exit code {code}"))
                .unwrap_or_else(|| "terminated".to_string())
        };
        return Err(format!("curl failed: {detail}"));
    }
    Ok(output.stdout)
}

fn curl_json_post(url: &str, body: &Value, cookie_path: Option<&Path>) -> Result<Value, String> {
    let body = serde_json::to_string(body).map_err(|error| error.to_string())?;
    let mut args: Vec<&OsStr> = vec![
        OsStr::new("--silent"),
        OsStr::new("--show-error"),
        OsStr::new("--max-time"),
        OsStr::new("60"),
        OsStr::new("-H"),
        OsStr::new("Content-Type: application/json"),
    ];
    if let Some(cookie_path) = cookie_path {
        args.push(OsStr::new("-b"));
        args.push(cookie_path.as_os_str());
        args.push(OsStr::new("-c"));
        args.push(cookie_path.as_os_str());
    }
    args.push(OsStr::new("--data"));
    args.push(OsStr::new(body.as_str()));
    args.push(OsStr::new(url));

    parse_curl_json_response(run_curl(&args)?)
}

fn curl_json_get(url: &str, cookie_path: &Path) -> Result<Value, String> {
    let args: Vec<&OsStr> = vec![
        OsStr::new("--silent"),
        OsStr::new("--show-error"),
        OsStr::new("--max-time"),
        OsStr::new("60"),
        OsStr::new("-b"),
        cookie_path.as_os_str(),
        OsStr::new("-c"),
        cookie_path.as_os_str(),
        OsStr::new(url),
    ];
    parse_curl_json_response(run_curl(&args)?)
}

fn parse_curl_json_response(bytes: Vec<u8>) -> Result<Value, String> {
    let text =
        String::from_utf8(bytes).map_err(|error| format!("Response was not UTF-8: {error}"))?;
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return Err("GDTF Share returned an empty response".to_string());
    }
    let value: Value = serde_json::from_str(trimmed).map_err(|error| {
        let snippet = trimmed.chars().take(220).collect::<String>();
        format!("GDTF Share returned non-JSON data: {error}: {snippet}")
    })?;
    if value.get("result").and_then(Value::as_bool) == Some(false) {
        return Err(value
            .get("error")
            .and_then(Value::as_str)
            .unwrap_or("GDTF Share request failed")
            .to_string());
    }
    Ok(value)
}

fn login_gdtf_share(user: &str, password: &str, cookie_path: &Path) -> Result<(), String> {
    let response = curl_json_post(
        &gdtf_share_api_url("login.php"),
        &json!({
            "user": user.trim(),
            "password": password,
        }),
        Some(cookie_path),
    )?;
    if response.get("result").and_then(Value::as_bool) == Some(false) {
        return Err(response
            .get("error")
            .and_then(Value::as_str)
            .unwrap_or("GDTF Share login failed")
            .to_string());
    }
    Ok(())
}

fn fetch_gdtf_share_catalog(cookie_path: &Path) -> Result<Value, String> {
    let attempts = [
        ("getList.php", None),
        ("getList.php", Some(json!({}))),
        ("getDiff.php", Some(json!({ "lastModified": 0 }))),
        ("getDiff.php", Some(json!({ "from": 0 }))),
        ("getDiff.php", Some(json!({}))),
    ];
    let mut last_error = String::new();
    for (endpoint, body) in attempts {
        let result = if let Some(body) = body {
            curl_json_post(&gdtf_share_api_url(endpoint), &body, Some(cookie_path))
        } else {
            curl_json_get(&gdtf_share_api_url(endpoint), cookie_path)
        };
        match result {
            Ok(value) => return Ok(value),
            Err(error) => last_error = error,
        }
    }
    Err(if last_error.is_empty() {
        "GDTF Share catalog request failed".to_string()
    } else {
        last_error
    })
}

fn find_string_field<'a>(map: &'a Map<String, Value>, keys: &[&str]) -> Option<&'a str> {
    keys.iter()
        .find_map(|key| map.get(*key).and_then(Value::as_str))
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn find_u64_field(map: &Map<String, Value>, keys: &[&str]) -> Option<u64> {
    keys.iter().find_map(|key| {
        let value = map.get(*key)?;
        value
            .as_u64()
            .or_else(|| value.as_str()?.trim().parse::<u64>().ok())
    })
}

fn find_bool_field(map: &Map<String, Value>, keys: &[&str]) -> Option<bool> {
    keys.iter().find_map(|key| {
        let value = map.get(*key)?;
        value.as_bool().or_else(|| {
            value.as_u64().map(|value| value != 0).or_else(|| {
                value
                    .as_str()
                    .and_then(|value| match value.trim().to_ascii_lowercase().as_str() {
                        "1" | "true" | "yes" | "tested" | "passed" => Some(true),
                        "0" | "false" | "no" | "untested" | "failed" => Some(false),
                        _ => None,
                    })
            })
        })
    })
}

fn gdtf_share_modes_from_value(value: Option<&Value>) -> Vec<GdtfShareModeSummary> {
    let Some(Value::Array(modes)) = value else {
        return Vec::new();
    };
    modes
        .iter()
        .filter_map(|mode| {
            let map = mode.as_object()?;
            let name = find_string_field(map, &["name", "mode", "dmxMode", "dmx_mode"])
                .unwrap_or("Mode")
                .to_string();
            let dmx_footprint = find_u64_field(
                map,
                &["dmxfootprint", "dmxFootprint", "footprint", "dmx_footprint"],
            )
            .and_then(|value| u16::try_from(value).ok());
            Some(GdtfShareModeSummary {
                name,
                dmx_footprint,
            })
        })
        .collect()
}

fn gdtf_share_fixture_from_map(map: &Map<String, Value>) -> Option<GdtfShareFixtureSummary> {
    let manufacturer = find_string_field(map, &["manufacturer", "manufacture", "maker", "brand"])?;
    let fixture = find_string_field(map, &["fixture", "name", "fixtureName", "fixture_name"])?;
    let revision = find_string_field(map, &["revision", "revisionName", "revision_name"])
        .or_else(|| find_string_field(map, &["file", "filename", "fileName"]))
        .unwrap_or("latest");
    Some(GdtfShareFixtureSummary {
        rid: find_u64_field(map, &["rid", "id", "revisionId", "revision_id"]),
        uuid: find_string_field(map, &["uuid", "guid", "fixtureTypeId", "fixture_type_id"])
            .map(ToString::to_string),
        manufacturer: manufacturer.to_string(),
        fixture: fixture.to_string(),
        revision: revision.to_string(),
        uploader: find_string_field(map, &["uploader", "uploadedBy", "uploaded_by"])
            .map(ToString::to_string),
        rating: find_string_field(map, &["rating"]).map(ToString::to_string),
        version: find_string_field(map, &["version", "gdtfVersion", "gdtf_version"])
            .map(ToString::to_string),
        creator: find_string_field(map, &["creator", "author"]).map(ToString::to_string),
        filesize: find_u64_field(map, &["filesize", "fileSize", "size"]),
        release_status: find_string_field(
            map,
            &[
                "releaseStatus",
                "release_status",
                "status",
                "fileStatus",
                "file_status",
            ],
        )
        .map(ToString::to_string),
        tested_in_visualizer: find_bool_field(
            map,
            &[
                "testedInVisualizer",
                "tested_in_visualizer",
                "testedInVisualiser",
                "tested_in_visualiser",
                "visualizerTested",
                "visualiserTested",
            ],
        ),
        tested_in_real_life: find_bool_field(
            map,
            &[
                "testedInRealLife",
                "tested_in_real_life",
                "realLifeTested",
                "real_life_tested",
            ],
        ),
        modes: gdtf_share_modes_from_value(map.get("modes")),
    })
}

fn collect_gdtf_share_fixture_maps(value: &Value, fixtures: &mut Vec<GdtfShareFixtureSummary>) {
    match value {
        Value::Array(items) => {
            for item in items {
                collect_gdtf_share_fixture_maps(item, fixtures);
            }
        }
        Value::Object(map) => {
            if let Some(fixture) = gdtf_share_fixture_from_map(map) {
                fixtures.push(fixture);
                return;
            }
            for nested in map.values() {
                collect_gdtf_share_fixture_maps(nested, fixtures);
            }
        }
        _ => {}
    }
}

fn extract_gdtf_share_fixtures(value: &Value) -> Vec<GdtfShareFixtureSummary> {
    let mut fixtures = Vec::new();
    collect_gdtf_share_fixture_maps(value, &mut fixtures);
    let mut seen = HashSet::new();
    fixtures.retain(|fixture| {
        let key = format!(
            "{}|{}|{}|{:?}|{:?}",
            fixture.manufacturer.to_ascii_lowercase(),
            fixture.fixture.to_ascii_lowercase(),
            fixture.revision.to_ascii_lowercase(),
            fixture.rid,
            fixture.uuid
        );
        seen.insert(key)
    });
    fixtures
}

fn gdtf_share_filter_matches(fixture: &GdtfShareFixtureSummary, needle: &str) -> bool {
    if needle.trim().is_empty() {
        return true;
    }
    let needle = needle.trim().to_ascii_lowercase();
    let field_match = [
        fixture.manufacturer.as_str(),
        fixture.fixture.as_str(),
        fixture.revision.as_str(),
        fixture.uploader.as_deref().unwrap_or_default(),
        fixture.creator.as_deref().unwrap_or_default(),
        fixture.version.as_deref().unwrap_or_default(),
    ]
    .iter()
    .any(|value| value.to_ascii_lowercase().contains(&needle));
    field_match
        || fixture.modes.iter().any(|mode| {
            mode.name.to_ascii_lowercase().contains(&needle)
                || mode
                    .dmx_footprint
                    .is_some_and(|footprint| format!("{footprint}ch").contains(&needle))
        })
}

fn filter_gdtf_share_results(
    mut fixtures: Vec<GdtfShareFixtureSummary>,
    manufacturer: &str,
    fixture: &str,
    query: &str,
    mode: &str,
    min_footprint: Option<u16>,
    max_footprint: Option<u16>,
    release_only: bool,
    tested_in_visualizer: bool,
    tested_in_real_life: bool,
    limit: usize,
) -> GdtfShareSearchResponse {
    let filter_support = GdtfShareFilterSupport {
        release_status: fixtures
            .iter()
            .any(|fixture| fixture.release_status.is_some()),
        tested_in_visualizer: fixtures
            .iter()
            .any(|fixture| fixture.tested_in_visualizer.is_some()),
        tested_in_real_life: fixtures
            .iter()
            .any(|fixture| fixture.tested_in_real_life.is_some()),
    };
    let mut manufacturers = fixtures
        .iter()
        .map(|fixture| fixture.manufacturer.clone())
        .collect::<Vec<_>>();
    manufacturers.sort_by_key(|value| value.to_ascii_lowercase());
    manufacturers.dedup_by(|left, right| left.eq_ignore_ascii_case(right));
    let mut modes = fixtures
        .iter()
        .flat_map(|fixture| fixture.modes.iter().map(|mode| mode.name.clone()))
        .collect::<Vec<_>>();
    modes.sort_by_key(|value| value.to_ascii_lowercase());
    modes.dedup_by(|left, right| left.eq_ignore_ascii_case(right));
    let mut versions = fixtures
        .iter()
        .filter_map(|fixture| fixture.version.clone())
        .collect::<Vec<_>>();
    versions.sort_by_key(|value| value.to_ascii_lowercase());
    versions.dedup_by(|left, right| left.eq_ignore_ascii_case(right));

    let manufacturer = manufacturer.trim().to_ascii_lowercase();
    let fixture_name = fixture.trim().to_ascii_lowercase();
    let mode = mode.trim().to_ascii_lowercase();
    fixtures.retain(|candidate| {
        (manufacturer.is_empty()
            || candidate
                .manufacturer
                .to_ascii_lowercase()
                .contains(&manufacturer))
            && (fixture_name.is_empty()
                || candidate
                    .fixture
                    .to_ascii_lowercase()
                    .contains(&fixture_name))
            && gdtf_share_filter_matches(candidate, query)
            && (mode.is_empty()
                || candidate
                    .modes
                    .iter()
                    .any(|candidate_mode| candidate_mode.name.to_ascii_lowercase().contains(&mode)))
            && (min_footprint.is_none() && max_footprint.is_none()
                || candidate.modes.iter().any(|candidate_mode| {
                    candidate_mode.dmx_footprint.is_some_and(|footprint| {
                        min_footprint.is_none_or(|minimum| footprint >= minimum)
                            && max_footprint.is_none_or(|maximum| footprint <= maximum)
                    })
                }))
            && (!release_only
                || candidate.release_status.as_deref().is_some_and(|status| {
                    matches!(
                        status.trim().to_ascii_lowercase().as_str(),
                        "release" | "released"
                    )
                }))
            && (!tested_in_visualizer || candidate.tested_in_visualizer == Some(true))
            && (!tested_in_real_life || candidate.tested_in_real_life == Some(true))
    });
    fixtures.sort_by(|left, right| {
        left.manufacturer
            .cmp(&right.manufacturer)
            .then_with(|| left.fixture.cmp(&right.fixture))
            .then_with(|| left.revision.cmp(&right.revision))
    });
    let total_matches = fixtures.len();
    fixtures.truncate(limit.clamp(1, 200));
    GdtfShareSearchResponse {
        fixtures,
        facets: GdtfShareSearchFacets {
            manufacturers,
            modes,
            versions,
        },
        filter_support,
        total_matches,
    }
}

fn gdtf_share_download_file_name(request: &GdtfShareDownloadRequest) -> String {
    let label = [
        request.manufacturer.as_str(),
        request.fixture.as_str(),
        request.revision.as_str(),
    ]
    .iter()
    .map(|value| value.trim())
    .filter(|value| !value.is_empty())
    .collect::<Vec<_>>()
    .join("-");
    format!("{}.gdtf", safe_file_stem(&label))
}

fn gdtf_share_download_url(request: &GdtfShareDownloadRequest) -> Result<String, String> {
    let rid = request.rid.ok_or_else(|| {
        "GDTF Share download requires a revision ID from the public catalog".to_string()
    })?;
    Ok(format!(
        "{}?rid={rid}",
        gdtf_share_api_url("downloadFile.php")
    ))
}

fn download_gdtf_share_file(
    request: &GdtfShareDownloadRequest,
    cookie_path: &Path,
    path: &Path,
) -> Result<(), String> {
    let url = gdtf_share_download_url(request)?;
    let args: Vec<&OsStr> = vec![
        OsStr::new("-L"),
        OsStr::new("--silent"),
        OsStr::new("--show-error"),
        OsStr::new("--max-time"),
        OsStr::new("120"),
        OsStr::new("-b"),
        cookie_path.as_os_str(),
        OsStr::new("-o"),
        path.as_os_str(),
        OsStr::new(url.as_str()),
    ];
    if let Err(error) = run_curl(&args) {
        let _ = fs::remove_file(path);
        return Err(error);
    }
    validate_gdtf_share_download_payload(path).map_err(|error| {
        let _ = fs::remove_file(path);
        error
    })?;
    Ok(())
}

fn validate_gdtf_share_download_payload(path: &Path) -> Result<(), String> {
    let metadata = fs::metadata(path)
        .map_err(|error| format!("GDTF Share download was not saved: {error}"))?;
    if metadata.len() == 0 {
        return Err("GDTF Share downloaded an empty file".to_string());
    }
    let mut file = fs::File::open(path)
        .map_err(|error| format!("Failed to inspect GDTF Share download: {error}"))?;
    let mut buffer = vec![0u8; usize::min(metadata.len() as usize, 4096)];
    let read = file
        .read(&mut buffer)
        .map_err(|error| format!("Failed to inspect GDTF Share download: {error}"))?;
    buffer.truncate(read);
    let trimmed_start = buffer
        .iter()
        .position(|byte| !byte.is_ascii_whitespace())
        .unwrap_or(0);
    let payload = &buffer[trimmed_start..];
    if payload.starts_with(b"PK") {
        return Ok(());
    }
    if payload
        .first()
        .is_some_and(|byte| *byte == b'{' || *byte == b'[')
    {
        let text = String::from_utf8_lossy(payload);
        let value = serde_json::from_str::<Value>(&text).ok();
        if let Some(error) = value
            .as_ref()
            .and_then(|value| value.get("error"))
            .and_then(Value::as_str)
        {
            return Err(format!("GDTF Share download failed: {error}"));
        }
        return Err("GDTF Share returned JSON instead of a .gdtf archive".to_string());
    }
    if payload.first().is_some_and(|byte| *byte == b'<') {
        let snippet = String::from_utf8_lossy(payload)
            .chars()
            .take(180)
            .collect::<String>();
        return Err(format!(
            "GDTF Share returned HTML instead of a .gdtf archive: {snippet}"
        ));
    }
    Ok(())
}

fn validate_gdtf_share_download_identity(request: &GdtfShareDownloadRequest) -> Result<(), String> {
    if request.rid.is_none() {
        return Err(
            "GDTF Share result is missing the revision ID required by the public download API"
                .to_string(),
        );
    }
    if request.manufacturer.trim().is_empty() || request.fixture.trim().is_empty() {
        return Err("GDTF Share manufacturer and fixture are required".to_string());
    }
    Ok(())
}

fn gdtf_fixture_cache_metadata(request: &GdtfShareDownloadRequest) -> GdtfFixtureCacheMetadata {
    let identity = request
        .rid
        .map(|rid| format!("rid-{rid}"))
        .or_else(|| {
            request
                .uuid
                .as_deref()
                .map(str::trim)
                .filter(|uuid| !uuid.is_empty())
                .map(|uuid| format!("uuid-{}", safe_file_stem(uuid)))
        })
        .unwrap_or_else(|| "unknown".to_string());
    GdtfFixtureCacheMetadata {
        version: 1,
        key: format!(
            "share:{}:{}:{}:{}",
            safe_file_stem(request.manufacturer.trim()),
            safe_file_stem(request.fixture.trim()),
            safe_file_stem(request.revision.trim()),
            identity
        )
        .to_ascii_lowercase(),
        rid: request.rid,
        uuid: request
            .uuid
            .as_deref()
            .map(str::trim)
            .filter(|uuid| !uuid.is_empty())
            .map(ToString::to_string),
        manufacturer: request.manufacturer.trim().to_string(),
        fixture: request.fixture.trim().to_string(),
        revision: request.revision.trim().to_string(),
    }
}

fn gdtf_fixture_cache_path(directory: &Path, metadata: &GdtfFixtureCacheMetadata) -> PathBuf {
    let identity = metadata
        .rid
        .map(|rid| format!("rid-{rid}"))
        .or_else(|| {
            metadata
                .uuid
                .as_deref()
                .map(|uuid| bounded_safe_file_stem(uuid, 24))
        })
        .unwrap_or_else(|| "profile".to_string());
    directory.join(format!(
        "{}-{}-{}-{}.gdtf",
        bounded_safe_file_stem(&metadata.manufacturer, 24),
        bounded_safe_file_stem(&metadata.fixture, 40),
        bounded_safe_file_stem(&metadata.revision, 24),
        identity
    ))
}

fn bounded_safe_file_stem(value: &str, max_chars: usize) -> String {
    safe_file_stem(value)
        .chars()
        .take(max_chars.max(1))
        .collect()
}

fn gdtf_fixture_cache_metadata_path(path: &Path) -> PathBuf {
    path.with_extension("json")
}

fn write_gdtf_fixture_cache_metadata(
    path: &Path,
    metadata: &GdtfFixtureCacheMetadata,
) -> Result<(), String> {
    let json = serde_json::to_string_pretty(metadata).map_err(|error| error.to_string())?;
    fs::write(gdtf_fixture_cache_metadata_path(path), json)
        .map_err(|error| format!("Unable to write fixture cache metadata: {error}"))
}

fn read_gdtf_fixture_cache_metadata(path: &Path) -> Option<GdtfFixtureCacheMetadata> {
    let json = fs::read_to_string(gdtf_fixture_cache_metadata_path(path)).ok()?;
    let metadata = serde_json::from_str::<GdtfFixtureCacheMetadata>(&json).ok()?;
    (metadata.version == 1).then_some(metadata)
}

fn inspect_gdtf_cache_file(
    path: &Path,
    metadata: Option<GdtfFixtureCacheMetadata>,
) -> Result<GdtfFixtureCacheEntry, String> {
    let file_metadata = fs::metadata(path).map_err(|error| {
        format!(
            "Unable to inspect fixture cache '{}': {error}",
            path.display()
        )
    })?;
    let fallback_label = path
        .file_stem()
        .and_then(OsStr::to_str)
        .unwrap_or("Cached fixture")
        .to_string();
    match gdtf::load_profile(path) {
        Ok(profile) => {
            let warnings = profile.warnings.clone();
            let health = if warnings.is_empty() {
                "healthy"
            } else {
                "warnings"
            };
            let detail = if warnings.is_empty() {
                format!("{} DMX mode(s) parsed", profile.dmx_modes.len())
            } else {
                format!("Parsed with {} warning(s)", warnings.len())
            };
            let metadata = metadata.unwrap_or_else(|| GdtfFixtureCacheMetadata {
                version: 1,
                key: format!("cache:{}", safe_file_stem(&fallback_label)).to_ascii_lowercase(),
                rid: None,
                uuid: profile.fixture_type_id.clone(),
                manufacturer: profile.manufacturer.clone(),
                fixture: profile.name.clone(),
                revision: "cached".to_string(),
            });
            Ok(GdtfFixtureCacheEntry {
                key: metadata.key,
                rid: metadata.rid,
                uuid: metadata.uuid,
                manufacturer: if metadata.manufacturer.trim().is_empty() {
                    profile.manufacturer.clone()
                } else {
                    metadata.manufacturer
                },
                fixture: if metadata.fixture.trim().is_empty() {
                    profile.name.clone()
                } else {
                    metadata.fixture
                },
                revision: metadata.revision,
                path: path.to_string_lossy().to_string(),
                filesize: file_metadata.len(),
                health: health.to_string(),
                detail,
                warnings,
                modes: profile
                    .dmx_modes
                    .iter()
                    .map(|mode| GdtfShareModeSummary {
                        name: mode.name.clone(),
                        dmx_footprint: gdtf::dmx_mode_footprint(mode),
                    })
                    .collect(),
            })
        }
        Err(error) => {
            let metadata = metadata.unwrap_or_else(|| GdtfFixtureCacheMetadata {
                version: 1,
                key: format!("cache:{}", safe_file_stem(&fallback_label)).to_ascii_lowercase(),
                rid: None,
                uuid: None,
                manufacturer: "Unknown".to_string(),
                fixture: fallback_label,
                revision: "cached".to_string(),
            });
            Ok(GdtfFixtureCacheEntry {
                key: metadata.key,
                rid: metadata.rid,
                uuid: metadata.uuid,
                manufacturer: metadata.manufacturer,
                fixture: metadata.fixture,
                revision: metadata.revision,
                path: path.to_string_lossy().to_string(),
                filesize: file_metadata.len(),
                health: "invalid".to_string(),
                detail: error.to_string(),
                warnings: Vec::new(),
                modes: Vec::new(),
            })
        }
    }
}

fn inspect_gdtf_fixture_cache_directory(
    directory: &Path,
) -> Result<Vec<GdtfFixtureCacheEntry>, String> {
    let mut entries = Vec::new();
    for entry in fs::read_dir(directory).map_err(|error| {
        format!(
            "Unable to read fixture cache '{}': {error}",
            directory.display()
        )
    })? {
        let path = entry.map_err(|error| error.to_string())?.path();
        if path.is_file() && has_extension(&path, "gdtf") {
            entries.push(inspect_gdtf_cache_file(
                &path,
                read_gdtf_fixture_cache_metadata(&path),
            )?);
        }
    }
    entries.sort_by(|left, right| {
        left.manufacturer
            .cmp(&right.manufacturer)
            .then_with(|| left.fixture.cmp(&right.fixture))
            .then_with(|| left.revision.cmp(&right.revision))
    });
    Ok(entries)
}

fn verified_control(
    attribute: &str,
    channel_name: &str,
    offsets: &[u16],
    resolution: AttributeResolution,
) -> AttributeControl {
    AttributeControl {
        attribute: attribute.to_string(),
        channel_name: channel_name.to_string(),
        geometry: None,
        offsets: offsets.to_vec(),
        resolution,
        default_value: 0,
        functions: Vec::new(),
    }
}

fn verified_fixture_profile(
    id: &str,
    name: &str,
    description: &str,
    controls: Vec<AttributeControl>,
) -> (VerifiedFixtureProfileSummary, FixtureProfileSummary) {
    let mode = DmxModeSummary {
        name: "Standard".to_string(),
        controls,
    };
    let footprint = gdtf::dmx_mode_footprint(&mode).unwrap_or(0);
    (
        VerifiedFixtureProfileSummary {
            id: id.to_string(),
            manufacturer: "Syndocal Verified".to_string(),
            name: name.to_string(),
            mode_name: mode.name.clone(),
            footprint,
            description: description.to_string(),
        },
        FixtureProfileSummary {
            source_path: format!("memory://verified/common-rig/{id}/v1"),
            manufacturer: "Syndocal Verified".to_string(),
            name: name.to_string(),
            short_name: None,
            fixture_type_id: Some(format!("syndocal-verified-{id}-v1")),
            dmx_modes: vec![mode],
            geometries: Vec::new(),
            warnings: Vec::new(),
        },
    )
}

