    #[test]
    fn group_delete_and_undo_restore_entity_membership_color_and_order() {
        let mut project = empty_project_file();
        let mut first = project_fixture(1, "First fixture", 0, 1);
        first.group_ids = vec!["other".to_string(), "fixture-group-1".to_string()];
        let mut second = project_fixture(2, "Second fixture", 0, 16);
        second.group_ids = vec!["fixture-group-1".to_string()];
        project.snapshot.fixtures = vec![first, second];
        project.fixture_groups = vec![
            FixtureGroupSummary {
                id: "other".to_string(),
                label: "Other".to_string(),
                color: None,
            },
            FixtureGroupSummary {
                id: "fixture-group-1".to_string(),
                label: "Front wash".to_string(),
                color: Some("#22aa88".to_string()),
            },
        ];
        project
            .snapshot
            .group_colors
            .insert("fixture-group-1".to_string(), "#22aa88".to_string());
        let before = project.clone();

        let deleted =
            delete_fixture_group_from_project_data(&mut project, "fixture-group-1").unwrap();
        assert_eq!(deleted.group.label, "Front wash");
        assert!(project
            .snapshot
            .fixtures
            .iter()
            .all(|fixture| !fixture.group_ids.contains(&"fixture-group-1".to_string())));
        assert!(!project
            .snapshot
            .group_colors
            .contains_key("fixture-group-1"));

        undo_delete_fixture_group_in_project_data(&mut project, deleted).unwrap();
        assert_eq!(project, before);
        validate_project_file(&project).unwrap();
    }

    #[test]
    fn operator_policy_round_trips_without_plaintext_and_rejects_invalid_verifiers() {
        let policy = sample_operator_policy();
        validate_operator_policy(&policy).unwrap();
        let mut project = empty_project_file();
        project.operator_policy = Some(policy.clone());

        let json = serde_json::to_string_pretty(&project).unwrap();
        let parsed: ProjectFile = serde_json::from_str(&json).unwrap();

        assert!(json.contains("\"operator_policy\""));
        assert!(json.contains(OPERATOR_CREDENTIAL_SCHEME));
        assert!(!json.to_ascii_lowercase().contains("password"));
        assert_eq!(parsed.operator_policy, Some(policy.clone()));
        validate_project_file(&parsed).unwrap();

        let mut invalid = policy.clone();
        invalid.credential.scheme = "SHA-256".to_string();
        assert!(validate_operator_policy(&invalid)
            .unwrap_err()
            .contains(OPERATOR_CREDENTIAL_SCHEME));
        invalid = policy.clone();
        invalid.credential.iterations = OPERATOR_CREDENTIAL_MIN_ITERATIONS - 1;
        assert!(validate_operator_policy(&invalid)
            .unwrap_err()
            .contains("iterations"));
        invalid = policy.clone();
        invalid.credential.salt_b64 = "not base64".to_string();
        assert!(validate_operator_policy(&invalid)
            .unwrap_err()
            .contains("salt"));
        invalid = policy;
        invalid.credential.verifier_b64 =
            base64::engine::general_purpose::STANDARD.encode([0xa7; 31]);
        assert!(validate_operator_policy(&invalid)
            .unwrap_err()
            .contains("32 bytes"));
    }

    #[test]
    fn media_asset_authoritative_operator_pbkdf2_matches_known_sha256_vector() {
        let derived = operator_pbkdf2_sha256(b"password", b"salt", 1);
        let derived_hex = derived
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>();
        assert_eq!(
            derived_hex,
            "120fb6cffcf8b32c43e7225256c4f837a86548c92ccc35480805987cb70be17b"
        );
        validate_operator_password_input("12345678").unwrap();
        validate_operator_password_input("😀😀😀😀").unwrap();
        assert!(validate_operator_password_input("1234567").is_err());
        assert!(
            validate_operator_password_input(&"x".repeat(OPERATOR_PASSWORD_MAX_BYTES + 1)).is_err()
        );
    }

    #[test]
    fn media_asset_authoritative_operator_sessions_fail_closed_and_reset_on_policy_change() {
        let owner_id = "renderer:test";
        let mut coordinator = ProjectCoordinator::default();
        let mut policy = sample_operator_policy();
        coordinator.ancillary.operator_policy = Some(policy.clone());
        let mut sessions = HashMap::new();

        let locked = project_operator_sessions_allow_authoritative_mutation(
            &mut sessions,
            &coordinator,
            owner_id,
        )
        .unwrap_err();
        assert!(locked.contains("Partial Lock"));
        sessions.get_mut(owner_id).unwrap().unlocked = true;
        project_operator_sessions_allow_authoritative_mutation(
            &mut sessions,
            &coordinator,
            owner_id,
        )
        .unwrap();

        coordinator.epoch = 1;
        let replaced = project_operator_sessions_allow_authoritative_mutation(
            &mut sessions,
            &coordinator,
            owner_id,
        )
        .unwrap_err();
        assert!(replaced.contains("Partial Lock"));
        assert!(!sessions.get(owner_id).unwrap().unlocked);

        policy.lock_mode = OperatorLockMode::Full;
        coordinator.ancillary.operator_policy = Some(policy.clone());
        let changed_policy = project_operator_sessions_allow_authoritative_mutation(
            &mut sessions,
            &coordinator,
            owner_id,
        )
        .unwrap_err();
        assert!(changed_policy.contains("Full Lock"));

        policy.lock_on_load = false;
        coordinator.ancillary.operator_policy = Some(policy);
        project_operator_sessions_allow_authoritative_mutation(
            &mut sessions,
            &coordinator,
            owner_id,
        )
        .unwrap();

        coordinator.ancillary.operator_policy = None;
        project_operator_sessions_allow_authoritative_mutation(
            &mut sessions,
            &coordinator,
            owner_id,
        )
        .unwrap();
        assert!(!sessions.contains_key(owner_id));
    }

