    #[test]
    fn strict_sdc_validation_rejects_duplicate_or_unknown_cue_effect_targets() {
        // Param-less targets retain the strict legacy reference contract. Cue-owned parameter
        // snapshots are covered separately because they deliberately survive stack deletion.
        let mut project = project_with_effect_only_cue();
        validate_project_file(&project).unwrap();

        project.snapshot.cues[0]
            .effect_targets
            .push(CueEffectTarget {
                effect_id: 9,
                enabled: true,
                params: None,
                transition_ms: None,
            });
        assert_eq!(
            validate_project_file(&project).unwrap_err(),
            "Project contains duplicate cue 7 effect reference 9"
        );

        project.snapshot.cues[0].effect_targets = vec![CueEffectTarget {
            effect_id: 99,
            enabled: true,
            params: None,
            transition_ms: None,
        }];
        assert_eq!(
            validate_project_file(&project).unwrap_err(),
            "Project cue 7 references missing effect 99"
        );

        let mut project = project_with_effect_only_cue();
        project.snapshot.cues[0].effect_targets[0].transition_ms = Some(100);
        assert_eq!(
            validate_project_file(&project).unwrap_err(),
            "Project cue 7 effect 9 cannot fade without Cue-owned parameters"
        );
    }

    #[test]
    fn project_cue_owned_effect_target_survives_missing_global_effect_and_validates() {
        let mut project = project_with_effect_only_cue();
        let params = effect_params_snapshot_from_summary(&project.snapshot.effects[0]).unwrap();
        project.snapshot.cues[0].effect_targets[0] = CueEffectTarget {
            effect_id: 9,
            enabled: true,
            params: Some(params),
            transition_ms: Some(750),
        };
        project.snapshot.effects.clear();

        validate_project_file(&project).unwrap();
        let json = project_json_for_write(&project).unwrap();
        let roundtrip: ProjectFile = serde_json::from_str(&json).unwrap();
        assert_eq!(roundtrip, project);
        assert_eq!(
            roundtrip.snapshot.cues[0].effect_targets[0].transition_ms,
            Some(750)
        );

        let EffectParamsSnapshot::Lfo(request) = roundtrip.snapshot.cues[0].effect_targets[0]
            .params
            .as_ref()
            .unwrap()
        else {
            panic!("expected an owned LFO request");
        };
        assert_eq!(request.period_ms, 500);

        let mut invalid = roundtrip.clone();
        let Some(EffectParamsSnapshot::Lfo(request)) =
            invalid.snapshot.cues[0].effect_targets[0].params.as_mut()
        else {
            panic!("expected an owned LFO request");
        };
        request.period_ms = 1;
        assert!(validate_project_file(&invalid)
            .unwrap_err()
            .contains("at least 10 ms"));

        let mut invalid_transition = roundtrip.clone();
        invalid_transition.snapshot.cues[0].effect_targets[0].transition_ms = Some(600_001);
        assert_eq!(
            validate_project_file(&invalid_transition).unwrap_err(),
            "Project cue 7 effect 9 transition must not exceed 600000 ms"
        );

        let mut legacy_missing = roundtrip;
        legacy_missing.snapshot.cues[0].effect_targets[0].params = None;
        legacy_missing.snapshot.cues[0].effect_targets[0].transition_ms = None;
        assert_eq!(
            validate_project_file(&legacy_missing).unwrap_err(),
            "Project cue 7 references missing effect 9"
        );
    }

    #[test]
    fn scene_owned_fx_command_matches_imported_shape_roundtrips_and_removes() {
        let cue_id = 17;
        let mut source_request = sample_lfo_request();
        source_request.label = "Imported Sinus".to_string();
        source_request.daslight_curve = Some(protocol::DaslightCurveSource {
            rate: 10.0,
            size: 0.5,
            offset: 0.1,
            sample_ms: 40,
            rng_seed: None,
        });
        let params = EffectParamsSnapshot::Lfo(source_request);
        let snapshot = EngineSnapshot {
            fixtures: vec![project_fixture(1, "Scene fixture", 0, 1)],
            cues: vec![protocol::CueSummary {
                id: cue_id,
                label: "Editable scene".to_string(),
                targets: vec![CueFixtureTarget {
                    fixture_id: 1,
                    values: vec![protocol::AttributeValueSummary {
                        attribute: "Dimmer".to_string(),
                        value: 32_768,
                    }],
                }],
                ..protocol::CueSummary::default()
            }],
            ..EngineSnapshot::default()
        };
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        engine.load_project_snapshot(snapshot).unwrap();

        let effect_id = add_cue_owned_effect_to_engine(&engine, cue_id, params.clone()).unwrap();
        let added = engine.snapshot();
        let imported_shape = CueEffectTarget {
            effect_id,
            enabled: true,
            params: Some(params),
            transition_ms: None,
        };
        assert!(added.effects.is_empty());
        assert_eq!(added.cues[0].effect_targets, vec![imported_shape.clone()]);

        let project = ProjectFile {
            version: PROJECT_FILE_VERSION,
            app: APP_NAME.to_string(),
            operator_policy: None,
            custom_profiles: Vec::new(),
            fixture_groups: Vec::new(),
            snapshot: added,
        };
        validate_project_file(&project).unwrap();
        let json = project_json_for_write(&project).unwrap();
        let roundtrip: ProjectFile = serde_json::from_str(&json).unwrap();
        assert_eq!(
            roundtrip.snapshot.cues[0].effect_targets,
            vec![imported_shape]
        );
        let Some(EffectParamsSnapshot::Lfo(roundtripped_request)) =
            roundtrip.snapshot.cues[0].effect_targets[0].params.as_ref()
        else {
            panic!("expected a round-tripped imported LFO request");
        };
        assert_eq!(
            roundtripped_request.daslight_curve,
            Some(protocol::DaslightCurveSource {
                rate: 10.0,
                size: 0.5,
                offset: 0.1,
                sample_ms: 40,
                rng_seed: None,
            })
        );
        assert!(roundtrip.snapshot.effects.is_empty());

        engine
            .set_cue_effect_targets_published(cue_id, Vec::new())
            .unwrap();
        assert!(engine.snapshot().cues[0].effect_targets.is_empty());
    }

