    #[test]
    fn project_file_roundtrips_fx_color_palette_without_static_values() {
        let project = ProjectFile {
            version: PROJECT_FILE_VERSION,
            app: "Syndocal".to_string(),
            operator_policy: None,
            custom_profiles: Vec::new(),
            fixture_groups: Vec::new(),
            snapshot: EngineSnapshot {
                palettes: vec![protocol::ReferencePaletteSummary {
                    id: 12,
                    label: "Campus FX".to_string(),
                    kind: protocol::PaletteKind::Color,
                    values: Vec::new(),
                    color_stops: vec![
                        protocol::ColorEffectStop {
                            position: 0.0,
                            color: protocol::ColorEffectColor {
                                red: 65_535,
                                green: 0,
                                blue: 0,
                            },
                        },
                        protocol::ColorEffectStop {
                            position: 1.0,
                            color: protocol::ColorEffectColor {
                                red: 0,
                                green: 0,
                                blue: 65_535,
                            },
                        },
                    ],
                }],
                ..EngineSnapshot::default()
            },
        };

        validate_project_file(&project).unwrap();
        let encoded = serde_json::to_vec(&project).unwrap();
        let decoded: ProjectFile = serde_json::from_slice(&encoded).unwrap();
        validate_project_file(&decoded).unwrap();
        assert_eq!(decoded.snapshot.palettes[0].color_stops.len(), 2);
        assert!(decoded.snapshot.palettes[0].values.is_empty());
    }

    #[test]
    fn fx_palette_validation_accepts_the_complete_daslight_cardinality_domain() {
        let stops = |last: u16| {
            (0..=last)
                .map(|index| protocol::ColorEffectStop {
                    position: if last == 0 {
                        0.0
                    } else {
                        f32::from(index) / f32::from(last)
                    },
                    color: protocol::ColorEffectColor {
                        red: index.saturating_mul(255),
                        green: 0,
                        blue: 0,
                    },
                })
                .collect::<Vec<_>>()
        };

        let mut one = stops(0);
        validate_fx_palette_stops(&mut one).unwrap();
        let mut maximum = stops(u16::from(u8::MAX) - 1);
        validate_fx_palette_stops(&mut maximum).unwrap();
        assert_eq!(maximum.len(), 255);
        let mut oversized = stops(u16::from(u8::MAX));
        assert!(validate_fx_palette_stops(&mut oversized)
            .unwrap_err()
            .contains("from 1 to 255"));
    }

