    #[test]
    fn effects_only_explicit_clear_validates_the_final_preserved_cue_body() {
        let existing = protocol::CueSummary {
            id: 42,
            label: "Mixed Look".to_string(),
            targets: vec![CueFixtureTarget {
                fixture_id: 1,
                values: vec![protocol::AttributeValueSummary {
                    attribute: "Dimmer".to_string(),
                    value: 30_000,
                }],
            }],
            effect_targets: vec![CueEffectTarget {
                effect_id: 11,
                enabled: true,
                params: None,
                transition_ms: None,
            }],
            ..protocol::CueSummary::default()
        };
        let snapshot = EngineSnapshot {
            cues: vec![existing.clone()],
            ..EngineSnapshot::default()
        };
        let cleared = merge_cue_update_targets(
            &snapshot,
            42,
            &CueCaptureScope::EffectsOnly,
            (Vec::new(), Vec::new(), Vec::new(), Vec::new(), Vec::new()),
            Some(Vec::new()),
        )
        .unwrap();

        assert_eq!(cleared.0, existing.targets);
        assert!(cleared.4.is_empty());
        ensure_cue_targets_present(
            &cleared.0, &cleared.1, &cleared.2, &cleared.3, &cleared.4, false, "updating",
        )
        .unwrap();

        let empty_snapshot = EngineSnapshot {
            cues: vec![protocol::CueSummary {
                id: 43,
                label: "Effect Only".to_string(),
                effect_targets: vec![CueEffectTarget {
                    effect_id: 11,
                    enabled: true,
                    params: None,
                    transition_ms: None,
                }],
                ..protocol::CueSummary::default()
            }],
            ..EngineSnapshot::default()
        };
        let empty = merge_cue_update_targets(
            &empty_snapshot,
            43,
            &CueCaptureScope::EffectsOnly,
            (Vec::new(), Vec::new(), Vec::new(), Vec::new(), Vec::new()),
            Some(Vec::new()),
        )
        .unwrap();
        assert!(ensure_cue_targets_present(
            &empty.0, &empty.1, &empty.2, &empty.3, &empty.4, false, "updating",
        )
        .is_err());
        assert_eq!(
            validate_cue_effect_target_replacement(&empty_snapshot.cues[0], &[]).unwrap_err(),
            "Cue 43 would contain no targets after clearing Effect Recall; remove the Cue instead"
        );

        let palette_only = protocol::CueSummary {
            id: 44,
            label: "Palette Recall".to_string(),
            palette_targets: vec![protocol::CuePaletteTarget {
                palette_id: 7,
                fixture_ids: vec![1],
            }],
            effect_targets: vec![CueEffectTarget {
                effect_id: 11,
                enabled: true,
                params: None,
                transition_ms: None,
            }],
            ..protocol::CueSummary::default()
        };
        validate_cue_effect_target_replacement(&palette_only, &[]).unwrap();
    }

    #[test]
    fn fixture_transform_validation_rejects_non_finite_values() {
        let error = validate_fixture_transform(
            &Vec3 {
                x: f32::NAN,
                y: 0.0,
                z: 0.0,
            },
            &Rotation3::default(),
        )
        .unwrap_err();
        assert!(error.contains("position"));

        let error = validate_fixture_transform(
            &Vec3::default(),
            &Rotation3 {
                pitch: 0.0,
                yaw: f32::INFINITY,
                roll: 0.0,
            },
        )
        .unwrap_err();
        assert!(error.contains("rotation"));
    }

    #[test]
    fn stage_map_config_validation_rejects_invalid_bounds() {
        let non_finite = StageMapConfig {
            locked: true,
            min_x: f32::NAN,
            max_x: 10.0,
            min_z: -5.0,
            max_z: 5.0,
        };
        assert!(validate_stage_map_config(&non_finite)
            .unwrap_err()
            .contains("finite"));

        let inverted = StageMapConfig {
            locked: true,
            min_x: 5.0,
            max_x: 5.0,
            min_z: -5.0,
            max_z: 5.0,
        };
        assert!(validate_stage_map_config(&inverted)
            .unwrap_err()
            .contains("min bounds"));
    }

    #[test]
    fn project_stage_object_validation_rejects_duplicate_ids_and_invalid_size() {
        let valid = StageObjectSummary {
            id: 1,
            label: "Front Truss".to_string(),
            kind: StageObjectKind::Truss,
            x: 0.0,
            z: -4.0,
            width: 12.0,
            depth: 0.4,
            rotation_deg: 0.0,
            color: Some("#55ccff".to_string()),
        };
        validate_project_stage_objects(&[valid.clone()]).unwrap();

        let duplicate_error =
            validate_project_stage_objects(&[valid.clone(), valid.clone()]).unwrap_err();
        assert!(duplicate_error.contains("duplicate stage object id 1"));

        let mut invalid_size = valid;
        invalid_size.id = 2;
        invalid_size.width = 0.0;
        let size_error = validate_project_stage_objects(&[invalid_size]).unwrap_err();
        assert!(size_error.contains("size must be greater than zero"));
    }

